final_template:
# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main"
  }
}

# Security group for the Application Load Balancer
resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Security group for ALB - accepts HTTP from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "alb"
  }
}

# Security group for backend EC2 instances behind the ALB
resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Security group for EC2 instances - accepts HTTP only from ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_alb"
  }
}

# Self-contained networking environment for testing

locals {
  vpc_cidr        = "10.0.0.0/16"
  public_cidr     = "10.0.1.0/24"
  private_cidr    = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-igw"
  }
}

# Public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "test-public-subnet"
  }
}

# Private subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "test-private-subnet"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-public-rt"
  }
}

# Route for all IPv4 traffic to IGW
resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Route for all IPv6 traffic to IGW
resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

# Associate public subnet with public route table
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "List of availability zones to create subnets in. Defaults to the first N availability zones where N is the length of subnet_cidrs."
  type        = list(string)
  default     = null
}

variable "subnet_cidrs" {
  description = "List of CIDR blocks for subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = var.availability_zones != null ? var.availability_zones : slice(
    data.aws_availability_zones.available.names,
    0,
    length(var.subnet_cidrs),
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count             = length(var.subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "main-subnet-${count.index}"
  }
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs authorized to assume this role via AWS Managed Grafana (e.g. the accounts where Grafana workspaces reside)"
  type        = list(string)
  default     = null
}

data "aws_partition" "current" {}
data "aws_region" "current" {}

# Build the trust policy statement with an optional condition on SourceAccount
locals {
  trust_statement = [
    {
      Sid    = "GrafanaAssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "grafana.amazonaws.com"
      }
      Action    = "sts:AssumeRole"
      Condition = var.monitoring_account_ids != null && length(var.monitoring_account_ids) > 0 ? {
        StringEquals = {
          "aws:SourceAccount" = var.monitoring_account_ids
        }
      } : null
    }
  ]
}

# IAM policy granting Grafana permissions to query Amazon Managed Service for Prometheus and CloudWatch
resource "aws_iam_policy" "grafana_query_policy" {
  name        = "GrafanaQueryPolicy"
  description = "IAM policy granting AWS Managed Grafana permissions to query Amazon Managed Service for Prometheus and Amazon CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PrometheusQuery"
        Effect = "Allow"
        Action = [
          "aps:QueryMetrics",
          "aps:GetSeries",
          "aps:GetLabels",
          "aps:GetMetricMetadata"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchRead"
        Effect = "Allow"
        Action = [
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM role that AWS Managed Grafana can assume to query AMP and CloudWatch
resource "aws_iam_role" "grafana_query_role" {
  name        = "GrafanaQueryRole"
  description = "IAM role that can be assumed by AWS Managed Grafana workspaces to query AMP and CloudWatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = local.trust_statement
  })

  tags = {
    Name = "GrafanaQueryRole"
  }
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "grafana_policy_attach" {
  role       = aws_iam_role.grafana_query_role.name
  policy_arn = aws_iam_policy.grafana_query_policy.arn
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 2)
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Public Subnets (one per AZ)
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Private Subnets (one per AZ)
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 2)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nat-eip"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Single NAT Gateway in the first public subnet
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "main-nat"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Public Route Table with route to Internet Gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Associate public subnets to the public route table
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table with route to NAT Gateway
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Associate private subnets to the private route table
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Group for containerized applications
resource "aws_security_group" "app" {
  name        = "app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 3000 from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 5432 from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "app-sg"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Service Discovery Private DNS Namespace
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "service.local"
  description = "Private DNS namespace for service discovery"
  vpc         = aws_vpc.main.id

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  aws_region  = data.aws_region.current.name
  aws_account = data.aws_caller_identity.current.account_id
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Cognito User Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = "main-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  auto_verified_attributes = ["email"]

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "email"
    required                 = true

    string_attribute_constraints {
      min_length = 3
      max_length = 256
    }
  }

  tags = {
    Name = "main-user-pool"
  }
}

# ---------------------------------------------------------------------------
# User Pool App Client
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "app" {
  name = "app-client"

  user_pool_id = aws_cognito_user_pool.main.id

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  generate_secret = false
}

# ---------------------------------------------------------------------------
# IAM Role for Authenticated Identities
# ---------------------------------------------------------------------------
resource "aws_iam_role" "authenticated" {
  name = "cognito-authenticated-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })

  tags = {
    Name = "cognito-authenticated-role"
  }
}

# ---------------------------------------------------------------------------
# IAM Policy for Cognito Sync and Mobile Analytics
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "cognito_sync_mobile_analytics" {
  name        = "cognito-sync-mobile-analytics-policy"
  description = "Allows authenticated Cognito identities to use Cognito Sync and Mobile Analytics"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-sync:ListDatasets",
          "cognito-sync:DescribeDataset",
          "cognito-sync:GetCognitoEvents",
          "cognito-sync:ListRecords",
          "cognito-sync:SubscribeToDataset",
          "cognito-sync:UnsubscribeFromDataset",
          "cognito-sync:UpdateRecords",
          "cognito-sync:SetCognitoEvents",
          "cognito-sync:QueryRecords"
        ]
        Resource = [
          "arn:aws:cognito-sync:${local.aws_region}:${local.aws_account}:identitypool/${aws_cognito_identity_pool.main.id}/identity/$${cognito-identity.amazonaws.com:sub}/dataset/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "mobileanalytics:GetSessionReports"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "authenticated_cognito_sync" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.cognito_sync_mobile_analytics.arn
}

# ---------------------------------------------------------------------------
# Cognito Identity Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "main-identity-pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  supported_login_providers = {}

  tags = {
    Name = "main-identity-pool"
  }
}

# ---------------------------------------------------------------------------
# Attach roles to the Identity Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated" = aws_iam_role.authenticated.arn
  }
}

locals {
  # Mutually exclusive key type flags
  create_key        = var.create_standard_key || var.create_external_key || var.create_replica_key || var.create_replica_external_key
  is_external       = var.create_external_key || var.create_replica_external_key
  is_replica        = var.create_replica_key || var.create_replica_external_key
  is_standard       = var.create_standard_key
  key_material_supplied = local.is_external && var.key_material_base64 != null

  # Determine key spec and usage with defaults
  key_spec  = var.key_spec != null ? var.key_spec : "SYMMETRIC_DEFAULT"
  key_usage = var.key_usage != null ? var.key_usage : "ENCRYPT_DECRYPT"

  # Policy override handling
  use_custom_policy = var.override_policy_document != null
}

# Data sources for static provider metadata
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -------------------------------------------------------------------
# Key Policy Document Generation
# -------------------------------------------------------------------

data "aws_iam_policy_document" "root_access" {
  count = local.create_key && !local.use_custom_policy ? 1 : 0

  statement {
    sid       = "EnableIAMRootAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

data "aws_iam_policy_document" "key_owners" {
  count = local.create_key && !local.use_custom_policy && length(var.key_owner_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowKeyOwners"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.key_owner_arns
    }
  }
}

data "aws_iam_policy_document" "key_admins" {
  count = local.create_key && !local.use_custom_policy && length(var.key_admin_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowKeyAdmins"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.key_admin_arns
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:RotateKeyOnDemand",
      "kms:ImportKeyMaterial",
      "kms:DeleteImportedKeyMaterial",
    ]
  }
}

data "aws_iam_policy_document" "key_users" {
  count = local.create_key && !local.use_custom_policy && length(var.key_user_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowStandardKeyUsers"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.key_user_arns
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RetireGrant",
    ]
  }
}

data "aws_iam_policy_document" "service_users" {
  count = local.create_key && !local.use_custom_policy && length(var.service_user_service_names) > 0 ? 1 : 0

  statement {
    sid       = "AllowServiceAccess"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [for s in var.service_user_service_names : "${s}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
  }
}

data "aws_iam_policy_document" "autoscaling" {
  count = local.create_key && !local.use_custom_policy && length(var.autoscaling_role_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowEC2AutoScaling"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.autoscaling_role_arns
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["ec2.${data.aws_region.current.region}.amazonaws.com"]
    }
  }
}

# Symmetric cryptographic users
data "aws_iam_policy_document" "symmetric_users" {
  count = local.create_key && !local.use_custom_policy && length(var.symmetric_user_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowSymmetricCryptoUsers"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.symmetric_user_arns
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GenerateDataKeyPair",
      "kms:GenerateDataKeyPairWithoutPlaintext",
    ]
  }
}

# HMAC cryptographic users
data "aws_iam_policy_document" "hmac_users" {
  count = local.create_key && !local.use_custom_policy && length(var.hmac_user_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowHMACCryptoUsers"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.hmac_user_arns
    }

    actions = [
      "kms:GenerateMac",
      "kms:VerifyMac",
    ]
  }
}

# Asymmetric public encryption users
data "aws_iam_policy_document" "asymmetric_encrypt_users" {
  count = local.create_key && !local.use_custom_policy && length(var.asymmetric_encrypt_user_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowAsymmetricEncryptUsers"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.asymmetric_encrypt_user_arns
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GetPublicKey",
    ]
  }
}

# Asymmetric sign/verify users
data "aws_iam_policy_document" "asymmetric_sign_verify_users" {
  count = local.create_key && !local.use_custom_policy && length(var.asymmetric_sign_verify_user_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowAsymmetricSignVerifyUsers"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.asymmetric_sign_verify_user_arns
    }

    actions = [
      "kms:Sign",
      "kms:Verify",
      "kms:GetPublicKey",
    ]
  }
}

# Route 53 DNSSEC signing
data "aws_iam_policy_document" "route53_dnssec" {
  count = local.create_key && !local.use_custom_policy && length(var.route53_dnssec_service_arns) > 0 ? 1 : 0

  statement {
    sid       = "AllowRoute53DNSSEC"
    effect    = "Allow"
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.route53_dnssec_service_arns
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GetPublicKey",
      "kms:Sign",
      "kms:Verify",
    ]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["dnssec.route53.${data.aws_region.current.region}.amazonaws.com"]
    }
  }
}

# Custom policy statements
data "aws_iam_policy_document" "custom_statements_doc" {
  count = local.create_key && !local.use_custom_policy && length(var.custom_statements) > 0 ? length(var.custom_statements) : 0

  statement {
    sid       = try(var.custom_statements[count.index].sid, "CustomStatement${count.index + 1}")
    effect    = var.custom_statements[count.index].effect
    actions   = var.custom_statements[count.index].actions
    resources = try(var.custom_statements[count.index].resources, ["*"])

    dynamic "principals" {
      for_each = var.custom_statements[count.index].principals
      content {
        type        = principals.value.type
        identifiers = principals.value.identifiers
      }
    }

    dynamic "condition" {
      for_each = try(var.custom_statements[count.index].conditions, [])
      content {
        test     = condition.value.test
        variable = condition.value.variable
        values   = condition.value.values
      }
    }
  }
}

# Combine all policy documents (non-override path)
locals {
  policy_source_documents = local.create_key && !local.use_custom_policy ? compact(
    concat(
      [try(data.aws_iam_policy_document.root_access[0].json, "")],
      [try(data.aws_iam_policy_document.key_owners[0].json, "")],
      [try(data.aws_iam_policy_document.key_admins[0].json, "")],
      [try(data.aws_iam_policy_document.key_users[0].json, "")],
      [try(data.aws_iam_policy_document.service_users[0].json, "")],
      [try(data.aws_iam_policy_document.autoscaling[0].json, "")],
      [try(data.aws_iam_policy_document.symmetric_users[0].json, "")],
      [try(data.aws_iam_policy_document.hmac_users[0].json, "")],
      [try(data.aws_iam_policy_document.asymmetric_encrypt_users[0].json, "")],
      [try(data.aws_iam_policy_document.asymmetric_sign_verify_users[0].json, "")],
      [try(data.aws_iam_policy_document.route53_dnssec[0].json, "")],
      [for d in data.aws_iam_policy_document.custom_statements_doc : d.json],
    )
  ) : []
}

data "aws_iam_policy_document" "combined" {
  count = local.create_key && !local.use_custom_policy ? 1 : 0

  source_policy_documents = local.policy_source_documents
}

locals {
  key_policy_json = local.use_custom_policy ? var.override_policy_document : (
    local.create_key ? data.aws_iam_policy_document.combined[0].json : null
  )
}

# -------------------------------------------------------------------
# KMS Key Resources
# -------------------------------------------------------------------

# Standard or external key (non-replica)
resource "aws_kms_key" "this" {
  count = local.create_key && !local.is_replica ? 1 : 0

  description                         = var.description
  key_usage                           = local.key_usage
  customer_master_key_spec            = local.key_spec
  policy                              = local.key_policy_json
  deletion_window_in_days             = var.deletion_window_in_days
  bypass_policy_lockout_safety_check  = var.bypass_policy_lockout_safety_check
  is_enabled                          = var.is_enabled
  multi_region                        = var.multi_region
  tags                                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Replica key (standard or external)
resource "aws_kms_replica_key" "this" {
  count = local.create_key && local.is_replica ? 1 : 0

  primary_key_arn                     = var.primary_key_arn
  description                         = var.description
  policy                              = local.key_policy_json
  deletion_window_in_days             = var.deletion_window_in_days
  bypass_policy_lockout_safety_check  = var.bypass_policy_lockout_safety_check
  tags                                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -------------------------------------------------------------------
# KMS Aliases
# -------------------------------------------------------------------

resource "aws_kms_alias" "this" {
  for_each = local.create_key ? var.aliases : {}

  name          = "alias/${try(each.value.name, null)}"
  name_prefix   = try(each.value.name_prefix, null) != null ? "alias/${each.value.name_prefix}" : null
  target_key_id = local.is_replica ? aws_kms_replica_key.this[0].key_id : aws_kms_key.this[0].key_id
}

# -------------------------------------------------------------------
# KMS Grants
# -------------------------------------------------------------------

resource "aws_kms_grant" "this" {
  for_each = local.create_key ? var.grants : {}

  key_id  = local.is_replica ? aws_kms_replica_key.this[0].key_id : aws_kms_key.this[0].key_id
  name    = try(each.value.name, null)
  retire_on_delete = try(each.value.retire_on_delete, true)

  grantee_principal   = each.value.grantee_principal
  retiring_principal  = try(each.value.retiring_principal, null)
  operations          = each.value.allowed_operations

  constraints {
    encryption_context_subset = try(each.value.encryption_context_subset, null)
    encryption_context_equals = try(each.value.encryption_context_equality, null)
  }
}

# -------------------------------------------------------------------
# Outputs
# -------------------------------------------------------------------

output "kms_key_id" {
  description = "The globally unique identifier for the KMS key"
  value       = local.create_key ? (local.is_replica ? aws_kms_replica_key.this[0].key_id : aws_kms_key.this[0].key_id) : null
}

output "kms_key_arn" {
  description = "The Amazon Resource Name (ARN) of the KMS key"
  value       = local.create_key ? (local.is_replica ? aws_kms_replica_key.this[0].arn : aws_kms_key.this[0].arn) : null
}

output "kms_key_policy" {
  description = "The key policy JSON document applied to the KMS key"
  value       = local.key_policy_json
}

output "kms_alias_names" {
  description = "Map of alias names created"
  value       = { for k, a in aws_kms_alias.this : k => a.name }
}

output "kms_grant_ids" {
  description = "Map of grant IDs created"
  value       = { for k, g in aws_kms_grant.this : k => g.grant_id }
}

# -------------------------------------------------------------------
# Variables
# -------------------------------------------------------------------

# Mutually exclusive key creation flags
variable "create_standard_key" {
  description = "Create a standard KMS key with AWS-provided key material"
  type        = bool
  default     = false
}

variable "create_external_key" {
  description = "Create a KMS key with imported external key material"
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Create a multi-region replica key referencing a primary key ARN"
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a multi-region replica external key with custom key material and primary external key ARN"
  type        = bool
  default     = false
}

# Key configuration
variable "key_spec" {
  description = "Key specification (SYMMETRIC_DEFAULT, RSA_2048, RSA_3072, RSA_4096, ECC_NIST_P256, ECC_NIST_P384, ECC_NIST_P521, ECC_SECG_P256K1, HMAC_256, HMAC_384, HMAC_512)"
  type        = string
  default     = null
}

variable "key_usage" {
  description = "Key usage (ENCRYPT_DECRYPT, SIGN_VERIFY, GENERATE_VERIFY_MAC)"
  type        = string
  default     = null
}

variable "description" {
  description = "Description of the KMS key"
  type        = string
  default     = "KMS key managed by Terraform"
}

variable "deletion_window_in_days" {
  description = "Waiting period before key deletion (7-30 days)"
  type        = number
  default     = 30
}

variable "bypass_policy_lockout_safety_check" {
  description = "Bypass the key policy lockout safety check"
  type        = bool
  default     = false
}

variable "is_enabled" {
  description = "Whether the KMS key is enabled"
  type        = bool
  default     = true
}

variable "enable_key_rotation" {
  description = "Enable automatic annual key rotation (not applicable to asymmetric or external keys)"
  type        = bool
  default     = false
}

variable "multi_region" {
  description = "Indicates whether the KMS key is a multi-region key (applicable only to non-replica keys)"
  type        = bool
  default     = false
}

# External key material
variable "key_material_base64" {
  description = "Base64-encoded key material for external keys"
  type        = string
  default     = null
  sensitive   = true
}

variable "key_material_valid_to" {
  description = "Date and time after which the key material expires"
  type        = string
  default     = null
}

variable "key_material_expiration_model" {
  description = "Expiration model for key material (KEY_MATERIAL_EXPIRES or KEY_MATERIAL_DOES_NOT_EXPIRE)"
  type        = string
  default     = null
}

# Replica key
variable "primary_key_arn" {
  description = "ARN of the primary multi-region KMS key for replica keys"
  type        = string
  default     = null
}

# Policy role inputs
variable "key_owner_arns" {
  description = "List of IAM ARNs with full KMS key ownership"
  type        = list(string)
  default     = []
}

variable "key_admin_arns" {
  description = "List of IAM ARNs with key administrative permissions"
  type        = list(string)
  default     = []
}

variable "key_user_arns" {
  description = "List of IAM ARNs with standard encrypt/decrypt user permissions"
  type        = list(string)
  default     = []
}

variable "service_user_service_names" {
  description = "List of AWS service names (e.g., 's3', 'sqs', 'lambda') to grant KMS access"
  type        = list(string)
  default     = []
}

variable "autoscaling_role_arns" {
  description = "List of IAM role ARNs for EC2 Auto Scaling KMS access via kms:ViaService"
  type        = list(string)
  default     = []
}

variable "symmetric_user_arns" {
  description = "List of IAM ARNs for symmetric cryptographic operations (Encrypt, Decrypt, GenerateDataKey, etc.)"
  type        = list(string)
  default     = []
}

variable "hmac_user_arns" {
  description = "List of IAM ARNs for HMAC operations (GenerateMac, VerifyMac)"
  type        = list(string)
  default     = []
}

variable "asymmetric_encrypt_user_arns" {
  description = "List of IAM ARNs for asymmetric public encryption operations"
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_user_arns" {
  description = "List of IAM ARNs for asymmetric sign/verify operations"
  type        = list(string)
  default     = []
}

variable "route53_dnssec_service_arns" {
  description = "List of IAM role ARNs for Route 53 DNSSEC signing KMS access via kms:ViaService"
  type        = list(string)
  default     = []
}

variable "custom_statements" {
  description = "List of custom IAM policy statements to add to the key policy"
  type = list(object({
    sid    = optional(string)
    effect = string
    actions = list(string)
    principals = list(object({
      type        = string
      identifiers = list(string)
    }))
    resources   = optional(list(string))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "override_policy_document" {
  description = "Complete JSON policy document to use instead of the auto-generated policy"
  type        = string
  default     = null
}

# Aliases
variable "aliases" {
  description = "Map of alias configurations. Each entry can have 'name' (exact) or 'name_prefix' (prefix)."
  type = map(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = {}
}

# Grants
variable "grants" {
  description = "Map of KMS grant configurations"
  type = map(object({
    grantee_principal           = string
    allowed_operations          = list(string)
    retiring_principal          = optional(string)
    encryption_context_subset   = optional(map(string))
    encryption_context_equality = optional(map(string))
    name                        = optional(string)
    retire_on_delete            = optional(bool)
  }))
  default = {}
}

# Tags
variable "tags" {
  description = "Tags to apply to the KMS key"
  type        = map(string)
  default     = {}
}

# -------------------------------------------------------------------
# Validation
# -------------------------------------------------------------------

resource "terraform_data" "key_type_validation" {
  lifecycle {
    precondition {
      condition     = (var.create_standard_key ? 1 : 0) + (var.create_external_key ? 1 : 0) + (var.create_replica_key ? 1 : 0) + (var.create_replica_external_key ? 1 : 0) <= 1
      error_message = "Only one of create_standard_key, create_external_key, create_replica_key, or create_replica_external_key may be set to true."
    }
  }
}

resource "terraform_data" "external_key_material_validation" {
  lifecycle {
    precondition {
      condition     = !var.create_external_key || var.key_material_base64 != null
      error_message = "key_material_base64 is required when create_external_key is true."
    }
  }
}

resource "terraform_data" "replica_key_arn_validation" {
  lifecycle {
    precondition {
      condition     = !var.create_replica_key || var.primary_key_arn != null
      error_message = "primary_key_arn is required when create_replica_key is true."
    }
  }
}

resource "terraform_data" "replica_external_arn_validation" {
  lifecycle {
    precondition {
      condition     = !var.create_replica_external_key || var.primary_key_arn != null
      error_message = "primary_key_arn is required when create_replica_external_key is true."
    }
  }
}

resource "terraform_data" "replica_external_material_validation" {
  lifecycle {
    precondition {
      condition     = !var.create_replica_external_key || var.key_material_base64 != null
      error_message = "key_material_base64 is required when create_replica_external_key is true."
    }
  }
}

resource "terraform_data" "alias_name_or_prefix_validation" {
  lifecycle {
    precondition {
      condition = alltrue([
        for k, a in var.aliases : (a.name != null && a.name_prefix == null) || (a.name == null && a.name_prefix != null)
      ])
      error_message = "Each alias must have exactly one of 'name' or 'name_prefix' set."
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name = "eks-multi-cluster-vpc"

  tags = {
    Blueprint  = local.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name = local.vpc_name
  cidr = "10.0.0.0/16"

  azs = data.aws_availability_zones.available.names

  private_subnets = ["10.0.0.0/20", "10.0.16.0/20", "10.0.32.0/20"]
  public_subnets  = ["10.0.48.0/24", "10.0.49.0/24", "10.0.50.0/24"]

  enable_nat_gateway     = true
  single_nat_gateway     = true
  enable_vpn_gateway     = false
  enable_dns_hostnames   = true
  enable_dns_support     = true

  tags = local.tags

  public_subnet_tags = merge(local.tags, {
    "kubernetes.io/role/elb" = 1
  })

  private_subnet_tags = merge(local.tags, {
    "kubernetes.io/role/internal-elb" = 1
  })
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster 1 enabling cross-cluster communication with cluster 2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster1_additional_sg"
  })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster 2 enabling cross-cluster communication with cluster 1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster2_additional_sg"
  })
}

# Ingress rule on cluster1 SG: allow all traffic from cluster2 SG
resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id

  description = "Allow all inbound traffic from cluster2 additional SG"
}

# Egress rule on cluster1 SG: allow all traffic to cluster2 SG
resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id

  description = "Allow all outbound traffic to cluster2 additional SG"
}

# Ingress rule on cluster2 SG: allow all traffic from cluster1 SG
resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id

  description = "Allow all inbound traffic from cluster1 additional SG"
}

# Egress rule on cluster2 SG: allow all traffic to cluster1 SG
resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id

  description = "Allow all outbound traffic to cluster1 additional SG"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes that can be used to alias users"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes that are auto-verified"
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message (code-based)"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject (code-based)"
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "MFA configuration (OFF, ON, OPTIONAL)"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message"
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Verification message template by link"
  type = object({
    default_email_option  = optional(string, "CONFIRM_WITH_LINK")
    email_message_by_link = optional(string)
    email_subject_by_link = optional(string)
  })
  default = {}
}

variable "sms_configuration" {
  description = "SMS configuration map"
  type = object({
    external_id    = optional(string, "")
    sns_caller_arn = optional(string, "")
  })
  default = {}
}

variable "recovery_mechanisms" {
  description = "Recovery mechanisms with priority"
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_email"
      priority = 2
    },
    {
      name     = "verified_phone_number"
      priority = 1
    }
  ]
}

variable "invite_message_template" {
  description = "Invite message template"
  type = object({
    email_message = optional(string)
    email_subject = optional(string)
    sms_message   = optional(string)
  })
  default = {}
}

variable "admin_create_user_only" {
  description = "Only allow admin to create users"
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Enable software token MFA"
  type        = bool
  default     = true
}

variable "case_sensitivity" {
  description = "Case sensitivity for username (null = use default)"
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Dynamic device configuration parameters"
  type = object({
    challenge_required_on_new_device      = optional(bool)
    device_only_remembered_on_user_prompt = optional(bool)
  })
  default = null
}

variable "lambda_triggers" {
  description = "Optional Lambda trigger configuration map"
  type = any
  default = {}
}

variable "custom_schema_attributes" {
  description = "Custom schema definitions"
  type = list(object({
    name                = string
    attribute_data_type = optional(string, "String")
    mutable             = optional(bool, true)
    required            = optional(bool, false)
    developer_only      = optional(bool, false)
    string_attribute_constraints = optional(object({
      min_length = optional(number)
      max_length = optional(number)
    }))
    number_attribute_constraints = optional(object({
      min_value = optional(number)
      max_value = optional(number)
    }))
  }))
  default = [
    {
      name       = "email"
      mutable    = true
      required   = true
    }
  ]
}

variable "client_apps" {
  description = "List of client app configurations"
  type = list(object({
    name                              = string
    generate_secret                   = optional(bool, false)
    access_token_validity             = optional(number, 120)
    id_token_validity                 = optional(number, 120)
    refresh_token_validity            = optional(number, 7)
    access_token_validity_unit        = optional(string, "minutes")
    id_token_validity_unit            = optional(string, "minutes")
    refresh_token_validity_unit       = optional(string, "days")
    allowed_oauth_flows_user_pool_client = optional(bool, false)
    token_revocation                  = optional(bool, true)
    explicit_auth_flows               = optional(list(string), ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"])
    prevent_user_existence_errors     = optional(string, "LEGACY")
    read_attributes                   = optional(list(string))
    write_attributes                  = optional(list(string))
    callback_urls                     = optional(list(string))
    logout_urls                       = optional(list(string))
    allowed_oauth_flows               = optional(list(string))
    allowed_oauth_scopes              = optional(list(string))
    supported_identity_providers      = optional(list(string))
  }))
  default = []
}

variable "group_name" {
  description = "Cognito user group name (empty to skip)"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the user group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "IAM role ARN for the group"
  type        = string
  default     = null
}

variable "domain" {
  description = "Cognito User Pool domain (empty to skip)"
  type        = string
  default     = ""
}

variable "acm_certificate_arn" {
  description = "ACM certificate ARN for the custom domain"
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Whether to create a Route53 alias A-record"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route53 zone ID for the alias record"
  type        = string
  default     = null
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  # Conditionally enable SMS configuration only when both values are non-empty
  enable_sms_config = (
    try(var.sms_configuration.external_id, "") != "" &&
    try(var.sms_configuration.sns_caller_arn, "") != ""
  )

  # Conditionally enable username case sensitivity configuration
  enable_case_sensitivity = var.case_sensitivity != null

  # Conditionally enable device configuration
  enable_device_config = var.device_configuration != null

  # Conditionally enable groups
  enable_group = var.group_name != ""

  # Conditionally enable domain
  enable_domain = var.domain != ""

  # Conditionally enable Route53 record
  enable_route53 = var.create_route53_record && var.route53_zone_id != null

  # Fixed CloudFront zone ID for Cognito alias records
  cloudfront_zone_id = "Z2FDTNDATAQYW2"
}

# ---------------------------------------------------------------------------
# Cognito User Pool
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name                       = var.pool_name
  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  # Verification message template by link
  dynamic "verification_message_template" {
    for_each = length(keys(var.verification_message_template)) > 0 ? [var.verification_message_template] : []
    content {
      default_email_option  = try(verification_message_template.value.default_email_option, "CONFIRM_WITH_LINK")
      email_message_by_link = try(verification_message_template.value.email_message_by_link, null)
      email_subject_by_link = try(verification_message_template.value.email_subject_by_link, null)
    }
  }

  # SMS configuration - only when both external_id and sns_caller_arn are non-empty
  dynamic "sms_configuration" {
    for_each = local.enable_sms_config ? [1] : []
    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  # Account recovery settings
  dynamic "account_recovery_setting" {
    for_each = length(var.recovery_mechanisms) > 0 ? [1] : []
    content {
      dynamic "recovery_mechanism" {
        for_each = var.recovery_mechanisms
        content {
          name     = recovery_mechanism.value.name
          priority = recovery_mechanism.value.priority
        }
      }
    }
  }

  # Admin create user config
  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    dynamic "invite_message_template" {
      for_each = length(keys(var.invite_message_template)) > 0 ? [var.invite_message_template] : []
      content {
        email_message = try(invite_message_template.value.email_message, null)
        email_subject = try(invite_message_template.value.email_subject, null)
        sms_message   = try(invite_message_template.value.sms_message, null)
      }
    }
  }

  # Software token MFA configuration
  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = true
    }
  }

  # Username configuration (case sensitivity)
  dynamic "username_configuration" {
    for_each = local.enable_case_sensitivity ? [1] : []
    content {
      case_sensitive = var.case_sensitivity
    }
  }

  # Device configuration
  dynamic "device_configuration" {
    for_each = local.enable_device_config ? [1] : []
    content {
      challenge_required_on_new_device      = try(var.device_configuration.challenge_required_on_new_device, null)
      device_only_remembered_on_user_prompt = try(var.device_configuration.device_only_remembered_on_user_prompt, null)
    }
  }

  # Lambda triggers
  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_triggers)) > 0 ? [var.lambda_triggers] : []
    content {
      create_auth_challenge          = try(lambda_config.value.create_auth_challenge, null)
      custom_message                 = try(lambda_config.value.custom_message, null)
      define_auth_challenge          = try(lambda_config.value.define_auth_challenge, null)
      post_authentication            = try(lambda_config.value.post_authentication, null)
      post_confirmation              = try(lambda_config.value.post_confirmation, null)
      pre_authentication             = try(lambda_config.value.pre_authentication, null)
      pre_sign_up                    = try(lambda_config.value.pre_sign_up, null)
      pre_token_generation           = try(lambda_config.value.pre_token_generation, null)
      user_migration                 = try(lambda_config.value.user_migration, null)
      verify_auth_challenge_response = try(lambda_config.value.verify_auth_challenge_response, null)

      dynamic "custom_email_sender" {
        for_each = try(lambda_config.value.custom_email_sender, null) != null ? [lambda_config.value.custom_email_sender] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = try(custom_email_sender.value.lambda_version, "V1_0")
        }
      }

      dynamic "custom_sms_sender" {
        for_each = try(lambda_config.value.custom_sms_sender, null) != null ? [lambda_config.value.custom_sms_sender] : []
        content {
          lambda_arn     = custom_sms_sender.value.lambda_arn
          lambda_version = try(custom_sms_sender.value.lambda_version, "V1_0")
        }
      }

      dynamic "pre_token_generation_config" {
        for_each = try(lambda_config.value.pre_token_generation_config, null) != null ? [lambda_config.value.pre_token_generation_config] : []
        content {
          lambda_arn     = pre_token_generation_config.value.lambda_arn
          lambda_version = try(pre_token_generation_config.value.lambda_version, "V1_0")
        }
      }
    }
  }

  # Schema attributes
  dynamic "schema" {
    for_each = var.custom_schema_attributes
    content {
      name                = schema.value.name
      attribute_data_type = try(schema.value.attribute_data_type, "String")
      mutable             = try(schema.value.mutable, true)
      required            = try(schema.value.required, false)
      developer_only_attribute = try(schema.value.developer_only, false)

      dynamic "string_attribute_constraints" {
        for_each = try(schema.value.string_attribute_constraints, null) != null ? [schema.value.string_attribute_constraints] : []
        content {
          min_length = try(string_attribute_constraints.value.min_length, null)
          max_length = try(string_attribute_constraints.value.max_length, null)
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = try(schema.value.number_attribute_constraints, null) != null ? [schema.value.number_attribute_constraints] : []
        content {
          min_value = try(number_attribute_constraints.value.min_value, null)
          max_value = try(number_attribute_constraints.value.max_value, null)
        }
      }
    }
  }

  # Ignore changes to estimated_number_of_users (computed attribute)
  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Cognito User Pool Clients (dynamic iteration)
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool_client" "clients" {
  for_each = { for idx, app in var.client_apps : idx => app }

  name                                 = each.value.name
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = try(each.value.generate_secret, false)
  access_token_validity                = try(each.value.access_token_validity, 120)
  id_token_validity                    = try(each.value.id_token_validity, 120)
  refresh_token_validity               = try(each.value.refresh_token_validity, 7)
  allowed_oauth_flows_user_pool_client = try(each.value.allowed_oauth_flows_user_pool_client, false)
  enable_token_revocation               = try(each.value.token_revocation, true)
  explicit_auth_flows                  = try(each.value.explicit_auth_flows, ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"])
  prevent_user_existence_errors        = try(each.value.prevent_user_existence_errors, "LEGACY")
  read_attributes                      = try(each.value.read_attributes, null)
  write_attributes                     = try(each.value.write_attributes, null)
  callback_urls                        = try(each.value.callback_urls, null)
  logout_urls                          = try(each.value.logout_urls, null)
  allowed_oauth_flows                  = try(each.value.allowed_oauth_flows, null)
  allowed_oauth_scopes                 = try(each.value.allowed_oauth_scopes, null)
  supported_identity_providers         = try(each.value.supported_identity_providers, null)

  token_validity_units {
    access_token  = try(each.value.access_token_validity_unit, "minutes")
    id_token      = try(each.value.id_token_validity_unit, "minutes")
    refresh_token = try(each.value.refresh_token_validity_unit, "days")
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Cognito User Group (conditional)
# ---------------------------------------------------------------------------

resource "aws_cognito_user_group" "group" {
  count = local.enable_group ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.main.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != null ? var.group_role_arn : null

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Cognito User Pool Domain (conditional)
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool_domain" "domain" {
  count = local.enable_domain ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.main.id
  certificate_arn = var.acm_certificate_arn != null ? var.acm_certificate_arn : null

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Route53 Alias A-Record (conditional)
# ---------------------------------------------------------------------------

resource "aws_route53_record" "cognito_alias" {
  count = local.enable_route53 ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = local.cloudfront_zone_id
    evaluate_target_health = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier" {
  description = "Name identifier for the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  description = "Public IPv4 pool name for the Elastic IP"
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

variable "subnet_a_map_public_ip_on_launch" {
  description = "Assign public IP to instances launched in Subnet A"
  type        = bool
  default     = false
}

variable "subnet_b_map_public_ip_on_launch" {
  description = "Assign public IP to instances launched in Subnet B"
  type        = bool
  default     = false
}

variable "subnet_c_map_public_ip_on_launch" {
  description = "Assign public IP to instances launched in Subnet C"
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool_name

  tags = {
    Name = var.nat_gateway_name
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Default security group with egress restricted to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr_block]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

# ---------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)."
  type        = bool
  default     = true
  nullable    = false
}

variable "id" {
  description = "ID of an existing Transit Gateway to look up when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag value used for the Transit Gateway and as a fallback for route table naming and RAM share naming."
  type        = string
  default     = null
}

variable "description" {
  description = "Description of the Transit Gateway."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session."
  type        = number
  default     = 65200
  nullable    = false
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept cross-account attachment requests (enable or disable)."
  type        = string
  default     = "disable"
  nullable    = false
}

variable "dns_support" {
  description = "DNS support for the Transit Gateway (enable or disable)."
  type        = string
  default     = "enable"
  nullable    = false
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support for the Transit Gateway (enable or disable)."
  type        = string
  default     = "enable"
  nullable    = false
}

variable "transit_gateway_cidr_blocks" {
  description = "List of valid IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []
  nullable    = false

  validation {
    condition = alltrue([
      for c in var.transit_gateway_cidr_blocks :
      try(can(cidrnetmask(c)), false) ||
      can(regex("^([0-9a-fA-F]{0,4}:){1,7}[0-9a-fA-F]{0,4}/[0-9]{1,3}$", c))
    ])
    error_message = "All entries in transit_gateway_cidr_blocks must be valid IPv4 or IPv6 CIDR notation (e.g. 10.0.0.0/8 or 2001:db8::/32)."
  }
}

variable "tags" {
  description = "Map of tags to apply to all resources."
  type        = map(string)
  default     = {}
  nullable    = false
}

variable "route_tables" {
  description = <<-EOT
    Map of Transit Gateway route tables. Each key acts as the logical identifier.
    - create (optional bool, default true): true provisions a new route table; false looks up an existing one.
    - name   (optional string): value for the Name tag / filter. Falls back to the item key or the global name.
    - tags   (optional map(string)): additional tags merged with global tags.
  EOT
  type = map(object({
    create = optional(bool, true)
    name   = optional(string)
    tags   = optional(map(string), {})
  }))
  default  = {}
  nullable = false
}

variable "shared_principals" {
  description = <<-EOT
    Map of AWS principals (account IDs or ARNs) to share the Transit Gateway with via AWS RAM.
    When non-empty, a RAM resource share is created and the Transit Gateway is associated with it.
    Keys are logical names, values are principal identifiers.
  EOT
  type        = map(string)
  default     = {}
  nullable    = false
}

variable "ram_resource_share_name" {
  description = "Explicit name for the RAM resource share. Defaults to the Transit Gateway name tag when null."
  type        = string
  default     = null
}

variable "allow_external_principals" {
  description = "Whether to allow external principals (outside the AWS organization) in the RAM resource share."
  type        = bool
  default     = true
  nullable    = false
}

# ---------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------

locals {
  # Whether we are responsible for creating the Transit Gateway resource
  create_tgw = var.create

  # Resolve the Transit Gateway ID and ARN (created or looked up)
  tgw_id  = local.create_tgw ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  tgw_arn = local.create_tgw ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  # Primary name tag for the main resource
  name_tag = var.name != null ? var.name : "tgw-main"

  # RAM share name: explicit variable or fallback to the main resource name
  ram_share_name = var.ram_resource_share_name != null ? var.ram_resource_share_name : local.name_tag

  # Whether a RAM resource share should be provisioned
  create_ram = length(var.shared_principals) > 0
}

# ---------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------

# Look up an existing Transit Gateway when create is false
data "aws_ec2_transit_gateway" "this" {
  count = local.create_tgw ? 0 : 1

  # If an explicit id is provided, use it; otherwise leave unset and rely on filters
  id = var.id != null ? var.id : null

  dynamic "filter" {
    for_each = var.id == null ? [1] : []
    content {
      name   = "tag:Name"
      values = var.name != null ? [var.name] : ["*"]
    }
  }
}

# Look up existing route tables for items where create is false
data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.name != null ? each.value.name : each.key]
  }
}

# ---------------------------------------------------------------------------
# TRANSIT GATEWAY
# ---------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "this" {
  count = local.create_tgw ? 1 : 0

  amazon_side_asn                     = var.amazon_side_asn
  auto_accept_shared_attachments      = var.auto_accept_shared_attachments
  dns_support                         = var.dns_support
  vpn_ecmp_support                    = var.vpn_ecmp_support
  default_route_table_association     = "disable"
  default_route_table_propagation     = "disable"
  transit_gateway_cidr_blocks         = length(var.transit_gateway_cidr_blocks) > 0 ? var.transit_gateway_cidr_blocks : null
  description                         = var.description

  tags = merge(var.tags, {
    Name = local.name_tag
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# TRANSIT GATEWAY ROUTE TABLES
# ---------------------------------------------------------------------------

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.tgw_id

  tags = merge(var.tags, each.value.tags, {
    Name = each.value.name != null ? each.value.name : local.name_tag
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# RAM RESOURCE SHARING
# ---------------------------------------------------------------------------

resource "aws_ram_resource_share" "this" {
  count = local.create_ram ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = var.allow_external_principals

  tags = merge(var.tags, {
    Name = local.ram_share_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_resource_association" "this" {
  count = local.create_ram ? 1 : 0

  resource_share_arn = aws_ram_resource_share.this[0].arn
  resource_arn       = local.tgw_arn
}

resource "aws_ram_principal_association" "this" {
  for_each = local.create_ram ? var.shared_principals : {}

  resource_share_arn = aws_ram_resource_share.this[0].arn
  principal          = each.value
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "bucket_name" {
  description = "Optional name for the bucket. Uses a generated name if null."
  type        = string
  default     = null
}

variable "prefix" {
  description = "If true, appends an extra random string suffix to the bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Request payer configuration. Defaults to BucketOwner."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Enable server-side encryption."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of a KMS key for encryption. If empty, a rotating customer-managed KMS key is created."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete for versioned bucket."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply to the bucket."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to the bucket and related resources."
  type        = map(string)
  default     = {}
}

variable "policy" {
  description = "JSON policy document for the bucket."
  type        = string
  default     = null
}

variable "grants" {
  description = "Grants for the bucket ACL."
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = []
}

variable "transfer_acceleration_status" {
  description = "Transfer acceleration status (Enabled or Suspended)."
  type        = string
  default     = null
}

variable "logging_target_bucket" {
  description = "Target bucket for server access logs."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for server access logs."
  type        = string
  default     = null
}

variable "website_index_document" {
  description = "Index document for website hosting."
  type        = string
  default     = null
}

variable "website_error_document" {
  description = "Error document for website hosting."
  type        = string
  default     = null
}

variable "website_redirect_all" {
  description = "Redirect all requests to another domain."
  type = object({
    host_name = string
    protocol  = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "CORS rules for the bucket."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Lifecycle rules for the bucket."
  type = list(object({
    id                                     = optional(string)
    status                                 = optional(string, "Enabled")
    prefix                                 = optional(string)
    abort_incomplete_multipart_upload_days = optional(number)
    filter = optional(object({
      prefix                   = optional(string)
      tag                      = optional(object({
        key   = string
        value = string
      }))
      tags                     = optional(map(string))
      object_size_greater_than = optional(number)
      object_size_less_than    = optional(number)
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transition = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
  }))
  default = []
}

variable "replication_rules" {
  description = "Replication rules for cross-region replication."
  type = list(object({
    id                              = optional(string)
    status                          = optional(string, "Enabled")
    priority                        = optional(number)
    prefix                          = optional(string)
    destination_bucket_arn          = string
    destination_storage_class       = optional(string)
    delete_marker_replication       = optional(string, "Disabled")
    replicate_kms_encrypted_objects = optional(string, "Disabled")
    access_control_translation = optional(object({
      owner = string
    }))
    encryption_configuration = optional(object({
      replica_kms_key_id = string
    }))
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
    filter = optional(object({
      prefix = optional(string)
      tag    = optional(object({
        key   = string
        value = string
      }))
      tags   = optional(map(string))
    }))
  }))
  default = []
}

variable "replication_role" {
  description = "ARN of an IAM role for replication. If empty, a role is created automatically."
  type        = string
  default     = ""
}

variable "object_lock_configuration" {
  description = "Object lock configuration for the bucket (mode, days, or years)."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  # Resolve the effective bucket name
  base_name     = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_suffix.hex}"
  bucket_name   = var.prefix ? "${local.base_name}-${random_id.prefix_suffix[0].hex}" : local.base_name

  # Encryption key ARN
  kms_key_arn = var.kms_key != "" ? var.kms_key : (var.encryption ? aws_kms_key.bucket[0].arn : null)

  # Whether replication requires a created role
  create_replication_role = length(var.replication_rules) > 0 && var.replication_role == ""

  # Replication role / policy names
  replication_role_name   = "CoreS3ReplicationRole_${local.bucket_name}"
  replication_policy_name = "CoreS3ReplicationPolicy_${local.bucket_name}"
}

# ---------------------------------------------------------------------------
# Random ID resources for bucket naming
# ---------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "prefix_suffix" {
  count       = var.prefix ? 1 : 0
  byte_length = 2
}

# ---------------------------------------------------------------------------
# KMS Key (created only when encryption is enabled and no external key given)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "bucket" {
  count                    = var.encryption && var.kms_key == "" ? 1 : 0
  description              = "KMS key for S3 bucket ${local.bucket_name}"
  key_usage                = "ENCRYPT_DECRYPT"
  enable_key_rotation      = true
  deletion_window_in_days  = 30
  tags                     = var.tags
}

resource "aws_kms_alias" "bucket" {
  count         = var.encryption && var.kms_key == "" ? 1 : 0
  name          = "alias/s3-${local.bucket_name}"
  target_key_id = aws_kms_key.bucket[0].key_id
}

# ---------------------------------------------------------------------------
# S3 Bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_configuration != null ? true : null
  tags                = var.tags
}

# ---------------------------------------------------------------------------
# Ownership controls (required before setting ACLs)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = length(var.grants) > 0 || var.acl != null ? "BucketOwnerPreferred" : "BucketOwnerEnforced"
  }
}

# ---------------------------------------------------------------------------
# Public Access Block (always applied to block all public access)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Bucket ACL
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_acl" "this" {
  count = var.acl != null || length(var.grants) > 0 ? 1 : 0

  bucket     = aws_s3_bucket.this.id
  acl        = var.acl
  depends_on = [aws_s3_bucket_ownership_controls.this]

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [true] : []
    content {
      owner {
        id = data.aws_caller_identity.current.user_id
      }
      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            type       = grant.value.type
            uri        = grant.value.uri
            id         = grant.value.id
          }
          permission = grant.value.permission
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Bucket Policy
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

# ---------------------------------------------------------------------------
# Server-Side Encryption Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    bucket_key_enabled = true
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
  }
}

# ---------------------------------------------------------------------------
# Versioning
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "this" {
  count  = var.versioning ? 1 : 0
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# ---------------------------------------------------------------------------
# Request Payment Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

# ---------------------------------------------------------------------------
# Transfer Acceleration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count   = var.transfer_acceleration_status != null ? 1 : 0
  bucket  = aws_s3_bucket.this.id
  status  = var.transfer_acceleration_status
}

# ---------------------------------------------------------------------------
# Website Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website_index_document != null || var.website_error_document != null || var.website_redirect_all != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website_index_document != null ? [var.website_index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website_error_document != null ? [var.website_error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all != null ? [var.website_redirect_all] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = redirect_all_requests_to.value.protocol
    }
  }
}

# ---------------------------------------------------------------------------
# CORS Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ---------------------------------------------------------------------------
# Lifecycle Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = { for idx, r in var.lifecycle_rules : idx => r }
    content {
      id     = rule.value.id != null ? rule.value.id : "rule-${rule.key}"
      status = rule.value.status

      # filter block: use prefix/tag at top level, or and block for multiple conditions
      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : (rule.value.prefix != null ? [{ prefix = rule.value.prefix, tag = null, tags = null, object_size_greater_than = null, object_size_less_than = null }] : [])
        content {
          dynamic "and" {
            for_each = filter.value["tags"] != null ? [true] : []
            content {
              prefix                   = filter.value["prefix"]
              tags                     = filter.value["tags"]
              object_size_greater_than = filter.value["object_size_greater_than"]
              object_size_less_than    = filter.value["object_size_less_than"]
            }
          }
          # When tags is provided, everything goes into the and block above,
          # and nothing goes at the top level (except the and block itself).
          # When no tags (but possibly tag), use top-level attributes.
          prefix                   = filter.value["tags"] != null ? null : filter.value["prefix"]
          object_size_greater_than = filter.value["tags"] != null ? null : filter.value["object_size_greater_than"]
          object_size_less_than    = filter.value["tags"] != null ? null : filter.value["object_size_less_than"]

          dynamic "tag" {
            for_each = filter.value["tags"] == null && filter.value["tag"] != null ? [filter.value["tag"]] : []
            content {
              key   = tag.value["key"]
              value = tag.value["value"]
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Logging Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix != null ? var.logging_target_prefix : ""
}

# ---------------------------------------------------------------------------
# Object Lock Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_configuration.mode
      days = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }
}

# ---------------------------------------------------------------------------
# Replication IAM Role and Policy (created only when replication_rules are
# supplied and no external replication_role ARN is given)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0
  name  = local.replication_role_name
  tags  = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_replication_role ? 1 : 0
  name = local.replication_policy_name
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetReplicationConfiguration",
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}",
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = var.kms_key != "" ? [var.kms_key] : (var.encryption ? [aws_kms_key.bucket[0].arn] : [])
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Replication Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role != "" ? var.replication_role : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = { for idx, r in var.replication_rules : idx => r }
    content {
      id       = rule.value.id != null ? rule.value.id : "replication-rule-${rule.key}"
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : (rule.value.prefix != null ? [{ prefix = rule.value.prefix, tag = null, tags = null }] : [])
        content {
          dynamic "and" {
            for_each = filter.value["tags"] != null ? [true] : []
            content {
              prefix = filter.value["prefix"]
              tags   = filter.value["tags"]
            }
          }
          prefix = filter.value["tags"] != null ? null : filter.value["prefix"]
          dynamic "tag" {
            for_each = filter.value["tags"] == null && filter.value["tag"] != null ? [filter.value["tag"]] : []
            content {
              key   = tag.value["key"]
              value = tag.value["value"]
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.destination_storage_class

        dynamic "access_control_translation" {
          for_each = rule.value.access_control_translation != null ? [rule.value.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "encryption_configuration" {
          for_each = rule.value.encryption_configuration != null ? [rule.value.encryption_configuration] : []
          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication
      }

      source_selection_criteria {
        dynamic "sse_kms_encrypted_objects" {
          for_each = rule.value.replicate_kms_encrypted_objects == "Enabled" ? [{ status = "Enabled" }] : []
          content {
            status = sse_kms_encrypted_objects.value.status
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this, aws_iam_role.replication]
}

variable "projectPrefix" {
  description = "Project prefix for resource tagging"
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Resource owner for tagging"
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Build suffix for resource tagging"
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Map public IP on launch for public subnets"
  type        = bool
  default     = false
}

variable "awsRegion" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "awsAz1" {
  description = "First availability zone. If null, resolves to the first available AZ in the region."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Second availability zone. If null, resolves to awsAz1 when awsAz1 is specified, otherwise to the second available AZ in the region."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for public subnet A"
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for public subnet B"
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for management subnet A"
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for management subnet B"
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for private subnet A"
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for private subnet B"
  type        = string
  default     = "10.1.120.0/24"
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Resolve AZ1: use specified value, or fall back to the first available AZ
  az1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]

  # Resolve AZ2:
  # - If var.awsAz2 is explicitly set, use it.
  # - If var.awsAz2 is null but var.awsAz1 is specified, fall back to awsAz1.
  # - If both are null, use the second available AZ.
  az2 = var.awsAz2 != null ? var.awsAz2 : (
    var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
  )

  # Common tags
  common_tags = {
    projectPrefix = var.projectPrefix
    resourceOwner = var.resourceOwner
    buildSuffix   = var.buildSuffix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
  })
}

# Public subnets
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-public-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-public-b-${var.buildSuffix}"
  })
}

# Management subnets
resource "aws_subnet" "management_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "management_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-mgmt-b-${var.buildSuffix}"
  })
}

# Private subnets
resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-private-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-subnet-private-b-${var.buildSuffix}"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
  })
}

# Custom route table routing all outbound traffic to the internet gateway
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rtb-main-${var.buildSuffix}"
  })
}

# Associate the custom route table as the VPC main route table
resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_providers {
    tls = {
      source = "hashicorp/tls"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "rule_count" {
  description = "Number of listener rules"
  type        = number
  default     = 1
}

variable "resource_name" {
  description = "Default resource name for all named resources"
  type        = string
  default     = "benchmark"
}

locals {
  name = var.resource_name
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = local.name
  }
}

resource "aws_subnet" "main" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name}-${count.index}"
  }
}

resource "aws_security_group" "alb" {
  name        = local.name
  description = "Security group for internal ALB allowing all VPC traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb_target_group" "main" {
  name        = local.name
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    interval            = 60
    path                = "/health"
    port                = 8081
    protocol            = "HTTP"
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "main" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name  = "${local.name}.local"
    organization = local.name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "main" {
  private_key      = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.main.cert_pem

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb" "main" {
  name                       = local.name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.main[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-3-2023-06"
  certificate_arn   = aws_acm_certificate.main.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener_rule" "static" {
  count = var.rule_count

  listener_arn = aws_lb_listener.main.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "resource_name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "VPC instance tenancy"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "VPC main CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound NACL rules for the private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 1024
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound NACL rules for the private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    }
  ]
}

locals {
  name_prefix = var.resource_name_prefix
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_no    = ingress.value.rule_number
      protocol   = ingress.value.protocol
      from_port  = ingress.value.from_port
      to_port    = ingress.value.to_port
      cidr_block = ingress.value.cidr_block
      action     = ingress.value.action
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_no    = egress.value.rule_number
      protocol   = egress.value.protocol
      from_port  = egress.value.from_port
      to_port    = egress.value.to_port
      cidr_block = egress.value.cidr_block
      action     = egress.value.action
    }
  }

  tags = {
    Name = "${local.name_prefix}-private-nacl"
  }
}

resource "aws_network_acl_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private.id
}

locals {
  # Name logic: use explicit name, or derive from prefix, or auto-generate
  queue_name        = var.name != null ? (var.fifo_queue ? "${var.name}.fifo" : var.name) : null
  queue_name_prefix = var.name_prefix != null ? var.name_prefix : null

  # DLQ name: use explicit dlq_name, derive from main queue name/prefix, or use default suffix
  dlq_name = var.dlq_name != null ? var.dlq_name : (
    var.name != null ? "${var.name}${var.dlq_suffix}" : null
  )
  dlq_fifo_name = var.dlq_name != null ? (var.fifo_queue && !endswith(var.dlq_name, ".fifo") ? "${var.dlq_name}.fifo" : var.dlq_name) : (
    var.name != null ? "${var.name}${var.dlq_suffix}${var.fifo_queue ? ".fifo" : ""}" : null
  )
  dlq_name_prefix = var.dlq_name_prefix != null ? var.dlq_name_prefix : (
    var.name_prefix != null ? "${var.name_prefix}${var.dlq_suffix}" : null
  )

  # SSE logic: SQS managed SSE when enabled and no KMS key provided
  use_sqs_managed_sse = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false
}

###############################################################################
# PRIMARY SQS QUEUE
###############################################################################
resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name       = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = local.use_sqs_managed_sse
  kms_master_key_id       = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  delay_seconds             = var.delay_seconds
  max_message_size          = var.max_message_size
  message_retention_seconds = var.message_retention_seconds
  receive_wait_time_seconds = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# DEAD-LETTER QUEUE
###############################################################################
resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_fifo_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  # DLQ inherits encryption settings from the main queue
  sqs_managed_sse_enabled = local.use_sqs_managed_sse
  kms_master_key_id       = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  delay_seconds             = var.delay_seconds
  max_message_size          = var.max_message_size
  message_retention_seconds = var.message_retention_seconds
  receive_wait_time_seconds = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  tags = merge(var.tags, { Name = coalesce(local.dlq_fifo_name, local.dlq_name_prefix) })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# REDRIVE POLICY (attached to main queue, targeting DLQ)
###############################################################################
resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  })
}

###############################################################################
# REDRIVE ALLOW POLICY (attached to DLQ, restricting source to main queue)
###############################################################################
data "aws_iam_policy_document" "dlq_redrive_allow" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["sqs:Redrive"]
    resources = [aws_sqs_queue.dlq[0].arn]

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_sqs_queue.this[0].arn]
    }
  }
}

resource "aws_sqs_queue_policy" "dlq_redrive_allow" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq_redrive_allow[0].json
}

###############################################################################
# QUEUE POLICY (on the main queue, controlled by create_queue_policy flag)
###############################################################################
data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.policy_statements
    content {
      sid       = try(statement.value.sid, null)
      effect    = try(statement.value.effect, "Allow")
      actions   = statement.value.actions
      resources = try(
        length(statement.value.resources) > 0 ? statement.value.resources : [aws_sqs_queue.this[0].arn],
        [aws_sqs_queue.this[0].arn]
      )

      dynamic "principals" {
        for_each = try(statement.value.principals, [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

###############################################################################
# VARIABLES
###############################################################################
variable "create" {
  description = "Whether to create the SQS queue"
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SQS queue. For FIFO queues the .fifo suffix is appended automatically."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "A prefix to use for the queue name. Terraform appends a unique suffix. For FIFO queues, .fifo is appended."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queue is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Deduplication scope for FIFO queues (queue or messageGroup)"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Throughput limit for FIFO queues (perQueue or perMessageGroupId)"
  type        = string
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS managed server-side encryption. Automatically applied when kms_master_key_id is omitted."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of a custom managed AWS KMS key for SSE. If omitted, SQS managed SSE is used."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time in seconds for which Amazon SQS can reuse a data key"
  type        = number
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue"
  type        = number
  default     = 30
}

variable "tags" {
  description = "A mapping of tags to assign to the queue(s)"
  type        = map(string)
  default     = {}
}

###############################################################################
# DEAD-LETTER QUEUE VARIABLES
###############################################################################
variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to create a redrive allow policy on the DLQ restricting redrive to the main queue"
  type        = bool
  default     = true
}

variable "dlq_name" {
  description = "The name of the dead-letter queue. If not set, derived from the main queue name with dlq_suffix."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "A prefix for the DLQ name. If not set, derived from the main queue name_prefix with dlq_suffix."
  type        = string
  default     = null
}

variable "dlq_suffix" {
  description = "Suffix to append to the main queue name when auto-generating the DLQ name"
  type        = string
  default     = "-dlq"
}

variable "max_receive_count" {
  description = "Maximum number of times a message can be received before being sent to the DLQ"
  type        = number
  default     = 5
}

###############################################################################
# QUEUE POLICY VARIABLES
###############################################################################
variable "create_queue_policy" {
  description = "Whether to create and attach a queue policy to the main queue"
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of IAM policy JSON documents to merge as source documents"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy JSON documents to merge as override documents"
  type        = list(string)
  default     = []
}

variable "policy_statements" {
  description = "Custom IAM policy statements for the queue. Resources default to the queue ARN when unspecified."
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

###############################################################################
# OUTPUTS
###############################################################################
output "queue_id" {
  description = "The URL of the main SQS queue"
  value       = var.create ? aws_sqs_queue.this[0].id : null
}

output "queue_arn" {
  description = "The ARN of the main SQS queue"
  value       = var.create ? aws_sqs_queue.this[0].arn : null
}

output "queue_name" {
  description = "The name of the main SQS queue"
  value       = var.create ? aws_sqs_queue.this[0].name : null
}

output "dlq_id" {
  description = "The URL of the dead-letter queue"
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].id : null
}

output "dlq_arn" {
  description = "The ARN of the dead-letter queue"
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].arn : null
}

output "dlq_name" {
  description = "The name of the dead-letter queue"
  value       = var.create && var.create_dlq ? aws_sqs_queue.dlq[0].name : null
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "backup_name" {
  description = "Required name for the backup infrastructure"
  type        = string
  default     = "example-backup"
}

variable "account_type" {
  description = "Account type: 'workload' or 'backup'"
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for vault encryption"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional vault policy JSON string"
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention period in days for vault lock. When set, a vault lock is created."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Maximum retention period in days for vault lock"
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Number of days the vault lock configuration is changeable"
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Flag to enable vault SNS notifications"
  type        = bool
  default     = false
}

variable "backup_vault_notification_events" {
  description = "List of backup events that trigger SNS notifications"
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic for vault notifications"
  type        = string
  default     = null
}

variable "rule_schedule" {
  description = "Cron expression for the backup plan rule schedule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "copy_actions" {
  description = "Cross-region or cross-account copy actions for the backup rule"
  type = list(object({
    destination_vault_arn = string
    lifecycle = optional(object({
      delete_after_days       = optional(number)
      cold_storage_after_days = optional(number)
    }))
  }))
  default = []
}

variable "selection_resources" {
  description = "List of ARNs for resource-based backup selection"
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Backup vault
# ---------------------------------------------------------------------------

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn

  tags = {
    Name = var.backup_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Vault policy (conditional on vault_policy being provided)
# ---------------------------------------------------------------------------

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

# ---------------------------------------------------------------------------
# Vault lock configuration (conditional on min_retention_days)
# ---------------------------------------------------------------------------

resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

# ---------------------------------------------------------------------------
# Vault SNS notifications (conditional)
# ---------------------------------------------------------------------------

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_notification_events
}

# ---------------------------------------------------------------------------
# IAM role (only for workload accounts)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  name = "aws-backup-${var.backup_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "aws-backup-${var.backup_name}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ---------------------------------------------------------------------------
# Backup plan (only for workload accounts)
# ---------------------------------------------------------------------------

resource "aws_backup_plan" "this" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = "${var.backup_name}-backup-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      BackupName = var.backup_name
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
        dynamic "lifecycle" {
          for_each = try(copy_action.value.lifecycle, null) != null ? [copy_action.value.lifecycle] : []
          content {
            delete_after       = try(lifecycle.value.delete_after, null)
            cold_storage_after = try(lifecycle.value.cold_storage_after, null)
          }
        }
      }
    }
  }

  tags = {
    Name = "plan-${var.backup_name}-backup"
  }
}

# ---------------------------------------------------------------------------
# Tag-based backup selection (always created for workload accounts)
# ---------------------------------------------------------------------------

resource "aws_backup_selection" "tag_based" {
  count = var.account_type == "workload" ? 1 : 0

  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "${var.backup_name}-tag-selection"
  plan_id      = aws_backup_plan.this[0].id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

# ---------------------------------------------------------------------------
# Resource-based backup selection (only when explicit ARNs are supplied)
# ---------------------------------------------------------------------------

resource "aws_backup_selection" "resource_based" {
  count = var.account_type == "workload" && length(var.selection_resources) > 0 ? 1 : 0

  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "${var.backup_name}-resource-selection"
  plan_id      = aws_backup_plan.this[0].id
  resources    = var.selection_resources

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "name_prefix" {
  description = "Prefix for naming resources. Defaults to 'config'. Falls back to a random pet name if null or empty."
  type        = string
  default     = "config"
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Naming convention
# -----------------------------------------------------------------------------
resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  resource_name = var.name_prefix != null && var.name_prefix != "" ? var.name_prefix : random_pet.this.id
}

# -----------------------------------------------------------------------------
# IAM Role for AWS Config
# -----------------------------------------------------------------------------
resource "aws_iam_role" "config" {
  name               = local.resource_name
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Sid    = "ConfigAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_inline" {
  name   = "${local.resource_name}-inline"
  role   = aws_iam_role.config.name
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Sid    = "S3WriteToConfigBucket"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.config.arn,
          "${aws_s3_bucket.config.arn}/*"
        ]
      },
      {
        Sid    = "SNSPublishToConfigTopic"
        Effect = "Allow"
        Action = [
          "sns:Publish"
        ]
        Resource = [aws_sns_topic.config.arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# S3 Bucket – snapshot storage
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "config" {
  bucket        = "awsconfig-${local.resource_name}-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket                  = aws_s3_bucket.config.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3" {
  description             = "KMS key for AWS Config S3 bucket SSE encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdminPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowConfigServiceToUseKeyForS3"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.resource_name}-s3-key"
  target_key_id = aws_kms_key.s3.id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id
  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# KMS Key – SNS topic encryption
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  description             = "KMS key for AWS Config SNS topic encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdminPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSNSServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowConfigServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}
resource "aws_kms_alias" "sns" {
  name          = "alias/${local.resource_name}-sns-key"
  target_key_id = aws_kms_key.sns.id
}

# -----------------------------------------------------------------------------
# SNS Topic – streaming notifications
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "config" {
  name              = local.resource_name
  kms_master_key_id = aws_kms_key.sns.id
}

# -----------------------------------------------------------------------------
# AWS Config Configuration Recorder
# -----------------------------------------------------------------------------
resource "aws_config_configuration_recorder" "config" {
  name     = local.resource_name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}
resource "aws_config_delivery_channel" "config" {
  name           = local.resource_name
  s3_bucket_name = aws_s3_bucket.config.id
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config.arn

  depends_on = [aws_config_configuration_recorder.config]
}
resource "aws_config_configuration_recorder_status" "config" {
  name       = aws_config_configuration_recorder.config.name
  is_enabled = true
  depends_on = [aws_config_delivery_channel.config]
}

# -----------------------------------------------------------------------------
# AWS Config Managed Rules
# -----------------------------------------------------------------------------

# 1. cloudtrail-enabled
resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                         = "cloudtrail-enabled"
  description                  = "Checks that AWS CloudTrail is enabled in all regions."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 2. iam-pw-policy
resource "aws_config_config_rule" "iam_password_policy" {
  name                         = "iam-pw-policy"
  description                  = "Checks whether the account password policy for IAM users meets the specified requirements."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 3. ec2-vpc
resource "aws_config_config_rule" "instances_in_vpc" {
  name                         = "ec2-vpc"
  description                  = "Checks whether EC2 instances are running in a VPC."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 4. root-mfa-enabled
resource "aws_config_config_rule" "root_account_mfa_enabled" {
  name                         = "root-mfa-enabled"
  description                  = "Checks whether the root user of your AWS account requires multi-factor authentication (MFA)."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier   = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 5. acm-expiratin-check
resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name                         = "acm-expiration-check"
  description                  = "Checks whether ACM Certificates in your account are marked for expiration within the specified number of days."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier   = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 6. ebs-inse-check
resource "aws_config_config_rule" "ec2_volume_inuse_check" {
  name                         = "ebs-inuse-check"
  description                  = "Checks whether EBS volumes are attached to EC2 instances."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier   = "EC2_VOLUME_INUSE_CHECK"
  }
  depends_on = [aws_config_configuration_recorder.config]
}

# 7. ec2-imdv2-check
resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name                         = "ec2-imdsv2-check"
  description                  = "Checks whether EC2 instance metadata version is configured with IMDSv2."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 8. rds-encrypted
resource "aws_config_config_rule" "rds_storage_encrypted" {
  name                         = "rds-encrypted"
  description                  = "Checks whether storage encryption is enabled for your RDS DB instances."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 9. rds-private
resource "aws_config_config_rule" "rds_instance_public_access_check" {
  name                         = "rds-private"
  description                  = "Checks whether RDS instances are not publicly accessible."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 10. rds-private-snapshots
resource "aws_config_config_rule" "rds_snapshots_public_prohibited" {
  name                         = "rds-private-snapshots"
  description                  = "Checks whether RDS snapshots are not publicly accessible."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# 11. required-tags
resource "aws_config_config_rule" "required_tags" {
  name                         = "required-tags"
  description                  = "Checks whether resources have the specified tags."
  maximum_execution_frequency   = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  depends_on = [aws_config_configuration_recorder.config]
}

# Data sources for static provider metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# AWS-managed policy data sources (global AWS, not account-created)
# ---------------------------------------------------------------------------
data "aws_iam_policy" "drs_agent" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "drs_failback" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "drs_conversion_server" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "drs_recovery_instance" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "drs_replication_server" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ---------------------------------------------------------------------------
# Trust policy documents
# ---------------------------------------------------------------------------

# DRS Agent Role trust policy — source identity prefix "s-"
data "aws_iam_policy_document" "drs_agent_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }
  }
}

# DRS Failback Role trust policy — source identity prefix "i-"
data "aws_iam_policy_document" "drs_failback_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }
  }
}

# EC2 service roles trust policy
data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Initializer role trust policy — allow the current calling identity to assume it
data "aws_iam_policy_document" "initializer_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
  }
}

# ---------------------------------------------------------------------------
# Custom InitializePolicy for the initializer role
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "initialize" {
  statement {
    sid    = "DRSInitializeService"
    effect = "Allow"
    actions = [
      "drs:InitializeService"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMCreateInstanceProfile"
    effect = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:DeleteInstanceProfile",
      "iam:GetInstanceProfile"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMPassRoleEC2DRS"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ec2.amazonaws.com", "drs.amazonaws.com"]
    }
  }

  statement {
    sid    = "IAMCreateServiceLinkedRole"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  statement {
    sid    = "EC2FullAccess"
    effect = "Allow"
    actions = [
      "ec2:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMCreateRolesAndAttachDRSPolicies"
    effect = "Allow"
    actions = [
      "iam:CreateRole",
      "iam:AttachRolePolicy",
      "iam:PutRolePolicy",
      "iam:GetRole",
      "iam:ListAttachedRolePolicies",
      "iam:ListRolePolicies"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/service-role/AWSElasticDisasterRecovery*",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/AWSElasticDisasterRecoveryInitializerRole"
    ]
    condition {
      test     = "StringEquals"
      variable = "iam:PolicyARN"
      values = [
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
      ]
    }
  }
}

resource "aws_iam_policy" "initialize" {
  name        = "InitializePolicy"
  description = "Policy granting DRS initialization and management permissions"
  policy      = data.aws_iam_policy_document.initialize.json

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Service Roles (path = "/service-role/")
# ---------------------------------------------------------------------------

resource "aws_iam_role" "drs_agent" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.drs_agent_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "drs_failback" {
  name               = "AWSElasticDisasterRecoveryFailbackRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.drs_failback_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "drs_conversion_server" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "drs_recovery_instance" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "drs_replication_server" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "drs_recovery_instance_with_launch_actions" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Policy attachments for service roles
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "drs_agent" {
  role       = aws_iam_role.drs_agent.name
  policy_arn = data.aws_iam_policy.drs_agent.arn
}

resource "aws_iam_role_policy_attachment" "drs_failback" {
  role       = aws_iam_role.drs_failback.name
  policy_arn = data.aws_iam_policy.drs_failback.arn
}

resource "aws_iam_role_policy_attachment" "drs_conversion_server" {
  role       = aws_iam_role.drs_conversion_server.name
  policy_arn = data.aws_iam_policy.drs_conversion_server.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance" {
  role       = aws_iam_role.drs_recovery_instance.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance.arn
}

resource "aws_iam_role_policy_attachment" "drs_replication_server" {
  role       = aws_iam_role.drs_replication_server.name
  policy_arn = data.aws_iam_policy.drs_replication_server.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_policy" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance.arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_with_launch_actions_ssm" {
  role       = aws_iam_role.drs_recovery_instance_with_launch_actions.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance.arn
}

# ---------------------------------------------------------------------------
# Initializer Role (root path)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "initializer" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.initializer_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "initializer" {
  role       = aws_iam_role.initializer.name
  policy_arn = aws_iam_policy.initialize.arn
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names    = data.aws_availability_zones.available.names
  az_suffixes = [for az in local.az_names : reverse(split("-", az))[0]]
}

# ===========================
# EXTERNAL VPC
# ===========================

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  ingress = []
  egress  = []
}

resource "aws_subnet" "external" {
  count = 4

  vpc_id            = aws_vpc.external.id
  cidr_block        = cidrsubnet("10.41.0.0/16", 8, count.index)
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "Subnet${count.index}-${local.az_suffixes[count.index]}"
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External GW"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name = "External Route Table"
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external" {
  count = 4

  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 150
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name = "External Default ACL"
  }
}

# ===========================
# INTERNAL VPC
# ===========================

resource "aws_vpc" "internal" {
  cidr_block       = "10.40.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  ingress = []
  egress  = []
}

resource "aws_subnet" "internal" {
  count = 4

  vpc_id            = aws_vpc.internal.id
  cidr_block        = cidrsubnet("10.40.0.0/16", 8, count.index)
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "Subnet${count.index}-${local.az_suffixes[count.index]}"
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 150
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name = "Internal Default ACL"
  }
}

locals {
  prefix        = var.prefix
  az_count      = 3
  vpc_cidr      = "10.0.0.0/16"
  private_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  https_listener_port = 443
  http_listener_port  = 80
  app_port            = 5678
  health_check_path   = "/healthz"

  efs_access_point_path = "/n8n"
  efs_owner_uid         = 1000
  efs_owner_gid         = 1000
  efs_permissions       = "0777"

  container_mount_path = "/home/node/.n8n"
  container_cpu        = 256
  container_memory     = 512
  container_port       = 5678

  log_group_name = "${var.prefix}-logs"
  log_retention  = 1

  webhook_url = var.url != null ? var.url : "https://${aws_lb.internal_n8n.dns_name}"
}

variable "prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "ARN of an existing ACM certificate for HTTPS listener"
  type        = string
  default     = null
}

variable "url" {
  description = "Optional public URL override for WEBHOOK_URL"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of Fargate tasks"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "n8n container image"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type"
  type        = string
  default     = "FARGATE_SPOT"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.prefix}-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.prefix}-private-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.prefix}-public-${count.index + 1}"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway (needed for public subnets and ALB outbound)
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}-igw"
  }
}

# ---------------------------------------------------------------------------
# Route Tables
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.prefix}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security Group: Load Balancer
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb-sg"
  description = "Security group for n8n internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-alb-sg"
  }
}

# ---------------------------------------------------------------------------
# Security Group: ECS Tasks
# ---------------------------------------------------------------------------
resource "aws_security_group" "ecs_tasks" {
  name        = "${local.prefix}-ecs-tasks-sg"
  description = "Security group for n8n ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = local.app_port
    to_port         = local.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-ecs-tasks-sg"
  }
}

# ---------------------------------------------------------------------------
# Security Group: EFS Mount Targets
# ---------------------------------------------------------------------------
resource "aws_security_group" "efs" {
  name        = "${local.prefix}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-efs-sg"
  }
}

# ---------------------------------------------------------------------------
# ACM Certificate (self-signed if no certificate_arn provided)
# ---------------------------------------------------------------------------
resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
}

resource "tls_self_signed_cert" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key_pem  = tls_private_key.self_signed[0].private_key_pem
  validity_period_hours = 43830

  subject {
    common_name         = "${local.prefix}-internal"
    organization        = local.prefix
  }

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  tags = {
    Name = "${local.prefix}-self-signed-cert"
  }
}

locals {
  alb_certificate_arn = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn
}

# ---------------------------------------------------------------------------
# Application Load Balancer (Internal)
# ---------------------------------------------------------------------------
resource "aws_lb" "internal_n8n" {
  name               = "${local.prefix}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection       = false
  drop_invalid_header_fields       = true

  tags = {
    Name = "${local.prefix}-alb"
  }
}

# ---------------------------------------------------------------------------
# ALB Target Group
# ---------------------------------------------------------------------------
resource "aws_lb_target_group" "n8n" {
  name        = "${local.prefix}-tg"
  port        = local.http_listener_port
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = local.health_check_path
    protocol            = "HTTP"
    port                = "traffic-port"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    matcher             = "200-499"
  }

  tags = {
    Name = "${local.prefix}-tg"
  }
}

# ---------------------------------------------------------------------------
# ALB Listeners
# ---------------------------------------------------------------------------
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal_n8n.arn
  port              = local.https_listener_port
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.alb_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal_n8n.arn
  port              = local.http_listener_port
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = local.https_listener_port
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ---------------------------------------------------------------------------
# EFS File System
# ---------------------------------------------------------------------------
resource "aws_efs_file_system" "n8n" {
  creation_token = "${local.prefix}-efs"
  encrypted      = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.prefix}-efs"
  }
}

resource "aws_efs_mount_target" "n8n" {
  count           = local.az_count
  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = local.efs_owner_uid
    gid = local.efs_owner_gid
  }

  root_directory {
    path = local.efs_access_point_path
    creation_info {
      owner_uid   = local.efs_owner_uid
      owner_gid   = local.efs_owner_gid
      permissions = local.efs_permissions
    }
  }

  tags = {
    Name = "${local.prefix}-efs-ap"
  }
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "n8n" {
  name              = local.log_group_name
  retention_in_days = local.log_retention

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.log_group_name
  }
}

# ---------------------------------------------------------------------------
# IAM Roles for ECS
# ---------------------------------------------------------------------------
resource "aws_iam_role" "task_execution" {
  name = "${local.prefix}-task-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-task-execution-role"
  }
}

resource "aws_iam_role_policy" "task_execution_logs" {
  name = "${local.prefix}-task-execution-logs"
  role = aws_iam_role.task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.n8n.arn}:*",
          "${aws_cloudwatch_log_group.n8n.arn}:*:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "task" {
  name = "${local.prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-task-role"
  }
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${local.prefix}-task-logs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.n8n.arn}:*",
          "${aws_cloudwatch_log_group.n8n.arn}:*:*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# ECS Cluster
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "n8n" {
  name = "${local.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${local.prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "n8n" {
  cluster_name = aws_ecs_cluster.n8n.name

  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

# ---------------------------------------------------------------------------
# ECS Task Definition
# ---------------------------------------------------------------------------
resource "aws_ecs_task_definition" "n8n" {
  family                   = "${local.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = local.container_cpu
  memory                   = local.container_memory
  execution_role_arn       = aws_iam_role.task_execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n_data"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.n8n.id
      transit_encryption      = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = local.container_port
          protocol      = "tcp"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "${local.prefix}"
        }
      }
      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "n8n_data"
          containerPath = local.container_mount_path
          readOnly      = false
        }
      ]
    }
  ])

  tags = {
    Name = "${local.prefix}-task-def"
  }
}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# ECS Service
# ---------------------------------------------------------------------------
resource "aws_ecs_service" "n8n" {
  name            = "${local.prefix}-service"
  cluster         = aws_ecs_cluster.n8n.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.public[*].id
    assign_public_ip = true
    security_groups  = [aws_security_group.ecs_tasks.id]
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = "n8n"
    container_port   = local.container_port
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
  ]

  lifecycle {
    ignore_changes = [
      desired_count,
    ]
  }

  tags = {
    Name = "${local.prefix}-service"
  }
}

locals {
  vpc_cidr        = "10.255.0.0/16"
  admin_range     = "203.0.113.0/24"
  application_tag = "dosomething-quasar"
  environment_tag = "production"
  stack_tag       = "data"
  common_tags = {
    Application = local.application_tag
    Environment = local.environment_tag
    Stack       = local.stack_tag
  }
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
