###############################################################################
# VARIABLES
###############################################################################

variable "create" {
  description = "Global toggle for all resources in this module"
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function"
  type        = string
}

variable "alias_name" {
  description = "Alias name for the Lambda function"
  type        = string
}

variable "current_version" {
  description = "Current version of the Lambda function"
  type        = string
}

variable "target_version" {
  description = "Target version for the Lambda deployment"
  type        = string
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function to invoke before allowing traffic"
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function to invoke after allowing traffic"
  type        = string
  default     = null
}

# ---------------------------------------------------------------------------
# CodeDeploy Application
# ---------------------------------------------------------------------------

variable "create_app" {
  description = "Whether to create a CodeDeploy application"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to reference an existing CodeDeploy application"
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of the CodeDeploy application"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# CodeDeploy Deployment Group
# ---------------------------------------------------------------------------

variable "create_deployment_group" {
  description = "Whether to create a CodeDeploy deployment group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to reference an existing deployment group"
  type        = bool
  default     = false
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration name"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "deployment_group_name" {
  description = "Name of the deployment group"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# CloudWatch Alarms (optional)
# ---------------------------------------------------------------------------

variable "alarm_names" {
  description = "List of CloudWatch alarm names for deployment monitoring"
  type        = list(string)
  default     = []
}

variable "alarm_enabled" {
  description = "Whether alarm monitoring is enabled"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------
# Notification Triggers (optional)
# ---------------------------------------------------------------------------

variable "trigger_events" {
  description = "List of trigger events (e.g. DeploymentSuccess, DeploymentFailure)"
  type        = list(string)
  default     = []
}

variable "trigger_target_arn" {
  description = "ARN of the SNS topic for deployment notifications"
  type        = string
  default     = null
}

variable "trigger_name" {
  description = "Name of the notification trigger"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# IAM Role
# ---------------------------------------------------------------------------

variable "create_codedeploy_role" {
  description = "Whether to create an IAM role for CodeDeploy"
  type        = bool
  default     = true
}

variable "codedeploy_service_principals" {
  description = "List of service principals for the CodeDeploy IAM role"
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach an inline policy granting lambda:InvokeFunction for hooks"
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach an inline policy granting sns:Publish for triggers"
  type        = bool
  default     = false
}

variable "role_name" {
  description = "Name of the CodeDeploy IAM role (auto-generated if empty)"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# Deployment Execution
# ---------------------------------------------------------------------------

variable "create_deployment" {
  description = "Whether to create the deployment AppSpec, script, and optionally run it"
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI command to use for deployments"
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Sleep interval in seconds between deployment status checks"
  type        = number
  default     = 5
}

variable "save_deploy_script" {
  description = "Whether to save the generated deployment shell script locally"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Whether to execute the deployment via a null_resource provisioner"
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Triggers a new deployment when changed (use a random UUID)"
  type        = string
  default     = ""
}

variable "deployment_description" {
  description = "Description for the deployment"
  type        = string
  default     = "Terraform managed Lambda blue/green deployment"
}

###############################################################################
# DATA SOURCES (static / provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

###############################################################################
# LOCALS
###############################################################################

locals {
  # Resolve the application name from creation or variable
  resolved_app_name = var.create_app && !var.use_existing_app && var.create
    ? try(aws_codedeploy_app.this[0].name, var.app_name)
    : var.app_name

  # Resolve the deployment group name
  resolved_deployment_group_name = var.deployment_group_name != ""
    ? var.deployment_group_name
    : "dg-${var.function_name}"

  # IAM role name
  resolved_role_name = var.role_name != ""
    ? var.role_name
    : "codedeploy-lambda-${var.function_name}"

  # Build hooks map for AppSpec (only non-null hooks)
  app_spec_hooks = merge(
    var.before_allow_traffic_hook_arn != null && var.before_allow_traffic_hook_arn != ""
      ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn }
      : {},
    var.after_allow_traffic_hook_arn != null && var.after_allow_traffic_hook_arn != ""
      ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn }
      : {},
  )

  # AppSpec JSON document
  app_spec_content = jsonencode({
    version = "0.0"
    Resources = [
      {
        myLambda = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      },
    ]
    Hooks = length(local.app_spec_hooks) > 0 ? local.app_spec_hooks : null
  })

  # Shell script for deployment
  deploy_script_content = <<-EOT
#!/usr/bin/env bash
set -euo pipefail

APP_NAME="${local.resolved_app_name}"
DEPLOYMENT_GROUP="${local.resolved_deployment_group_name}"
APP_SPEC='${replace(local.app_spec_content, "'", "'\\''")}'

echo "Creating deployment for application: $APP_NAME / group: $DEPLOYMENT_GROUP"

DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
  --application-name "$APP_NAME" \
  --deployment-group-name "$DEPLOYMENT_GROUP" \
  --description "${var.deployment_description}" \
  --revision "revisionType=AppSpecContent,appSpecContent={\\\"content\\\":\\\"$APP_SPEC\\\"}" \
  --query 'deploymentId' \
  --output text)

echo "Deployment ID: $DEPLOYMENT_ID"

# Monitor deployment status
while true; do
  STATUS=$(${var.aws_cli_command} deploy get-deployment \
    --deployment-id "$DEPLOYMENT_ID" \
    --query 'deploymentInfo.status' \
    --output text)
  echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] Status: $STATUS"

  if [[ "$STATUS" == "Succeeded" ]]; then
    echo "Deployment succeeded!"
    break
  elif [[ "$STATUS" == "Failed" || "$STATUS" == "Stopped" || "$STATUS" == "Rollback"* ]]; then
    echo "Deployment ended with status: $STATUS"
    exit 1
  fi

  sleep ${var.get_deployment_sleep_timer}
done
EOT
}

###############################################################################
# IAM ROLE AND POLICIES
###############################################################################

# Assume role policy document
data "aws_iam_policy_document" "codedeploy_assume_role" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

# IAM role for CodeDeploy
resource "aws_iam_role" "codedeploy" {
  count              = var.create && var.create_codedeploy_role ? 1 : 0
  name               = local.resolved_role_name
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# Attach AWS managed AWSCodeDeployRoleForLambda policy
resource "aws_iam_role_policy_attachment" "codedeploy_managed" {
  count      = var.create && var.create_codedeploy_role ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSCodeDeployRoleForLambda"
}

# Inline policy for hook invocation permissions
data "aws_iam_policy_document" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (
    (var.before_allow_traffic_hook_arn != null && var.before_allow_traffic_hook_arn != "") ||
    (var.after_allow_traffic_hook_arn != null && var.after_allow_traffic_hook_arn != "")
  ) ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = compact([
      var.before_allow_traffic_hook_arn,
      var.after_allow_traffic_hook_arn,
    ])
  }
}

resource "aws_iam_role_policy" "hooks" {
  count  = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (
    (var.before_allow_traffic_hook_arn != null && var.before_allow_traffic_hook_arn != "") ||
    (var.after_allow_traffic_hook_arn != null && var.after_allow_traffic_hook_arn != "")
  ) ? 1 : 0
  name   = "${local.resolved_role_name}-hooks"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.hooks[0].json
}

# Inline policy for trigger SNS publish permissions
data "aws_iam_policy_document" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && var.trigger_target_arn != null ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [var.trigger_target_arn]
  }
}

resource "aws_iam_role_policy" "triggers" {
  count  = var.create && var.create_codedeploy_role && var.attach_triggers_policy && var.trigger_target_arn != null ? 1 : 0
  name   = "${local.resolved_role_name}-triggers"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.triggers[0].json
}

###############################################################################
# CODEDEPLOY APPLICATION
###############################################################################

resource "aws_codedeploy_app" "this" {
  count            = var.create && var.create_app && !var.use_existing_app ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# CODEDEPLOY DEPLOYMENT GROUP
###############################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0

  app_name               = local.resolved_app_name
  deployment_group_name  = local.resolved_deployment_group_name
  service_role_arn       = var.create_codedeploy_role ? aws_iam_role.codedeploy[0].arn : null
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_type   = "BLUE_GREEN"
    deployment_option = "WITH_TRAFFIC_CONTROL"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  alarm_configuration {
    alarms  = var.alarm_names
    enabled = var.alarm_enabled && length(var.alarm_names) > 0
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_target_arn != null && length(var.trigger_events) > 0 ? [1] : []
    content {
      trigger_events     = var.trigger_events
      trigger_name       = var.trigger_name != "" ? var.trigger_name : "trigger-${var.function_name}"
      trigger_target_arn = var.trigger_target_arn
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_codedeploy_app.this,
  ]
}

###############################################################################
# DEPLOYMENT RESOURCES (AppSpec file, deploy script, null_resource runner)
###############################################################################

# AppSpec JSON file
resource "local_file" "app_spec" {
  count   = var.create && var.create_deployment ? 1 : 0
  content = local.app_spec_content
  filename = "${path.module}/${var.function_name}_appspec.json"
}

# Deployment shell script
resource "local_file" "deploy_script" {
  count    = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0
  content  = local.deploy_script_content
  filename = "${path.module}/${var.function_name}_deploy.sh"

  provisioner "local-exec" {
    command = "chmod +x \"${path.module}/${var.function_name}_deploy.sh\""
  }
}

# Random UUID for force_deploy trigger
resource "random_uuid" "force_deploy" {
  count = var.create && var.create_deployment && var.run_deployment && var.force_deploy == "" ? 1 : 0
}

# Null resource that runs the deployment
resource "null_resource" "deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force_deploy = var.force_deploy != "" ? var.force_deploy : (
      var.create_deployment && var.run_deployment && var.force_deploy == ""
        ? join("", random_uuid.force_deploy[*].result)
        : ""
    )
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local.deploy_script_content
  }

  depends_on = [
    local_file.app_spec,
    aws_codedeploy_app.this,
    aws_codedeploy_deployment_group.this,
    aws_iam_role.codedeploy,
  ]
}

###############################################################################
# OUTPUTS
###############################################################################

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application"
  value       = var.create && var.create_app && !var.use_existing_app ? aws_codedeploy_app.this[0].name : var.app_name
}

output "codedeploy_app_id" {
  description = "ID of the CodeDeploy application"
  value       = var.create && var.create_app && !var.use_existing_app ? aws_codedeploy_app.this[0].id : null
}

output "codedeploy_deployment_group_name" {
  description = "Name of the deployment group"
  value       = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? aws_codedeploy_deployment_group.this[0].deployment_group_name : local.resolved_deployment_group_name
}

output "codedeploy_deployment_group_id" {
  description = "ID of the deployment group"
  value       = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? aws_codedeploy_deployment_group.this[0].id : null
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy IAM role"
  value       = var.create && var.create_codedeploy_role ? aws_iam_role.codedeploy[0].arn : null
}

output "codedeploy_role_name" {
  description = "Name of the CodeDeploy IAM role"
  value       = var.create && var.create_codedeploy_role ? aws_iam_role.codedeploy[0].name : null
}

output "app_spec_content" {
  description = "The generated AppSpec JSON content"
  value       = var.create && var.create_deployment ? local.app_spec_content : null
}

output "deploy_script_content" {
  description = "The generated deployment shell script content"
  value       = var.create && var.create_deployment ? local.deploy_script_content : null
}

variable "admin_cidrs" {
  description = "List of CIDR blocks allowed SSH access via the Home SSH security group"
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

locals {
  vpc_cidr        = "10.0.0.0/16"
  web_cidr        = "10.0.2.0/24"
  gameserver_cidr = "10.0.4.0/22"
  internal_domain = "internal"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "main"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "ig"
  }
}

# DHCP Options
resource "aws_vpc_dhcp_options" "main" {
  domain_name         = local.internal_domain
  domain_name_servers = ["AmazonProvidedDNS", "8.8.8.8"]
  tags = {
    Name = "main-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

# Route 53 Private Hosted Zone
resource "aws_route53_zone" "internal" {
  name = local.internal_domain
  vpc {
    vpc_id = aws_vpc.main.id
  }
}

# Subnets
resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false
  tags = {
    Name = "reserved"
  }
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
  tags = {
    Name = "sandbox"
