# Security Groups

# Home SSH - SSH from configurable admin CIDRs and from self
resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from admin CIDRs and self"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "Home SSH"
  }
}

# Packer SSH - SSH from VPC CIDR and from self
resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from VPC CIDR and self"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "Packer SSH"
  }
}

# -----------------------------------------------------------------------------
# Data sources — static / well-known lookups only
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Random suffix for bucket naming
# -----------------------------------------------------------------------------
resource "random_pet" "suffix" {
  length  = 2
  prefix  = var.bucket_name
  keepers = {
    bucket_name = var.bucket_name
  }
}

# -----------------------------------------------------------------------------
# Locals — bucket name construction and shared values
# -----------------------------------------------------------------------------
locals {
  account_alias         = var.use_account_alias_prefix ? try(data.aws_iam_account_alias.current[0].account_alias, "") : ""
  account_alias_prefix  = local.account_alias != "" ? "${local.account_alias}-" : ""
  random_suffix_value   = var.use_random_suffix ? "${random_pet.suffix.id}-" : ""
  effective_bucket_name = "${local.account_alias_prefix}${local.random_suffix_value}${var.bucket_name}"

  # Helper for source policy document list
  source_policy_docs = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []
}

# -----------------------------------------------------------------------------
# S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket        = local.effective_bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Ownership controls — BucketOwnerEnforced
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# -----------------------------------------------------------------------------
# Public access block
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Versioning — Enabled by default
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Server-side encryption — AES256 default, KMS when key ID provided
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != "" ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.kms_master_key_id != "" ? var.bucket_key_enabled : null
  }
}

# -----------------------------------------------------------------------------
# Lifecycle configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  # Rule 1: Abort incomplete multipart uploads after 14 days
  rule {
    id     = "abort-incomplete-multipart-upload"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  # Rule 2: Noncurrent version transition and expiration
  rule {
    id     = "noncurrent-version-lifecycle"
    status = "Enabled"

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  # Rule 3: Analytics data expiration (conditional)
  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []
    content {
      id     = "analytics-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  # Rule 4: Inventory data expiration (conditional)
  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []
    content {
      id     = "inventory-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Bucket policy — enforce TLS, allow S3 service writes, extend custom policy
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "this" {
  source_policy_documents = local.source_policy_docs

  statement {
    sid     = "DenyNonTLS"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid     = "AllowS3ServiceInventoryAndAnalytics"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this.json
}

# -----------------------------------------------------------------------------
# Storage class analytics (enabled by default)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "S3BucketAnalytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          prefix     = "_AWSBucketAnalytics/"
          format     = "CSV"
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Bucket inventory (disabled by default)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "S3BucketInventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      format     = "ORC"
      prefix     = "_AWSBucketInventory/"
    }
  }
}

# -----------------------------------------------------------------------------
# Logging — conditional based on logging_bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

# -----------------------------------------------------------------------------
# Transfer acceleration — conditional
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

# -----------------------------------------------------------------------------
# Bucket ACL — conditional
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl
}

# -----------------------------------------------------------------------------
# CORS configuration — dynamic rules
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Whether to prefix the bucket name with the AWS IAM account alias"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to append a random suffix to the bucket name"
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional custom JSON bucket policy document to extend"
  type        = string
  default     = ""
}

variable "kms_master_key_id" {
  description = "KMS key ID to use for SSE-KMS encryption (empty defaults to AES256)"
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for SSE-KMS (only applies when kms_master_key_id is set)"
  type        = bool
  default     = false
}

variable "enable_s3_public_access_block" {
  description = "Enable S3 public access block configuration"
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Allow bucket deletion even when non-empty"
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable storage class analytics export"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable bucket inventory reporting"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target bucket name for S3 server access logs (empty disables logging)"
  type        = string
  default     = ""
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (\"Enabled\" or \"Suspended\", null to disable)"
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply to the bucket (empty disables ACL management)"
  type        = string
  default     = ""
}

variable "cors_rules" {
  description = "List of CORS rule maps, each with allowed_methods, allowed_origins, and optional allowed_headers, expose_headers, max_age_seconds"
  type        = list(any)
  default     = []
}

variable "tags" {
  description = "Tags to apply to the S3 bucket"
  type        = map(string)
  default     = {}
}

# ----------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------

variable "bucket_name" {
  description = "Name of the S3 bucket (max 63 characters). Not used if bucket_name_prefix is set."
  type        = string
  default     = null
  validation {
    condition     = var.bucket_name == null || length(var.bucket_name) <= 63
    error_message = "bucket_name must be at most 63 characters."
  }
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name (max 37 characters); a random suffix is appended."
  type        = string
  default     = null
  validation {
    condition     = var.bucket_name_prefix == null || length(var.bucket_name_prefix) <= 37
    error_message = "bucket_name_prefix must be at most 37 characters."
  }
}

variable "force_destroy" {
  description = "Allow deletion of bucket even if it contains objects."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting. When 'BucketOwnerEnforced' (default), canned ACLs are not used. When 'ObjectWriter', a canned ACL (private) is applied."
  type        = string
  default     = "BucketOwnerEnforced"
  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of: BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict access to only AWS service principals and authorized users."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of the KMS key for SSE-KMS encryption. If null, AES256 is used."
  type        = string
  default     = null
}

variable "enable_versioning" {
  description = "Enable bucket versioning. Defaults to false (Suspended)."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "A custom IAM policy document (JSON) to attach to the bucket. This is merged with an enforced SSL-only deny and optional logging permissions."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs that are allowed to write access logs to this bucket. When non-empty, a logging permission statement is added to the bucket policy."
  type        = list(string)
  default     = []
}

variable "enable_eventbridge" {
  description = "Enable Amazon EventBridge notifications for the S3 bucket."
  type        = bool
  default     = false
}

variable "access_logging_target_bucket" {
  description = "The ARN of the target S3 bucket for server access logging. Mutually exclusive with object lock configuration."
  type        = string
  default     = null
}

variable "access_logging_target_prefix" {
  description = "Prefix for access log objects."
  type        = string
  default     = null
}

variable "object_lock_mode" {
  description = "Default retention mode for object lock (GOVERNANCE or COMPLIANCE). Setting this enables object lock. Mutually exclusive with access logging."
  type        = string
  default     = null
  validation {
    condition     = var.object_lock_mode == null || contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Number of days for the default retention period."
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Number of years for the default retention period."
  type        = number
  default     = null
}

variable "replication_rules" {
  description = <<-EOT
    List of cross-region replication rule objects. Each object supports:
    - priority (number, required)
    - status (string, required: "Enabled" or "Disabled")
    - destination_bucket_arn (string, required)
    - destination_storage_class (optional string)
    - filter_prefix (optional string)
    - filter_tags (optional map(string))
    - delete_marker_replication (optional string, default "Disabled")
    - replica_modifications (optional string, default "Disabled")
    - sse_kms_encrypted_objects (optional bool, default false)
    - replica_kms_key_id (optional string)
  EOT
  type = list(object({
    priority                       = number
    status                         = string
    destination_bucket_arn         = string
    destination_storage_class      = optional(string)
    filter_prefix                  = optional(string)
    filter_tags                    = optional(map(string))
    delete_marker_replication      = optional(string, "Disabled")
    replica_modifications          = optional(string, "Disabled")
    sse_kms_encrypted_objects      = optional(bool, false)
    replica_kms_key_id             = optional(string)
  }))
  default = []
}

variable "inventory_configs" {
  description = <<-EOT
    List of inventory configuration objects. Each object supports:
    - destination_bucket_arn (string, required)
    - destination_prefix (optional string)
    - format (string, required: "Parquet", "CSV", or "ORC")
    - schedule (string, required: "Daily" or "Weekly")
    - included_object_versions (string, required: "Current" or "All")
    - optional_fields (optional list(string))
    - encryption_type (optional string: "SSE-S3" or "SSE-KMS")
    - kms_key_arn (optional string)
  EOT
  type = list(object({
    destination_bucket_arn   = string
    destination_prefix      = optional(string)
    format                  = string
    schedule                = string
    included_object_versions = string
    optional_fields         = optional(list(string))
    encryption_type         = optional(string)
    kms_key_arn             = optional(string)
  }))
  default = []
}

variable "cors_rules" {
  description = <<-EOT
    List of CORS rule objects. Each object supports:
    - allowed_headers (list(string), required)
    - allowed_methods (list(string), required)
    - allowed_origins (list(string), required)
    - expose_headers (optional list(string))
    - max_age_seconds (optional number)
  EOT
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = <<-EOT
    List of lifecycle rule objects. Each object supports:
    - id (string, required)
    - status (optional string, default "Enabled")
    - filter_prefix (optional string)
    - filter_tags (optional map(string))
    - expiration_days (optional number)
    - expiration_date (optional string)
    - expire_delete_marker (optional bool)
    - transitions (optional list of objects with days and storage_class)
    - noncurrent_version_expiration_days (optional number)
    - noncurrent_version_transitions (optional list of objects with days and storage_class)
    - abort_incomplete_multipart_upload_days (optional number)
  EOT
  type = list(object({
    id                                 = string
    status                             = optional(string, "Enabled")
    filter_prefix                      = optional(string)
    filter_tags                        = optional(map(string))
    expiration_days                    = optional(number)
    expiration_date                    = optional(string)
    expire_delete_marker               = optional(bool)
    transitions                        = optional(list(object({
      days          = number
      storage_class = string
    })))
    noncurrent_version_expiration_days = optional(number)
    noncurrent_version_transitions     = optional(list(object({
      days          = number
      storage_class = string
    })))
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

# ----------------------------------------------------------------------
# LOCALS
# ----------------------------------------------------------------------

locals {
  # Generate a bucket name from the name, name_prefix, or a fully random name
  suffix       = random_id.suffix.hex
  bucket_name  = var.bucket_name != null ? var.bucket_name : (
    var.bucket_name_prefix != null ? "${var.bucket_name_prefix}${local.suffix}" : "s3-bucket-${local.suffix}"
  )

  # Encryption decision
  use_kms           = var.kms_key_arn != null
  sse_algorithm     = local.use_kms ? "aws:kms" : "AES256"
  bucket_key_enabled = local.use_kms ? true : false

  # Versioning
  versioning_status = var.enable_versioning ? "Enabled" : "Suspended"

  # Object ownership check – canned ACLs only when ObjectWriter
  use_canned_acl = var.object_ownership == "ObjectWriter"

  # Flags for preconditions
  has_access_logging = var.access_logging_target_bucket != null && var.access_logging_target_bucket != ""
  has_object_lock    = var.object_lock_mode != null

  # Bucket ARN
  bucket_arn  = "arn:aws:s3:::${local.bucket_name}"
  bucket_arn_star = "${local.bucket_arn}/*"
}

# ----------------------------------------------------------------------
# RANDOM SUFFIX
# ----------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

# ----------------------------------------------------------------------
# MAIN S3 BUCKET
# ----------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  # Enable object lock at creation time only if object lock is requested
  object_lock_enabled = local.has_object_lock

  }

# ----------------------------------------------------------------------
# PUBLIC ACCESS BLOCK
# ----------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ----------------------------------------------------------------------
# SERVER-SIDE ENCRYPTION
# ----------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.use_kms ? var.kms_key_arn : null
    }
    bucket_key_enabled = local.bucket_key_enabled
  }
}

# ----------------------------------------------------------------------
# VERSIONING
# ----------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = local.versioning_status
  }
}

# ----------------------------------------------------------------------
# CONDITIONAL CANNED ACL (only when object_ownership == "ObjectWriter")
# ----------------------------------------------------------------------

resource "aws_s3_bucket_acl" "this" {
  count  = local.use_canned_acl ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = "private"
}

# ----------------------------------------------------------------------
# OBJECT OWNERSHIP
# ----------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# ----------------------------------------------------------------------
# CONDITIONAL OBJECT LOCK CONFIGURATION
# ----------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.has_object_lock ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }

  lifecycle {
    precondition {
      condition     = !local.has_access_logging
      error_message = "Object lock configuration cannot be combined with server access logging on the same bucket."
    }
  }
}

# ----------------------------------------------------------------------
# COMBINED BUCKET POLICY
# ----------------------------------------------------------------------

data "aws_iam_policy_document" "combined_bucket_policy" {
  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []

  # Enforced SSL-only deny
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    actions = ["s3:*"]
    resources = [
      local.bucket_arn,
      local.bucket_arn_star,
    ]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # Conditional logging permissions
  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []
    content {
      sid    = "S3ServerAccessLogsPermissions"
      effect = "Allow"
      actions = ["s3:PutObject"]
      resources = [local.bucket_arn_star]
      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined_bucket_policy.json
}

# ----------------------------------------------------------------------
# CONDITIONAL SERVER ACCESS LOGGING
# ----------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  count  = local.has_access_logging ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.access_logging_target_bucket
  target_prefix = var.access_logging_target_prefix

  lifecycle {
    precondition {
      condition     = !local.has_object_lock
      error_message = "Server access logging cannot be combined with object lock configuration on the same bucket."
    }
  }
}

# ----------------------------------------------------------------------
# CONDITIONAL EVENTBRIDGE NOTIFICATION
# ----------------------------------------------------------------------

resource "aws_s3_bucket_notification" "eventbridge" {
  count     = var.enable_eventbridge ? 1 : 0
  bucket    = aws_s3_bucket.this.id
  eventbridge = true
}

# ----------------------------------------------------------------------
# CONDITIONAL CORS CONFIGURATION
# ----------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ----------------------------------------------------------------------
# CONDITIONAL LIFECYCLE CONFIGURATION
# ----------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      # Filter
      filter {
        prefix = rule.value.filter_prefix

        dynamic "tag" {
          for_each = rule.value.filter_tags != null ? [for k, v in rule.value.filter_tags : { key = k, value = v }] : []
          content {
            key   = tag.value.key
            value = tag.value.value
          }
        }
      }

      # Expiration
      dynamic "expiration" {
        for_each = (
          rule.value.expiration_days != null ||
          rule.value.expiration_date != null ||
          rule.value.expire_delete_marker != null
        ) ? [1] : []
        content {
          days                         = rule.value.expiration_days
          date                         = rule.value.expiration_date
          expired_object_delete_marker = rule.value.expire_delete_marker
        }
      }

      # Transitions
      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      # Noncurrent version expiration
      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      # Noncurrent version transitions
      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      # Abort incomplete multipart upload
      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }
}

# ----------------------------------------------------------------------
# CONDITIONAL CROSS-REGION REPLICATION
# ----------------------------------------------------------------------

# IAM role for S3 replication
resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = "${local.bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ReplicationAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for replication
resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = "${local.bucket_name}-replication-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = [local.bucket_arn]
      },
      {
        Sid    = "SourceObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersionAcl",
        ]
        Resource = [local.bucket_arn_star]
      },
      {
        Sid    = "DestinationPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Resource = [for r in var.replication_rules : "${r.destination_bucket_arn}/*"]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = length(var.replication_rules) > 0 ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Replication configuration
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      priority = rule.value.priority
      status   = rule.value.status

      # Filter
      filter {
        prefix = rule.value.filter_prefix

        dynamic "tag" {
          for_each = rule.value.filter_tags != null ? [for k, v in rule.value.filter_tags : { key = k, value = v }] : []
          content {
            key   = tag.value.key
            value = tag.value.value
          }
        }
      }

      # Destination
      destination {
        bucket          = rule.value.destination_bucket_arn
        storage_class   = rule.value.destination_storage_class

        # Replica modification sync (replication_time and metrics)
        dynamic "replication_time" {
          for_each = rule.value.replica_modifications == "Enabled" ? [1] : []
          content {
            status = "Enabled"
            time {
              minutes = 15
            }
          }
        }

        # Metrics
        dynamic "metrics" {
          for_each = rule.value.replica_modifications == "Enabled" ? [1] : []
          content {
            status = "Enabled"
            event_threshold {
              minutes = 15
            }
          }
        }

        # Encryption configuration (KMS key for replica)
        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_key_id != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.replica_kms_key_id
          }
        }
      }

      # Delete marker replication
      delete_marker_replication {
        status = rule.value.delete_marker_replication
      }

      # Source selection criteria for SSE-KMS encrypted objects
      dynamic "source_selection_criteria" {
        for_each = rule.value.sse_kms_encrypted_objects ? [1] : []
        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.replication,
  ]
}

# ----------------------------------------------------------------------
# CONDITIONAL INVENTORY CONFIGURATIONS
# ----------------------------------------------------------------------

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for idx, inv in var.inventory_configs : idx => inv }

  bucket = aws_s3_bucket.this.id
  name   = "inventory-config-${each.key}"

  included_object_versions = each.value.included_object_versions

  # Schedule
  schedule {
    frequency = each.value.schedule
  }

  # Format
  destination {
    bucket {
      format          = each.value.format
      bucket_arn      = each.value.destination_bucket_arn
      prefix          = each.value.destination_prefix

      # Inventory destination encryption (SSE-S3 or SSE-KMS)
      dynamic "encryption" {
        for_each = each.value.encryption_type == "SSE-S3" ? [1] : []
        content {
          sse_s3 {}
        }
      }

      dynamic "encryption" {
        for_each = each.value.encryption_type == "SSE-KMS" ? [1] : []
        content {
          sse_kms {
            key_id = each.value.kms_key_arn != null ? each.value.kms_key_arn : var.kms_key_arn
          }
        }
      }
    }
  }

  # Optional fields (set of strings)
  optional_fields = each.value.optional_fields
}

# ----------------------------------------------------------------------
# OUTPUTS
# ----------------------------------------------------------------------

output "bucket_id" {
  description = "The S3 bucket ID."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The S3 bucket ARN."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The S3 bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The S3 bucket regional domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "designated_region" {
  description = "Single designated AWS region where s3:CreateBucket is allowed"
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket" {
  description = "Name of the remote state S3 bucket to restrict access to"
  type        = string
  default     = "company-terraform-state"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# IAM Account Password Policy
# -----------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 24
}

# -----------------------------------------------------------------------------
# S3 Account Public Access Block
# -----------------------------------------------------------------------------
resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
  path = "/"
}

# -----------------------------------------------------------------------------
# AWS-Managed Policy Attachments — Developer Group
# -----------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# -----------------------------------------------------------------------------
# Custom Policy: Manage Personal Access Keys
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "manage_access_keys" {
  statement {
    sid    = "ManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }
}

resource "aws_iam_policy" "manage_personal_access_keys" {
  name        = "${var.group_name_prefix}_manage_access_keys"
  description = "Allow users to manage their own access keys"
  policy      = data.aws_iam_policy_document.manage_access_keys.json
}

# -----------------------------------------------------------------------------
# Custom Policy: Virtual MFA Devices (require MFA to deactivate)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "manage_virtual_mfa" {
  statement {
    sid    = "AllowActivateOwnMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ListMFADevices",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  statement {
    sid    = "AllowDeactivateOwnMFADeviceWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "manage_virtual_mfa" {
  name        = "${var.group_name_prefix}_manage_virtual_mfa"
  description = "Allow users to manage their own virtual MFA devices, requiring MFA to deactivate"
  policy      = data.aws_iam_policy_document.manage_virtual_mfa.json
}

# -----------------------------------------------------------------------------
# Custom Policy: MFA-gated S3 Access
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "mfa_gated_s3" {
  statement {
    sid    = "DenyS3CreateBucketOutsideDesignatedRegion"
    effect = "Deny"
    actions = [
      "s3:CreateBucket",
    ]
    resources = ["arn:aws:s3:::*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [var.designated_region]
    }
  }

  statement {
    sid    = "DenyS3AccessToRemoteStateBucket"
    effect = "Deny"
    actions = [
      "s3:*",
    ]
    resources = [
      "arn:aws:s3:::${var.remote_state_bucket}",
      "arn:aws:s3:::${var.remote_state_bucket}/*",
    ]
  }
}

resource "aws_iam_policy" "mfa_gated_s3" {
  name        = "${var.group_name_prefix}_mfa_gated_s3"
  description = "Deny S3 CreateBucket outside designated region and deny all S3 access to remote state bucket"
  policy      = data.aws_iam_policy_document.mfa_gated_s3.json
}

# -----------------------------------------------------------------------------
# Custom Policy: MFA-gated Access for EC2, ELB, CloudWatch, AutoScaling
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "mfa_gated_infrastructure" {
  statement {
    sid    = "AllowInfraActionsWithMFA"
    effect = "Allow"
    actions = [
      "autoscaling:*",
      "cloudwatch:*",
      "ec2:*",
      "elasticloadbalancing:*",
    ]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowPassRoleToServiceLinkedRoles"
    effect = "Allow"
    actions = [
      "iam:PassRole",
    ]
    resources = [
      "arn:aws:iam::*:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
      "arn:aws:iam::*:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2",
    ]
  }
}

resource "aws_iam_policy" "mfa_gated_infrastructure" {
  name        = "${var.group_name_prefix}_mfa_gated_infra"
  description = "MFA-gated access for EC2, ELB, CloudWatch, AutoScaling, including service-linked roles"
  policy      = data.aws_iam_policy_document.mfa_gated_infrastructure.json
}

# -----------------------------------------------------------------------------
# Attach Custom Policies to Developer Group
# -----------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "developer_manage_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_personal_access_keys.arn
}

resource "aws_iam_group_policy_attachment" "developer_manage_virtual_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_virtual_mfa.arn
}

resource "aws_iam_group_policy_attachment" "developer_mfa_gated_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.mfa_gated_s3.arn
}

resource "aws_iam_group_policy_attachment" "developer_mfa_gated_infra" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.mfa_gated_infrastructure.arn
}

# -----------------------------------------------------------------------------
# Admin IAM Role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid    = "RootPrincipalAssumeRoleWithMFA"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = "admin"
  description        = "Admin role assumable by the account root principal with MFA"
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role.json
}

# -----------------------------------------------------------------------------
# Full Admin Access Policy (conditioned on MFA)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_full_access" {
  statement {
    sid    = "FullAdminAccessWithMFA"
    effect = "Allow"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_full_access" {
  name        = "admin_full_access"
  description = "Full administrative access conditioned on active MFA"
  policy      = data.aws_iam_policy_document.admin_full_access.json
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

# -----------------------------------------------------------------------------
# Policy Allowing Admin Group to Assume the Admin Role (with MFA)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_group_assume_role" {
  statement {
    sid    = "AllowAssumeAdminRoleWithMFA"
    effect = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_group_assume_role" {
  name        = "${var.group_name_prefix}_assume_admin_role"
  description = "Allow admin group members to assume the admin role when MFA is present"
  policy      = data.aws_iam_policy_document.admin_group_assume_role.json
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_role.arn
}

variable "config" {
  type        = string
  description = "YAML configuration for the CI/CD pipeline orchestration framework"

  default = <<-EOT
    default_role: true
    pipelines: []
  EOT
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  config_data        = yamldecode(var.config)
  pipelines          = { for p in try(local.config_data.pipelines, []) : p.name => p }
  create_default_role = try(local.config_data.default_role, false)

  # CodeStar source pipelines
  codestar_sources = {
    for k, p in local.pipelines : k => p if try(p.source.type, "") == "CodeStar"
  }

  # CodeBuild projects defined in config
  codebuild_projects = try(local.config_data.codebuild_projects, {})

  # Lambda functions defined in config
  lambda_functions = try(local.config_data.lambda_functions, {})

  # Flatten all triggers for EventBridge rules
  all_triggers = flatten([
    for pname, p in local.pipelines : [
      for idx, t in try(p.triggers, []) : {
        pipeline_name = pname
        index         = idx
        rule_key      = "${pname}-${idx}"
        type          = t.type
        branches      = try(t.branches, null)
        tags          = try(t.tags, null)
        cron          = try(t.cron, null)
        pattern       = try(t.pattern, null)
      }
    ]
  ])

  trigger_map = { for t in local.all_triggers : t.rule_key => t }

  # CodeCommit repository ARN for pipelines that use CodeCommit source
  codecommit_repo_arn = {
    for pname, p in local.pipelines : pname => (
      try(p.source.type, "") == "CodeCommit"
      ? "arn:${data.aws_partition.current.partition}:codecommit:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${p.source.repository_name}"
      : ""
    ) if try(p.source.type, "") == "CodeCommit"
  }

  # Build event_pattern for non-schedule triggers
  trigger_event_patterns = {
    for k, t in local.trigger_map : k => (
      t.type == "CodeCommitBranchChange" ? jsonencode({
        source      = ["aws.codecommit"]
        detail-type = ["CodeCommit Repository State Change"]
        resources   = try([local.codecommit_repo_arn[t.pipeline_name]], null)
        detail = {
          event          = ["referenceCreated", "referenceUpdated"]
          referenceType  = ["branch"]
          referenceName  = try(t.branches, [])
        }
      }) :
      t.type == "CodeCommitTagChange" ? jsonencode({
        source      = ["aws.codecommit"]
        detail-type = ["CodeCommit Repository State Change"]
        resources   = try([local.codecommit_repo_arn[t.pipeline_name]], null)
        detail = {
          event          = ["referenceCreated", "referenceUpdated"]
          referenceType  = ["tag"]
          referenceName  = try(t.tags, [])
        }
      }) :
      t.type == "EventPattern" ? jsonencode(t.pattern) :
      null
    ) if t.type != "Schedule"
  }

  # Schedule expressions for schedule triggers
  trigger_schedule_expressions = {
    for k, t in local.trigger_map : k => t.cron if t.type == "Schedule"
  }
}

# ──────────────────────────────────────────────
# KMS Customer Managed Key for S3 Encryption
# ──────────────────────────────────────────────
resource "aws_kms_key" "s3" {
  description             = "KMS CMK for S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

# S3 Artifact Bucket
# ──────────────────────────────────────────────
resource "aws_s3_bucket" "artifacts" {
  bucket        = "codepipeline-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                = aws_s3_bucket.artifacts.id
  block_public_acls     = true
  block_public_policy   = true
  ignore_public_acls    = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ──────────────────────────────────────────────
# S3 Build Cache Bucket
# ──────────────────────────────────────────────
resource "aws_s3_bucket" "build_cache" {
  bucket        = "codebuild-cache-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket                = aws_s3_bucket.build_cache.id
  block_public_acls     = true
  block_public_policy   = true
  ignore_public_acls    = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ──────────────────────────────────────────────
# Default CodePipeline IAM Role (optional)
# ──────────────────────────────────────────────
resource "aws_iam_role" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0
  name  = "CodePipelineDefaultRole"
  path  = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0
  name  = "CodePipelineDefaultPolicy"
  role  = aws_iam_role.codepipeline_default[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GitPull",
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:ListBranches",
          "codecommit:ListRepositories"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeBuildAccess"
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:BatchGetProjects"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECRAccess"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:GetRepositoryPolicy",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DescribeImages",
          "ecr:BatchGetImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:PutImage"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
          aws_s3_bucket.build_cache.arn,
          "${aws_s3_bucket.build_cache.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.s3.arn]
      }
    ]
  })
}

# ──────────────────────────────────────────────
# Pipeline-specific IAM roles (used when default_role is false)
# ──────────────────────────────────────────────
resource "aws_iam_role" "codepipeline_pipeline" {
  for_each = local.create_default_role ? {} : local.pipelines
  name     = "CodePipeline-${each.key}-Role"
  path     = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_pipeline" {
  for_each = local.create_default_role ? {} : local.pipelines
  name     = "CodePipeline-${each.key}-Policy"
  role     = aws_iam_role.codepipeline_pipeline[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GitPull",
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:ListBranches",
          "codecommit:ListRepositories"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeBuildAccess"
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:BatchGetProjects"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECRAccess"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:GetRepositoryPolicy",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DescribeImages",
          "ecr:BatchGetImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:PutImage"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
          aws_s3_bucket.build_cache.arn,
          "${aws_s3_bucket.build_cache.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.s3.arn]
      },
      {
        Sid    = "LambdaInvokeAccess"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "*"
      }
    ]
  })
}

# ──────────────────────────────────────────────
# CodeStar Connections
# ──────────────────────────────────────────────
resource "aws_codestarconnections_connection" "this" {
  for_each = local.codestar_sources

  name          = "${each.key}-codestar-connection"
  provider_type = each.value.source.provider_type
}

# ──────────────────────────────────────────────
# CodeBuild Projects (external modules referenced by pipelines)
# ──────────────────────────────────────────────
resource "aws_iam_role" "codebuild" {
  for_each = local.codebuild_projects
  name     = "codebuild-${each.key}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "codebuild" {
  for_each = local.codebuild_projects
  name     = "codebuild-${each.key}-policy"
  role     = aws_iam_role.codebuild[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
          aws_s3_bucket.build_cache.arn,
          "${aws_s3_bucket.build_cache.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.s3.arn]
      },
      {
        Sid    = "LogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_codebuild_project" "this" {
  for_each = local.codebuild_projects

  name         = each.key
  description  = try(each.value.description, "CodeBuild project for CI/CD pipeline")
  service_role = aws_iam_role.codebuild[each.key].arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type = try(each.value.compute_type, "BUILD_GENERAL1_SMALL")
    image        = try(each.value.image, "aws/codebuild/standard:7.0")
    type         = "LINUX_CONTAINER"
  }

  source {
    type      = try(each.value.source_type, "CODEPIPELINE")
    location  = try(each.value.source_location, null)
    buildspec = try(each.value.buildspec, null)
  }

  build_timeout = try(each.value.build_timeout, 60)
}

# ──────────────────────────────────────────────
# Lambda Functions (external modules referenced by pipelines)
# ──────────────────────────────────────────────
resource "aws_iam_role" "lambda" {
  for_each = local.lambda_functions
  name     = "lambda-${each.key}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  for_each   = local.lambda_functions
  role       = aws_iam_role.lambda[each.key].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "this" {
  for_each = local.lambda_functions

  function_name = try(each.value.function_name, each.key)
  role          = aws_iam_role.lambda[each.key].arn
  handler       = each.value.handler
  runtime       = each.value.runtime
  filename      = try(each.value.filename, null)
  publish       = true

  lifecycle {
    prevent_destroy = true
  }
}

# ──────────────────────────────────────────────
# CodePipeline - One per pipeline definition
# ──────────────────────────────────────────────
resource "aws_codepipeline" "this" {
  for_each = local.pipelines

  name     = each.key
  role_arn = try(
    aws_iam_role.codepipeline_default[0].arn,
    aws_iam_role.codepipeline_pipeline[each.key].arn
  )

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.s3.id
      type = "KMS"
    }
  }

  # Dynamic stages from YAML config
  dynamic "stage" {
    for_each = try(each.value.stages, [])
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])
        content {
          name             = action.value.name
          category         = action.value.category
          owner            = try(action.value.owner, "AWS")
          provider         = action.value.provider
          version          = try(action.value.version, "1")
          input_artifacts  = try(action.value.input_artifacts, null)
          output_artifacts = try(action.value.output_artifacts, null)
          configuration    = try(action.value.configuration, null)
          run_order        = try(action.value.run_order, 1)
        }
      }
    }
  }
}

# ──────────────────────────────────────────────
# EventBridge IAM Roles (terrabits-{pipeline_name})
# ──────────────────────────────────────────────
resource "aws_iam_role" "eventbridge" {
  for_each = local.pipelines
  name     = "terrabits-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge" {
  for_each = local.pipelines
  name     = "terrabits-${each.key}-policy"
  role     = aws_iam_role.eventbridge[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartPipelineExecution"
        Effect = "Allow"
        Action = [
          "codepipeline:StartPipelineExecution"
        ]
        Resource = aws_codepipeline.this[each.key].arn
      }
    ]
  })
}

# ──────────────────────────────────────────────
# EventBridge Rules - One per trigger per pipeline
# ──────────────────────────────────────────────
resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.trigger_map

  name          = "${each.value.pipeline_name}-trigger-${each.value.index}"
  description   = "EventBridge rule for pipeline ${each.value.pipeline_name} trigger ${each.value.index}"
  event_pattern    = try(local.trigger_event_patterns[each.key], null)
  schedule_expression = try(local.trigger_schedule_expressions[each.key], null)
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = local.trigger_map

  rule     = aws_cloudwatch_event_rule.this[each.key].name
  arn      = aws_codepipeline.this[each.value.pipeline_name].arn
  role_arn = aws_iam_role.eventbridge[each.value.pipeline_name].arn
}

# =============================================================================
# VARIABLES
# =============================================================================

variable "create_module" {
  description = "Overall toggle for module resource creation"
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "Toggle to create a new security group (true) or use an existing one (false)"
  type        = bool
  default     = true
}

# -- VPC -------------------------------------------------------------------
variable "vpc_id" {
  description = "ID of an existing VPC. Leave null to create a new VPC."
  type        = string
  default     = null
}

variable "create_vpc" {
  description = "Whether to create a new VPC when vpc_id is not provided"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "main-vpc"
}

# -- Existing security group ------------------------------------------------
variable "existing_security_group_id" {
  description = "ID of an existing security group (required when create_new_sg is false)"
  type        = string
  default     = null
}

# -- New security group ----------------------------------------------------
variable "sg_name" {
  description = "Exact name for the new security group. Omit to use sg_name_prefix."
  type        = string
  default     = null
}

variable "sg_name_prefix" {
  description = "Prefix for the security group name (random suffix appended). Used when sg_name is null or create_before_destroy is true."
  type        = string
  default     = "terraform-sg-"
}

variable "sg_description" {
  description = "Description of the new security group"
  type        = string
  default     = "Security group managed by Terraform"
}

variable "sg_tags" {
  description = "Tags for the new security group"
  type        = map(string)
  default     = {}
}

variable "create_before_destroy" {
  description = "Enable create-before-destroy lifecycle on the security group"
  type        = bool
  default     = true
}

variable "revoke_rules_on_delete" {
  description = "Enable rule revocation when the security group is deleted"
  type        = bool
  default     = true
}

# -- Default egress rule ---------------------------------------------------
variable "add_default_egress_rule" {
  description = "Add a default egress rule allowing all outbound IPv4 traffic"
  type        = bool
  default     = true
}

# -- Ingress rules for new SG ----------------------------------------------
variable "ingress_rules_new_sg" {
  description = "Ingress rules for the newly created security group"
  type = list(object({
    ip_protocol                   = string
    from_port                     = optional(number)
    to_port                       = optional(number)
    cidr_ipv4                     = optional(string)
    cidr_ipv6                     = optional(string)
    referenced_security_group_id  = optional(string)
    prefix_list_id                = optional(string)
    description                   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.ingress_rules_new_sg :
      length(compact([
        r.cidr_ipv4 != null ? "a" : "",
        r.cidr_ipv6 != null ? "a" : "",
        r.referenced_security_group_id != null ? "a" : "",
        r.prefix_list_id != null ? "a" : "",
      ])) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

# -- Egress rules for new SG -----------------------------------------------
variable "egress_rules_new_sg" {
  description = "Egress rules for the newly created security group"
  type = list(object({
    ip_protocol                   = string
    from_port                     = optional(number)
    to_port                       = optional(number)
    cidr_ipv4                     = optional(string)
    cidr_ipv6                     = optional(string)
    referenced_security_group_id  = optional(string)
    prefix_list_id                = optional(string)
    description                   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.egress_rules_new_sg :
      length(compact([
        r.cidr_ipv4 != null ? "a" : "",
        r.cidr_ipv6 != null ? "a" : "",
        r.referenced_security_group_id != null ? "a" : "",
        r.prefix_list_id != null ? "a" : "",
      ])) == 1
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

# -- Ingress rules for existing SG -----------------------------------------
variable "ingress_rules_existing_sg" {
  description = "Ingress rules for the existing security group"
  type = list(object({
    ip_protocol                   = string
    from_port                     = optional(number)
    to_port                       = optional(number)
    cidr_ipv4                     = optional(string)
    cidr_ipv6                     = optional(string)
    referenced_security_group_id  = optional(string)
    prefix_list_id                = optional(string)
    description                   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.ingress_rules_existing_sg :
      length(compact([
        r.cidr_ipv4 != null ? "a" : "",
        r.cidr_ipv6 != null ? "a" : "",
        r.referenced_security_group_id != null ? "a" : "",
        r.prefix_list_id != null ? "a" : "",
      ])) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

# -- Egress rules for existing SG ------------------------------------------
variable "egress_rules_existing_sg" {
  description = "Egress rules for the existing security group"
  type = list(object({
    ip_protocol                   = string
    from_port                     = optional(number)
    to_port                       = optional(number)
    cidr_ipv4                     = optional(string)
    cidr_ipv6                     = optional(string)
    referenced_security_group_id  = optional(string)
    prefix_list_id                = optional(string)
    description                   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.egress_rules_existing_sg :
      length(compact([
        r.cidr_ipv4 != null ? "a" : "",
        r.cidr_ipv6 != null ? "a" : "",
        r.referenced_security_group_id != null ? "a" : "",
        r.prefix_list_id != null ? "a" : "",
      ])) == 1
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

# -- Prefix list -----------------------------------------------------------
variable "create_prefix_list" {
  description = "Toggle to create a customer-managed EC2 prefix list"
  type        = bool
  default     = false
}

variable "existing_prefix_list_ids" {
  description = "List of existing prefix list IDs. When non-empty, no new prefix list is created."
  type        = list(string)
  default     = []
}

variable "prefix_list_name" {
  description = "Name of the customer-managed prefix list"
  type        = string
  default     = "main-prefix-list"
}

variable "prefix_list_address_family" {
  description = "Address family for the prefix list"
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either 'IPv4' or 'IPv6'."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the prefix list"
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "CIDR entries for the prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "prefix_list_tags" {
  description = "Tags for the prefix list"
  type        = map(string)
  default     = {}
}

# =============================================================================
# LOCALS
# =============================================================================

locals {
  create = var.create_module

  # Resolve VPC ID: use provided ID, or the newly created VPC, or null
  vpc_id = local.create ? (
    var.vpc_id != null
    ? var.vpc_id
    : (var.create_vpc ? try(aws_vpc.this[0].id, null) : null)
  ) : null

  # Resolve security group ID: newly created (CBD or non-CBD variant) or existing
  sg_id = local.create ? (
    var.create_new_sg
    ? (
      var.create_before_destroy
      ? try(aws_security_group.new_cbd[0].id, null)
      : try(aws_security_group.new_no_cbd[0].id, null)
    )
    : var.existing_security_group_id
  ) : null

  # Whether to create the prefix list (only when creation is enabled AND no existing IDs supplied)
  create_prefix_list = local.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0
}

# =============================================================================
# VPC
# =============================================================================

resource "aws_vpc" "this" {
  count = local.create && var.create_vpc && var.vpc_id == null ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# =============================================================================
# SECURITY GROUP (new) — create-before-destroy variant
# =============================================================================

resource "aws_security_group" "new_cbd" {
  count = local.create && var.create_new_sg && var.create_before_destroy ? 1 : 0

  name_prefix = var.sg_name_prefix
  description = var.sg_description
  vpc_id      = local.vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = var.sg_tags

  lifecycle {
    create_before_destroy = true
  }
}

# =============================================================================
# SECURITY GROUP (new) — without create-before-destroy
# =============================================================================

resource "aws_security_group" "new_no_cbd" {
  count = local.create && var.create_new_sg && !var.create_before_destroy ? 1 : 0

  name        = var.sg_name
  name_prefix = var.sg_name == null ? var.sg_name_prefix : null
  description = var.sg_description
  vpc_id      = local.vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = var.sg_tags

  lifecycle {
    create_before_destroy = false
  }
}

# =============================================================================
# DEFAULT EGRESS RULE (allow all outbound IPv4)
# =============================================================================

resource "aws_vpc_security_group_egress_rule" "default" {
  count = local.create && var.add_default_egress_rule ? 1 : 0

  security_group_id = local.sg_id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
  description       = "Default egress rule allowing all outbound IPv4 traffic"
}

# =============================================================================
# INGRESS RULES — New Security Group
# =============================================================================

resource "aws_vpc_security_group_ingress_rule" "new_sg" {
  for_each = local.create && var.create_new_sg ? {
    for idx, rule in var.ingress_rules_new_sg : idx => rule
  } : {}

  security_group_id = local.sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description
}

# =============================================================================
# EGRESS RULES — New Security Group
# =============================================================================

resource "aws_vpc_security_group_egress_rule" "new_sg" {
  for_each = local.create && var.create_new_sg ? {
    for idx, rule in var.egress_rules_new_sg : idx => rule
  } : {}

  security_group_id = local.sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description
}

# =============================================================================
# INGRESS RULES — Existing Security Group
# =============================================================================

resource "aws_vpc_security_group_ingress_rule" "existing_sg" {
  for_each = local.create && !var.create_new_sg ? {
    for idx, rule in var.ingress_rules_existing_sg : idx => rule
  } : {}

  security_group_id = local.sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description
}

# =============================================================================
# EGRESS RULES — Existing Security Group
# =============================================================================

resource "aws_vpc_security_group_egress_rule" "existing_sg" {
  for_each = local.create && !var.create_new_sg ? {
    for idx, rule in var.egress_rules_existing_sg : idx => rule
  } : {}

  security_group_id = local.sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description
}

# =============================================================================
# CUSTOMER-MANAGED PREFIX LIST
# =============================================================================

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries
  tags           = var.prefix_list_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ec2_managed_prefix_list_entry" "this" {
  for_each = local.create_prefix_list ? {
    for idx, entry in var.prefix_list_entries : idx => entry
  } : {}

  prefix_list_id = aws_ec2_managed_prefix_list.this[0].id
  cidr           = each.value.cidr
  description    = each.value.description
}

locals {
  environment = "dev"
  common_tags = {
    Environment = local.environment
  }
}

