# ---------------------------------------------------------------------------
# Data sources for static provider metadata
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Server identifier: explicit name variable or random pet name
# ---------------------------------------------------------------------------
resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

locals {
  server_name = var.name != "" ? var.name : random_pet.server_name.id

  is_vpc_mode = var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT"

  create_logging_role    = var.logging_role_arn == ""
  create_api_gateway_role = var.api_gateway_auth
  create_eips            = local.is_vpc_mode && var.address_allocation_ids == null
  create_sg              = local.is_vpc_mode && var.security_group_ids == null

  logging_role_arn_final = var.logging_role_arn != "" ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn

  # CloudWatch log group name
  log_group_name = "/aws/transfer/${local.server_name}"
}

# ---------------------------------------------------------------------------
# IAM: Transfer logging role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "transfer_logging" {
  count = local.create_logging_role ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_logging_assume.json
  tags               = var.tags
}

data "aws_iam_policy_document" "transfer_logging_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = local.create_logging_role ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# ---------------------------------------------------------------------------
# IAM: API Gateway authorization role (when api_gateway_auth is true)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway_auth" {
  count = local.create_api_gateway_role ? 1 : 0

  name               = "${local.server_name}-apigw-auth"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume.json
  tags               = var.tags
}

data "aws_iam_policy_document" "apigw_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "apigw_cloudwatch" {
  count = local.create_api_gateway_role ? 1 : 0

  name        = "${local.server_name}-apigw-cloudwatch"
  description = "Allow API Gateway to write CloudWatch logs for Transfer Family auth"
  policy      = data.aws_iam_policy_document.apigw_cloudwatch.json
  tags        = var.tags
}

data "aws_iam_policy_document" "apigw_cloudwatch" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch" {
  count = local.create_api_gateway_role ? 1 : 0

  role       = aws_iam_role.api_gateway_auth[0].name
  policy_arn = aws_iam_policy.apigw_cloudwatch[0].arn
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group for structured log destinations
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "transfer" {
  name              = local.log_group_name
  retention_in_days = 30
  tags              = var.tags
}

# ---------------------------------------------------------------------------
# VPC resources: Elastic IPs (one per subnet when address_allocation_ids is
# not supplied)
# ---------------------------------------------------------------------------
resource "aws_eip" "transfer" {
  count = local.create_eips ? length(var.subnet_ids) : 0

  domain = "vpc"
  tags   = merge(var.tags, { Name = "${local.server_name}-transfer-eip-${count.index}" })
}

locals {
  address_allocation_ids_final = var.address_allocation_ids != null ? var.address_allocation_ids : (
    local.create_eips ? aws_eip.transfer[*].id : []
  )
}

# ---------------------------------------------------------------------------
# VPC resources: Security Group (port 22 from 0.0.0.0/0)
# ---------------------------------------------------------------------------
resource "aws_security_group" "transfer" {
  count = local.create_sg ? 1 : 0

  name        = "${local.server_name}-transfer-sftp"
  description = "Security group for AWS Transfer Family SFTP server"
  vpc_id      = var.vpc_id
  tags        = merge(var.tags, { Name = "${local.server_name}-transfer-sftp" })
}

resource "aws_vpc_security_group_ingress_rule" "transfer_sftp" {
  count = local.create_sg ? 1 : 0

  security_group_id = aws_security_group.transfer[0].id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  description       = "SFTP access from anywhere"
}

resource "aws_vpc_security_group_egress_rule" "transfer_all" {
  count = local.create_sg ? 1 : 0

  security_group_id = aws_security_group.transfer[0].id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
  description       = "All outbound traffic"
}

locals {
  security_group_ids_final = var.security_group_ids != null ? var.security_group_ids : (
    local.create_sg ? [aws_security_group.transfer[0].id] : []
  )
}

# ---------------------------------------------------------------------------
# AWS Transfer Server
# ---------------------------------------------------------------------------
resource "aws_transfer_server" "main" {
  domain          = var.domain
  endpoint_type   = var.endpoint_type
  protocols       = var.protocols
  logging_role    = local.logging_role_arn_final
  security_policy_name = var.security_policy_name

  # Host key (optional)
  host_key = var.host_key != "" ? var.host_key : null

  # Login banners (optional)
  pre_authentication_login_banner  = var.pre_authentication_login_banner != "" ? var.pre_authentication_login_banner : null
  post_authentication_login_banner = var.post_authentication_login_banner != "" ? var.post_authentication_login_banner : null

  # FTPS certificate (optional)
  certificate = var.certificate_arn != "" ? var.certificate_arn : null

  # API Gateway identity provider
  identity_provider_type = var.api_gateway_auth ? "API_GATEWAY" : "SERVICE_MANAGED"
  url                   = var.api_gateway_auth ? var.api_gateway_url : null
  invocation_role       = var.api_gateway_auth ? aws_iam_role.api_gateway_auth[0].arn : null

  # Structured log destinations
  structured_log_destinations = var.structured_log_destinations != null ? var.structured_log_destinations : null

  # Tags
  tags = merge(var.tags, { Name = local.server_name })

  # Endpoint details (VPC / VPC_ENDPOINT only)
  dynamic "endpoint_details" {
    for_each = local.is_vpc_mode ? [1] : []
    content {
      subnet_ids            = var.subnet_ids
      vpc_id                = var.vpc_id
      address_allocation_ids = local.address_allocation_ids_final
      security_group_ids    = local.security_group_ids_final
    }
  }

  # Protocol details
  dynamic "protocol_details" {
    for_each = (
      var.protocol_details_passive_ip != "" ||
      var.protocol_details_set_stat_option != "" ||
      var.protocol_details_tls_session_resumption_mode != "" ||
      length(var.protocol_details_as2_transports) > 0
    ) ? [1] : []
    content {
      as2_transports              = length(var.protocol_details_as2_transports) > 0 ? var.protocol_details_as2_transports : null
      passive_ip                  = var.protocol_details_passive_ip != "" ? var.protocol_details_passive_ip : null
      set_stat_option             = var.protocol_details_set_stat_option != "" ? var.protocol_details_set_stat_option : null
      tls_session_resumption_mode = var.protocol_details_tls_session_resumption_mode != "" ? var.protocol_details_tls_session_resumption_mode : null
    }
  }

  # S3 storage options
  dynamic "s3_storage_options" {
    for_each = var.s3_storage_options_directory_listing_optimization != "" ? [1] : []
    content {
      directory_listing_optimization = var.s3_storage_options_directory_listing_optimization
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Route 53 CNAME record (when hosted zone is specified)
# ---------------------------------------------------------------------------
resource "aws_route53_record" "transfer" {
  count = var.route53_zone_id != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.route53_subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.main.endpoint]
}

# ---------------------------------------------------------------------------
# SFTP Users: IAM roles, IAM policies, Transfer users, and SSH keys
# ---------------------------------------------------------------------------

# IAM role for each user
resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users

  name               = "${local.server_name}-sftp-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.sftp_user_assume.json
  tags                = var.tags
}

data "aws_iam_policy_document" "sftp_user_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

# IAM policy granting list and object access to the user's S3 home directory
resource "aws_iam_policy" "sftp_user" {
  for_each = var.sftp_users

  name        = "${local.server_name}-sftp-${each.key}-access"
  description = "S3 access policy for SFTP user ${each.key}"
  policy      = data.aws_iam_policy_document.sftp_user[each.key].json
  tags        = var.tags
}

data "aws_iam_policy_document" "sftp_user" {
  for_each = var.sftp_users

  statement {
    sid    = "ListHomeDirectory"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${each.value.home_bucket}"
    ]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = each.value.home_folder != "" ? ["${each.value.home_folder}/*"] : ["*"]
    }
  }

  statement {
    sid    = "ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = each.value.home_folder != "" ? [
      "arn:${data.aws_partition.current.partition}:s3:::${each.value.home_bucket}/${each.value.home_folder}/*"
    ] : [
      "arn:${data.aws_partition.current.partition}:s3:::${each.value.home_bucket}/*"
    ]
  }
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each = var.sftp_users

  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

# AWS Transfer user
resource "aws_transfer_user" "sftp" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.main.id
  user_name = each.key
  role      = aws_iam_role.sftp_user[each.key].arn

  # Home directory
  home_directory_type = try(each.value.home_directory_type, "PATH")
  home_directory      = try(each.value.home_directory, "/${each.value.home_bucket}/${each.value.home_folder}")

  tags = var.tags
}

# SSH public keys (only for users that have an entry in sftp_user_keys)
resource "aws_transfer_ssh_key" "sftp" {
  for_each = {
    for k, v in var.sftp_user_keys : k => v
    if contains(keys(var.sftp_users), k)
  }

  server_id = aws_transfer_server.main.id
  user_name = each.key
  body      = each.value

  depends_on = [aws_transfer_user.sftp]
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "name" {
  description = "Explicit name for the Transfer server. Falls back to a random pet name if empty."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Transfer server endpoint type: PUBLIC, VPC, or VPC_ENDPOINT"
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "List of protocols for the transfer server (e.g. SFTP, FTPS, AS2)"
  type        = set(string)
  default     = ["SFTP"]
}

variable "domain" {
  description = "Storage domain: S3 or EFS"
  type        = string
  default     = "S3"

  validation {
    condition     = contains(["S3", "EFS"], var.domain)
    error_message = "domain must be S3 or EFS."
  }
}

variable "security_policy_name" {
  description = "Security policy name for the transfer server"
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "logging_role_arn" {
  description = "Explicit IAM role ARN for Transfer Family logging. If empty, a role with AWSTransferLoggingAccess is created."
  type        = string
  default     = ""
}

variable "api_gateway_auth" {
  description = "If true, configure API Gateway identity provider and provision an authorization IAM role"
  type        = bool
  default     = false
}

variable "api_gateway_url" {
  description = "API Gateway URL endpoint for identity provider (required when api_gateway_auth is true)"
  type        = string
  default     = ""
}

variable "host_key" {
  description = "Host key for the transfer server (private key PEM)"
  type        = string
  default     = ""
  sensitive   = true
}

variable "pre_authentication_login_banner" {
  description = "Pre-authentication login banner"
  type        = string
  default     = ""
}

variable "post_authentication_login_banner" {
  description = "Post-authentication login banner"
  type        = string
  default     = ""
}

variable "certificate_arn" {
  description = "ACM certificate ARN for FTPS"
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "List of subnet IDs for VPC or VPC_ENDPOINT endpoint types"
  type        = list(string)
  default     = null
}

variable "vpc_id" {
  description = "VPC ID for VPC or VPC_ENDPOINT endpoint types"
  type        = string
  default     = ""
}

variable "address_allocation_ids" {
  description = "List of Elastic IP allocation IDs for VPC mode (one per subnet). If null, EIPs are auto-created."
  type        = list(string)
  default     = null
}

variable "security_group_ids" {
  description = "List of security group IDs for VPC mode. If null, a security group allowing port 22 from 0.0.0.0/0 is auto-created."
  type        = list(string)
  default     = null
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID. If provided, a CNAME record is created for the sub-domain."
  type        = string
  default     = ""
}

variable "route53_subdomain" {
  description = "Sub-domain name for the Route 53 CNAME record"
  type        = string
  default     = "sftp"
}

variable "structured_log_destinations" {
  description = "List of ARNs for CloudWatch log destinations for structured logging"
  type        = list(string)
  default     = null
}

variable "sftp_users" {
  description = "Map of SFTP users. Keys are usernames, values contain home_bucket and optional home_folder."
  type = map(object({
    home_bucket          = string
    home_folder          = optional(string, "/")
    home_directory_type  = optional(string, "PATH")
    home_directory       = optional(string, "")
  }))
  default = {}
}

variable "sftp_user_keys" {
  description = "Map of SSH public keys keyed by username. Only applied for users that also exist in sftp_users."
  type        = map(string)
  default     = {}
}

variable "protocol_details_as2_transports" {
  description = "List of AS2 transport protocols"
  type        = list(string)
  default     = []
}

variable "protocol_details_passive_ip" {
  description = "Passive IP address for FTPS"
  type        = string
  default     = ""
}

variable "protocol_details_set_stat_option" {
  description = "Set stat option: DEFAULT or ENABLE_NO_OP"
  type        = string
  default     = ""
}

variable "protocol_details_tls_session_resumption_mode" {
  description = "TLS session resumption mode: ENFORCED, ENABLED, or DISABLED"
  type        = string
  default     = ""
}

variable "s3_storage_options_directory_listing_optimization" {
  description = "S3 directory listing optimization: ENABLED or DISABLED"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "server_id" {
  description = "The ID of the Transfer server"
  value       = aws_transfer_server.main.id
}

output "server_arn" {
  description = "The ARN of the Transfer server"
  value       = aws_transfer_server.main.arn
}

output "server_endpoint" {
  description = "The endpoint of the Transfer server"
  value       = aws_transfer_server.main.endpoint
}

output "logging_role_arn" {
  description = "The IAM role ARN used for transfer logging"
  value       = local.logging_role_arn_final
}

output "api_gateway_role_arn" {
  description = "The IAM role ARN for API Gateway auth (if created)"
  value       = local.create_api_gateway_role ? aws_iam_role.api_gateway_auth[0].arn : null
}

locals {
  azs = var.availability_zones != null ? var.availability_zones : data.aws_availability_zones.available.names
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/18"
}

variable "availability_zones" {
  description = "List of availability zones. Defaults to all available AZs in the region."
  type        = list(string)
  default     = null
}

variable "create_public_subnets" {
  description = "Whether to create public subnets"
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT Gateway"
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# VPC
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = var.create_public_subnets ? length(local.azs) : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 6, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = var.create_private_subnets ? length(local.azs) : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 6, length(local.azs) + count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count = var.create_nat_gateway && var.create_public_subnets ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# NAT Gateway
resource "aws_nat_gateway" "this" {
  count = var.create_nat_gateway && var.create_public_subnets ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat"
  }

  depends_on = [aws_internet_gateway.this]

  lifecycle {
    prevent_destroy = true
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count = var.create_public_subnets ? length(local.azs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private Route Table
resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  dynamic "route" {
    for_each = var.create_nat_gateway && var.create_public_subnets ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.this[0].id
    }
  }

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count = var.create_private_subnets ? length(local.azs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Public Network ACL
resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-public-nacl"
  }
}

# Public NACL - Inbound Rules
resource "aws_network_acl_rule" "public_inbound_ssh" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_inbound_http" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 200
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_inbound_https" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 300
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_inbound_ephemeral" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 400
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

# Public NACL - Outbound Rules
resource "aws_network_acl_rule" "public_outbound_tcp" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

# Private Network ACL
resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-private-nacl"
  }
}

# Private NACL - Inbound Rules
resource "aws_network_acl_rule" "private_inbound_ssh" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "private_inbound_http" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 200
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_inbound_https" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 300
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_inbound_ephemeral" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 400
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 1024
  to_port        = 65535
}

# Private NACL - Outbound Rules
resource "aws_network_acl_rule" "private_outbound_tcp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

# NACL Subnet Associations
resource "aws_network_acl_association" "public" {
  count = var.create_public_subnets ? length(local.azs) : 0

  network_acl_id = aws_network_acl.public[0].id
  subnet_id      = aws_subnet.public[count.index].id
}

resource "aws_network_acl_association" "private" {
  count = var.create_private_subnets ? length(local.azs) : 0

  network_acl_id = aws_network_acl.private[0].id
  subnet_id      = aws_subnet.private[count.index].id
}

# Fetch available AZs for the region
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr       = "10.16.0.0/16"
  az_count       = 3
  ipv6_enabled   = true
  azs            = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  # list of subnet details: name, AZ key, public/private indicator.
  # 12 subnets total (3 AZs x web/app/db/reserved tiers)
  sn_details = [
    { name = "web",      az_key = 0, public = true  },
    { name = "web",      az_key = 1, public = true  },
    { name = "web",      az_key = 2, public = true  },
    { name = "app",      az_key = 0, public = false },
    { name = "app",      az_key = 1, public = false },
    { name = "app",      az_key = 2, public = false },
    { name = "db",       az_key = 0, public = false },
    { name = "db",       az_key = 1, public = false },
    { name = "db",       az_key = 2, public = false },
    { name = "reserved", az_key = 0, public = false },
    { name = "reserved", az_key = 1, public = false },
    { name = "reserved", az_key = 2, public = false },
  ]
}

# -----------------------------------------------------------------------------
# VPC: dual-stack IPv4 + IPv6, DNS hostnames/support, tenancy default
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = "default"

  assign_generated_ipv6_cidr_block = local.ipv6_enabled

  tags = {
    Name = "main-vpc"
  }
}

# -----------------------------------------------------------------------------
# Subnet CIDR calculation module (hashicorp/subnets/cidr, v1.0.0)
# -----------------------------------------------------------------------------
module "subnet_calcs" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  cidr_block = local.vpc_cidr
  az_count   = local.az_count

  subnet_sets = {
    web = {
      name      = "web"
      cidr_bits = 4   # /20 each (16+4)
      public    = true
    }
    app = {
      name      = "app"
      cidr_bits = 4
      public    = false
    }
    db = {
      name      = "db"
      cidr_bits = 4
      public    = false
    }
    reserved = {
      name      = "reserved"
      cidr_bits = 4
      public    = false
    }
  }
}

# Derive each subnet's CIDR from module output based on tier + AZ key
locals {
  subnet_configs = {
    for idx, sd in local.sn_details : idx => {
      name    = sd.name
      az      = local.azs[sd.az_key]
      az_key  = sd.az_key
      public  = sd.public
      cidr_v4 = module.subnet_calcs.subnet_cidrs[sd.name][sd.az_key]
    }
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "this" {
  for_each = local.subnet_configs

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.az
  cidr_block        = each.value.cidr_v4

  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, each.value.az_key + 4 * (index(["web", "app", "db", "reserved"], each.value.name)))
  assign_ipv6_address_on_creation = each.value.public ? true : false

  tags = {
    Name   = "${each.value.name}-${each.value.az}"
    Tier   = each.value.name
    Role   = each.value.public ? "public" : "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  for_each = {
    for k, v in local.subnet_configs : k => v
    if v.public
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Security group for web tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web-sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Security group for app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app-sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for db tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db-sg"
  }
}

# --- web_sg ingress: 443 from anywhere ---
resource "aws_vpc_security_group_ingress_rule" "web_https" {
  security_group_id = aws_security_group.web_sg.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
  description       = "HTTPS from anywhere"
}

# --- web_sg ingress: 22 from VPC CIDR ---
resource "aws_vpc_security_group_ingress_rule" "web_ssh_vpc" {
  security_group_id = aws_security_group.web_sg.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  description       = "SSH from VPC CIDR"
}

# --- web_sg egress: 443 to app_sg (via reference to app_sg SG id) ---
resource "aws_vpc_security_group_egress_rule" "web_to_app" {
  security_group_id            = aws_security_group.web_sg.id
  referenced_security_group_id = aws_security_group.app_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"
  description                  = "Egress 443 to app_sg"
}

# --- app_sg ingress: 443 from web_sg ---
resource "aws_vpc_security_group_ingress_rule" "app_from_web" {
  security_group_id            = aws_security_group.app_sg.id
  referenced_security_group_id = aws_security_group.web_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"
  description                  = "Ingress 443 from web_sg"
}

# --- app_sg egress: 443 to db_sg ---
resource "aws_vpc_security_group_egress_rule" "app_to_db" {
  security_group_id            = aws_security_group.app_sg.id
  referenced_security_group_id = aws_security_group.db_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"
  description                  = "Egress 443 to db_sg"
}

# --- db_sg ingress: 443 from app_sg ---
resource "aws_vpc_security_group_ingress_rule" "db_from_app" {
  security_group_id            = aws_security_group.db_sg.id
  referenced_security_group_id = aws_security_group.app_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"
  description                  = "Ingress 443 from app_sg"
}

# =============================================================================
# VARIABLES
# =============================================================================

variable "create_vpc" {
  description = "Main toggle to create or skip all VPC resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name prefix applied to VPC and all tagged resources"
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostname resolution for the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support for the VPC"
  type        = bool
  default     = true
}

variable "azs" {
  description = "List of availability zone names or IDs to distribute subnets across. Defaults to all available AZs."
  type        = list(string)
  default     = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for isolated intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Tag suffix for public subnets"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Tag suffix for private subnets"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Tag suffix for intra subnets"
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit Name tag values for public subnets (overrides auto-generation)"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit Name tag values for private subnets (overrides auto-generation)"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit Name tag values for intra subnets (overrides auto-generation)"
  type        = list(string)
  default     = []
}

variable "map_public_ip_on_launch" {
  description = "Assign public IPv4 address to instances launched in public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Toggle to create an Internet Gateway and default public route"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Toggle to provision NAT Gateways and private NAT routes"
  type        = bool
  default     = false
}

# =============================================================================
# LOCALS
# =============================================================================

locals {
  # Effective AZ list: use user-provided list, or fall back to all available AZs
  effective_azs = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names

  # Default VPC name prefix
  vpc_name = var.name != null ? var.name : "vpc"

  # Subnet naming: use explicit names if supplied, otherwise auto-generate from AZ + suffix
  public_subnet_names = length(var.public_subnet_names) > 0 ? var.public_subnet_names : [
    for i, c in var.public_subnet_cidrs :
    format("%s-%s-%s", local.vpc_name, var.public_subnet_suffix, element(local.effective_azs, i % length(local.effective_azs)))
  ]
  private_subnet_names = length(var.private_subnet_names) > 0 ? var.private_subnet_names : [
    for i, c in var.private_subnet_cidrs :
    format("%s-%s-%s", local.vpc_name, var.private_subnet_suffix, element(local.effective_azs, i % length(local.effective_azs)))
  ]
  intra_subnet_names = length(var.intra_subnet_names) > 0 ? var.intra_subnet_names : [
    for i, c in var.intra_subnet_cidrs :
    format("%s-%s-%s", local.vpc_name, var.intra_subnet_suffix, element(local.effective_azs, i % length(local.effective_azs)))
  ]

  # NAT gateway count: minimum of public or private subnet counts
  nat_gateway_count = var.enable_nat_gateway && var.create_vpc ? (
    length(var.public_subnet_cidrs) > 0 && length(var.private_subnet_cidrs) > 0 ? (
      min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs))
    ) : 0
  ) : 0

  # Predicates for clarity
  has_public_subnets  = var.create_vpc && length(var.public_subnet_cidrs) > 0
  has_private_subnets = var.create_vpc && length(var.private_subnet_cidrs) > 0
  has_intra_subnets   = var.create_vpc && length(var.intra_subnet_cidrs) > 0
  use_nat_gateways    = local.nat_gateway_count > 0
}

# =============================================================================
# VPC
# =============================================================================
resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = local.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# INTERNET GATEWAY
# =============================================================================
resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw && local.has_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = {
    Name = format("%s-%s", local.vpc_name, "igw")
  }
}

# =============================================================================
# PUBLIC ROUTE TABLE & DEFAULT ROUTE
# =============================================================================
resource "aws_route_table" "public" {
  count = local.has_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = {
    Name = format("%s-%s", local.vpc_name, "public")
  }
}

resource "aws_route" "public_internet_gateway" {
  count = local.has_public_subnets && var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

# =============================================================================
# PUBLIC SUBNETS & ASSOCIATIONS
# =============================================================================
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(local.effective_azs, count.index % length(local.effective_azs))
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = local.public_subnet_names[count.index]
    Tier = var.public_subnet_suffix
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# =============================================================================
# ELASTIC IPs & NAT GATEWAYS
# =============================================================================
resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = {
    Name = format("%s-nat-%d", local.vpc_name, count.index + 1)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = format("%s-nat-%d", local.vpc_name, count.index + 1)
  }

  depends_on = [aws_internet_gateway.this]

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# PRIVATE ROUTE TABLES (with NAT routes)
# =============================================================================
resource "aws_route_table" "private" {
  count = local.nat_gateway_count

  vpc_id = aws_vpc.this[0].id

  tags = {
    Name = format("%s-private-%d", local.vpc_name, count.index + 1)
  }
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

# =============================================================================
# PRIVATE SUBNETS
# =============================================================================
resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = element(local.effective_azs, count.index % length(local.effective_azs))

  tags = {
    Name = local.private_subnet_names[count.index]
    Tier = var.private_subnet_suffix
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Private route table associations (when NAT gateways exist)
resource "aws_route_table_association" "private" {
  count = local.use_nat_gateways ? length(var.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index % local.nat_gateway_count].id
}

# Private route tables WITHOUT NAT (isolated — no internet route)
resource "aws_route_table" "private_no_nat" {
  count = local.has_private_subnets && !local.use_nat_gateways ? length(var.private_subnet_cidrs) : 0

  vpc_id = aws_vpc.this[0].id

  tags = {
    Name = format("%s-private-%d", local.vpc_name, count.index + 1)
  }
}

resource "aws_route_table_association" "private_no_nat" {
  count = local.has_private_subnets && !local.use_nat_gateways ? length(var.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_no_nat[count.index].id
}

# =============================================================================
# INTRA (ISOLATED) SUBNETS
# =============================================================================
resource "aws_subnet" "intra" {
  count = length(var.intra_subnet_cidrs)

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.intra_subnet_cidrs[count.index]
  availability_zone = element(local.effective_azs, count.index % length(local.effective_azs))

  tags = {
    Name = local.intra_subnet_names[count.index]
    Tier = var.intra_subnet_suffix
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "intra" {
  count = length(var.intra_subnet_cidrs)

  vpc_id = aws_vpc.this[0].id

  tags = {
    Name = format("%s-%s-%d", local.vpc_name, var.intra_subnet_suffix, count.index + 1)
  }
}

resource "aws_route_table_association" "intra" {
  count = length(var.intra_subnet_cidrs)

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

# =============================================================================
# OUTPUTS
# =============================================================================

output "vpc_id" {
  description = "The ID of the created VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_arn" {
  description = "The ARN of the created VPC"
  value       = try(aws_vpc.this[0].arn, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the created VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "public_subnet_ids" {
  description = "List of IDs of the created public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of the created private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "List of IDs of the created intra subnets"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of IDs of the private route tables"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "List of IDs of the intra route tables"
  value       = aws_route_table.intra[*].id
}

output "nat_gateway_ids" {
  description = "List of IDs of the NAT Gateways"
  value       = aws_nat_gateway.this[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_eip_public_ips" {
  description = "List of public Elastic IP addresses assigned to NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}

# =============================================================================
# Variables
# =============================================================================

variable "api_type" {
  description = "The type of API Gateway to provision: \"http\" (v2) or \"rest\" (v1)"
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either \"http\" or \"rest\"."
  }
}

variable "api_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name used for stage naming and resource tagging"
  type        = string
  default     = "dev"
}

variable "vpc_link_enabled" {
  description = "Enable creation of VPC Link resources"
  type        = bool
  default     = false
}

variable "vpc_id" {
  description = "VPC ID for VPC Link and NLB resources"
  type        = string
  default     = null
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for VPC Link / NLB"
  type        = list(string)
  default     = []
}

variable "custom_domain_enabled" {
  description = "Enable custom domain name mapping"
  type        = bool
  default     = false
}

variable "domain_name" {
  description = "Custom domain name"
  type        = string
  default     = null
}

variable "certificate_arn" {
  description = "ARN of the ACM certificate for the custom domain"
  type        = string
  default     = null
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for alias A record"
  type        = string
  default     = null
}

variable "http_routes" {
  description = "Map of routes for HTTP API (v2). Key = route key, value = route config."
  type = map(object({
    route_key           = string
    target_type         = optional(string, "INTEGRATION")
    integration         = optional(string)
    authorization_type  = optional(string, "NONE")
    authorizer_id       = optional(string)
  }))
  default = {}
}

variable "rest_resources" {
  description = "Map of REST API resource paths. Key = path part, value = parent path or null for root."
  type = map(object({
    parent_path = optional(string)
  }))
  default = {}
}

variable "rest_methods" {
  description = "Map of REST API methods. Key = resource path, value = method config."
  type = map(object({
    http_method                = string
    authorization              = optional(string, "NONE")
    authorizer_id              = optional(string)
    api_key_required           = optional(bool, false)
    path_parameter_override    = optional(string)
    integration_type           = optional(string, "MOCK")
    integration_uri            = optional(string)
  }))
  default = {}
}

variable "rest_resource_policy" {
  description = "JSON resource policy for REST API (for IP source restriction)"
  type        = string
  default     = null
}

variable "lambda_authorizer_enabled" {
  description = "Enable creation of a custom Lambda authorizer"
  type        = bool
  default     = false
}

variable "lambda_authorizer_name" {
  description = "Name of the Lambda authorizer function"
  type        = string
  default     = "api-authorizer"
}

variable "usage_plan_enabled" {
  description = "Enable creation of usage plan and API keys for REST APIs"
  type        = bool
  default     = false
}

variable "nlb_target_alb_id" {
  description = "ALB ID (ARN) for NLB target group when VPC link is enabled for REST API"
  type        = string
  default     = null
}

variable "nlb_target_port" {
  description = "TCP port for NLB target group"
  type        = number
  default     = 443
}

# =============================================================================
# Locals
# =============================================================================

locals {
  stage_name = "${var.environment}-stage"
}

# =============================================================================
# Data sources
# =============================================================================

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# =============================================================================
# Archive for Lambda authorizer inline code
# =============================================================================

data "archive_file" "authorizer_lambda" {
  count = var.lambda_authorizer_enabled ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/authorizer_lambda.zip"

  source {
    content  = <<EOT
exports.handler = async (event, context) => {
  const principalId = event.headers && event.headers.Authorization
    ? 'user'
    : 'unauthorized';

  const effect = principalId === 'unauthorized' ? 'Deny' : 'Allow';

  return {
    principalId: principalId,
    policyDocument: {
      Version: '2012-10-17',
      Statement: [{
        Action: 'execute-api:Invoke',
        Effect: effect,
        Resource: event.methodArn
      }]
    }
  };
};
EOT
    filename = "index.js"
  }
}

# =============================================================================
# Lambda IAM Role & Policy (for Lambda Authorizer)
# =============================================================================

resource "aws_iam_role" "lambda_authorizer_role" {
  count = var.lambda_authorizer_enabled ? 1 : 0

  name = "${var.environment}-${var.lambda_authorizer_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_authorizer_policy" {
  count = var.lambda_authorizer_enabled ? 1 : 0

  name = "${var.environment}-${var.lambda_authorizer_name}-policy"
  role = aws_iam_role.lambda_authorizer_role[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/${var.lambda_authorizer_name}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Resource = "*"
      }
    ]
  })
}

# =============================================================================
# Lambda Authorizer Function (Node.js 16.x)
# =============================================================================

resource "aws_lambda_function" "authorizer" {
  count = var.lambda_authorizer_enabled ? 1 : 0

  filename         = data.archive_file.authorizer_lambda[0].output_path
  source_code_hash = data.archive_file.authorizer_lambda[0].output_base64sha256
  function_name    = var.lambda_authorizer_name
  role             = aws_iam_role.lambda_authorizer_role[0].arn
  handler          = "index.handler"
  runtime          = "nodejs16.x"
  timeout          = 10
}

# =============================================================================
# Lambda Authorizer Permission for API Gateway invoke
# =============================================================================

resource "aws_lambda_permission" "authorizer_invoke" {
  count = var.lambda_authorizer_enabled ? 1 : 0

  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"

  source_arn = "arn:${data.aws_partition.current.partition}:execute-api:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:*/*"
}

# =============================================================================
# HTTP API v2 Authorizer
# =============================================================================

resource "aws_apigatewayv2_authorizer" "http" {
  count = var.api_type == "http" && var.lambda_authorizer_enabled ? 1 : 0

  api_id           = aws_apigatewayv2_api.http[0].id
  authorizer_type  = "REQUEST"
  authorizer_uri   = aws_lambda_function.authorizer[0].invoke_arn
  identity_sources = ["$request.header.Authorization"]
  name             = "${var.lambda_authorizer_name}-v2"
}

# =============================================================================
# REST API v1 Authorizer
# =============================================================================

resource "aws_api_gateway_authorizer" "rest" {
  count = var.api_type == "rest" && var.lambda_authorizer_enabled ? 1 : 0

  name           = "${var.lambda_authorizer_name}-v1"
  rest_api_id    = aws_api_gateway_rest_api.rest[0].id
  authorizer_uri = aws_lambda_function.authorizer[0].invoke_arn
  type           = "TOKEN"

  identity_source = "method.request.header.Authorization"
}

# =============================================================================
# HTTP API (v2)
# =============================================================================

resource "aws_apigatewayv2_api" "http" {
  count = var.api_type == "http" ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"

  cors_configuration {
    allow_origins = ["*"]
    allow_methods = ["GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS"]
    allow_headers = ["*"]
  }
}

# =============================================================================
# HTTP API VPC Link
# =============================================================================

resource "aws_security_group" "vpc_link_http" {
  count = var.api_type == "http" && var.vpc_link_enabled ? 1 : 0

  name        = "${var.environment}-${var.api_name}-vpc-link-sg"
  description = "Security group for HTTP API VPC Link"
  vpc_id      = var.vpc_id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count = var.api_type == "http" && var.vpc_link_enabled ? 1 : 0

  name               = "${var.environment}-${var.api_name}-vpc-link"
  security_group_ids = [aws_security_group.vpc_link_http[0].id]
  subnet_ids         = var.private_subnet_ids
}

# =============================================================================
# HTTP API Stage (auto-deploy)
# =============================================================================

resource "aws_apigatewayv2_stage" "http" {
  count = var.api_type == "http" ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true

  default_route_settings {
    throttling_burst_limit = 5000
    throttling_rate_limit  = 10000
  }
}

# =============================================================================
# HTTP API Routes
# =============================================================================

resource "aws_apigatewayv2_route" "http" {
  for_each = var.api_type == "http" ? var.http_routes : {}

  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = each.value.route_key

  target = each.value.target_type == "INTEGRATION" && each.value.integration != null ? "integrations/${each.value.integration}" : null

  authorization_type = each.value.authorization_type
  authorizer_id      = each.value.authorizer_id
}

# =============================================================================
# HTTP API Custom Domain
# =============================================================================

resource "aws_apigatewayv2_domain_name" "http" {
  count = var.api_type == "http" && var.custom_domain_enabled ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = var.certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = var.api_type == "http" && var.custom_domain_enabled ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

# =============================================================================
# Route53 Alias A Record for HTTP API Custom Domain
# =============================================================================

resource "aws_route53_record" "http_custom_domain" {
  count = var.api_type == "http" && var.custom_domain_enabled && var.route53_zone_id != null ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# =============================================================================
# REST API (v1)
# =============================================================================

resource "aws_api_gateway_rest_api" "rest" {
  count = var.api_type == "rest" ? 1 : 0

  name        = var.api_name
  description = "REST API managed by Terraform"

  policy = var.rest_resource_policy != null ? var.rest_resource_policy : null

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

# =============================================================================
# REST API Resources
# =============================================================================

resource "aws_api_gateway_resource" "rest" {
  for_each = var.api_type == "rest" ? var.rest_resources : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = each.value.parent_path != null ? (
    try(aws_api_gateway_resource.rest[each.value.parent_path].id, aws_api_gateway_rest_api.rest[0].root_resource_id)
  ) : aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part = each.key
}

# =============================================================================
# REST API Methods
# =============================================================================

resource "aws_api_gateway_method" "rest" {
  for_each = var.api_type == "rest" ? var.rest_methods : {}

  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest[each.key].id
  http_method   = each.value.http_method
  authorization = each.value.authorization
  authorizer_id = each.value.authorizer_id
  api_key_required = each.value.api_key_required

  request_parameters = each.value.path_parameter_override != null ? {
    "method.request.path.${each.value.path_parameter_override}" = true
  } : {}
}

resource "aws_api_gateway_integration" "rest" {
  for_each = var.api_type == "rest" ? var.rest_methods : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.key].id
  http_method = aws_api_gateway_method.rest[each.key].http_method

  type        = each.value.integration_type
  uri         = each.value.integration_uri
  integration_http_method = each.value.integration_type == "MOCK" ? null : "POST"
}

# =============================================================================
# REST API Deployment with redeploy trigger
# =============================================================================

resource "aws_api_gateway_deployment" "rest" {
  count = var.api_type == "rest" ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_rest_api.rest[0].body,
      aws_api_gateway_resource.rest,
      aws_api_gateway_method.rest,
      aws_api_gateway_integration.rest,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = var.api_type == "rest" ? 1 : 0

  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
}

# =============================================================================
# REST API Custom Domain
# =============================================================================

resource "aws_api_gateway_domain_name" "rest" {
  count = var.api_type == "rest" && var.custom_domain_enabled ? 1 : 0

  domain_name              = var.domain_name
  regional_certificate_arn = var.certificate_arn

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  security_policy = "TLS_1_2"
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count = var.api_type == "rest" && var.custom_domain_enabled ? 1 : 0

  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

# =============================================================================
# Route53 Alias A Record for REST API Custom Domain
# =============================================================================

resource "aws_route53_record" "rest_custom_domain" {
  count = var.api_type == "rest" && var.custom_domain_enabled && var.route53_zone_id != null ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

# =============================================================================
# REST API Usage Plan & API Keys
# =============================================================================

resource "aws_api_gateway_api_key" "rest" {
  count = var.api_type == "rest" && var.usage_plan_enabled ? 1 : 0

  name = "${var.environment}-${var.api_name}-api-key"
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = var.api_type == "rest" && var.usage_plan_enabled ? 1 : 0

  name = "${var.environment}-${var.api_name}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  quota_settings {
    limit  = 10000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 5000
    rate_limit  = 10000
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = var.api_type == "rest" && var.usage_plan_enabled ? 1 : 0

  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

# =============================================================================
# SSM Parameter Store for API Key (SecureString)
# =============================================================================

resource "aws_ssm_parameter" "api_key" {
  count = var.api_type == "rest" && var.usage_plan_enabled ? 1 : 0

  name  = "/${var.environment}/api-gateway/${var.api_name}/api-key"
  type  = "SecureString"
  value = aws_api_gateway_api_key.rest[0].value

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# REST API VPC Link — NLB, Target Group, Listener
# =============================================================================

resource "aws_lb" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0

  name               = "${var.environment}-${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = var.private_subnet_ids
}

resource "aws_lb_target_group" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0

  name     = "${var.environment}-${var.api_name}-tg"
  port     = var.nlb_target_port
  protocol = "TCP"
  vpc_id   = var.vpc_id

  health_check {
    enabled  = true
    protocol = "HTTPS"
    port     = tostring(var.nlb_target_port)
  }

  target_type = "ip"
}

resource "aws_lb_target_group_attachment" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled && var.nlb_target_alb_id != null ? 1 : 0

  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = var.nlb_target_alb_id
  port             = var.nlb_target_port
}

resource "aws_lb_listener" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0

  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.nlb_target_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0

  name        = "${var.environment}-${var.api_name}-vpc-link"
  description = "VPC Link for REST API"
  target_arns = [aws_lb.nlb[0].arn]
}

# =============================================================================
# Outputs
# =============================================================================

output "api_type" {
  value = var.api_type
}

output "stage_name" {
  value = local.stage_name
}

output "http_api_id" {
  value = var.api_type == "http" ? aws_apigatewayv2_api.http[0].id : null
}

output "http_api_endpoint" {
  value = var.api_type == "http" ? aws_apigatewayv2_api.http[0].api_endpoint : null
}

output "rest_api_id" {
  value = var.api_type == "rest" ? aws_api_gateway_rest_api.rest[0].id : null
}

output "rest_execution_arn" {
  value = var.api_type == "rest" ? aws_api_gateway_rest_api.rest[0].execution_arn : null
}

output "rest_api_key_value" {
  value     = var.api_type == "rest" && var.usage_plan_enabled ? aws_api_gateway_api_key.rest[0].value : null
  sensitive = true
}

output "nlb_arn" {
  value = var.api_type == "rest" && var.vpc_link_enabled ? aws_lb.nlb[0].arn : null
}

output "vpc_link_id" {
  value = var.api_type == "rest" && var.vpc_link_enabled ? aws_api_gateway_vpc_link.rest[0].id : (
    var.api_type == "http" && var.vpc_link_enabled ? aws_apigatewayv2_vpc_link.http[0].id : null
  )
}

# ============================================================
# Input Variables
# ============================================================

variable "bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. If empty, a name is auto-generated from account ID, region, and random suffix."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Allow force-destroy of the S3 bucket even when it contains objects."
  type        = bool
  default     = true
}

variable "enable_versioning" {
  description = "Enable versioning on the S3 bucket."
  type        = bool
  default     = false
}

variable "kms_key_deletion_window" {
  description = "Waiting period (days) before KMS key deletion."
  type        = number
  default     = 30
}

variable "kms_key_alias_prefix" {
  description = "Prefix to use for the KMS key alias."
  type        = string
  default     = "cloudtrail-"
}

variable "cloudtrail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "account-trail"
}

variable "log_retention_days" {
  description = "Number of days to retain CloudWatch log events."
  type        = number
  default     = 90
}

variable "enable_log_file_validation" {
  description = "Enable log file validation for CloudTrail."
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Include global service events in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Create a multi-region trail."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Create an organization trail (requires management account)."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Read/write type for management events (All, ReadOnly, or WriteOnly)."
  type        = string
  default     = "All"
}

variable "enable_management_events" {
  description = "Include management events in the trail."
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selectors. Each entry has a type and list of values."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of insight selectors. Each entry has an insight_type (ApiCallRateInsight or ApiErrorRateInsight)."
  type = list(object({
    insight_type = string
  }))
  default = []
}

variable "create_sns_topic" {
  description = "Create an SNS topic for CloudTrail alerts."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of an existing SNS topic for CloudTrail notifications. Ignored when create_sns_topic is true."
  type        = string
  default     = ""
}

variable "log_decryption_role_arn" {
  description = "ARN of an IAM role that should be granted KMS decrypt permissions for log decryption."
  type        = string
  default     = ""
}

# ============================================================
# Data Sources (static metadata only)
# ============================================================

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ============================================================
# Random Suffix for Dynamic Bucket Name
# ============================================================

resource "random_id" "suffix" {
  byte_length = 4
}

# ============================================================
# Local Values
# ============================================================

locals {
  # S3 bucket name: use provided name or auto-generate with account ID, region, and suffix
  bucket_name = var.bucket_name != "" ? var.bucket_name : "cloudtrail-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}-${random_id.suffix.hex}"

  # Effective SNS topic ARN (prioritise created topic, then provided ARN, then empty)
  effective_sns_topic_arn = var.create_sns_topic ? aws_sns_topic.cloudtrail_alerts[0].arn : var.sns_topic_arn
}

# ============================================================
# KMS Key and Alias
# ============================================================

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = var.kms_key_deletion_window
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.kms_key_alias_prefix}${var.cloudtrail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailEncryption"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.region}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.log_decryption_role_arn != "" ? [1] : []
    content {
      sid    = "AllowLogDecryptionRole"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [var.log_decryption_role_arn]
      }
      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:ReEncrypt*",
      ]
      resources = ["*"]
    }
  }
}

# ============================================================
# S3 Bucket and Configuration
# ============================================================

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket                = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls     = true
  block_public_policy   = true
  ignore_public_acls    = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.s3_bucket_policy.json
}

# ============================================================
# CloudWatch Log Group
# ============================================================

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "/aws/cloudtrail/${var.cloudtrail_name}"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  lifecycle {
    prevent_destroy = true
  }
}

# ============================================================
# IAM Role and Policy for CloudTrail CloudWatch Logs Delivery
# ============================================================

data "aws_iam_policy_document" "cloudwatch_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "CloudTrailCloudWatchLogsRole-${var.cloudtrail_name}"
  assume_role_policy = data.aws_iam_policy_document.cloudwatch_assume_role.json
}

data "aws_iam_policy_document" "cloudwatch_logs_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "CloudTrailCloudWatchLogsPolicy"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudwatch_logs_policy.json
}

# ============================================================
# SNS Topic (Optional, disabled by default)
# ============================================================

resource "aws_sns_topic" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0

  name = "cloudtrail-alerts-${var.cloudtrail_name}"
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid    = "AllowCloudTrailPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.cloudtrail_alerts[0].arn]
  }
}

resource "aws_sns_topic_policy" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail_alerts[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

# ============================================================
# CloudTrail Trail
# ============================================================

resource "aws_cloudtrail" "main" {
  name                          = var.cloudtrail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = "AWSLogs"
  enable_log_file_validation    = var.enable_log_file_validation
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn

  cloud_watch_logs_group_arn = aws_cloudwatch_log_group.cloudtrail.arn
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch.arn

  sns_topic_name = local.effective_sns_topic_arn != "" ? local.effective_sns_topic_arn : null

  event_selector {
    read_write_type           = var.read_write_type
    include_management_events = var.enable_management_events

    dynamic "data_resource" {
      for_each = var.data_resource_selectors
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors
    content {
      insight_type = insight_selector.value.insight_type
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "legion"
}

locals {
  cluster_name    = var.cluster_name
  master_role_name = "tf-${local.cluster_name}"
  node_role_name   = "tf-${local.cluster_name}-node"
}

# ── Master (Control Plane) Role ──────────────────────────────────────────────

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "master" {
  name               = local.master_role_name
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "master_eks_cluster" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "master_eks_service" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSServicePolicy"
}

# ── Worker Node Role ─────────────────────────────────────────────────────────

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "node" {
  name               = local.node_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_readonly" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# ── Instance Profile ─────────────────────────────────────────────────────────

resource "aws_iam_instance_profile" "node" {
  name = local.node_role_name
  role = aws_iam_role.node.name
}

# ── Custom Autoscaling Policy ────────────────────────────────────────────────

data "aws_iam_policy_document" "cluster_autoscaler" {
  statement {
    sid    = "DescribeAutoScaling"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeLaunchTemplateVersions",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ModifyAutoScalingTagged"
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${local.cluster_name}"
      values   = ["owned"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "cluster_autoscaler" {
  name        = "eks-worker-autoscaling-${local.cluster_name}"
  description = "Policy for EKS Cluster Autoscaler on worker nodes"
  policy      = data.aws_iam_policy_document.cluster_autoscaler.json
}

resource "aws_iam_role_policy_attachment" "node_autoscaling" {
  role       = aws_iam_role.node.name
  policy_arn = aws_iam_policy.cluster_autoscaler.arn
}

# ── Data Sources ─────────────────────────────────────────────────────────────

data "aws_partition" "current" {}

locals {
  admin_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })

  # Shared policy for the github group (ACM, CloudFront, IAM, Lambda, Route53, S3, SQS)
  # S3 actions are scoped to specific deployment-related operations
  github_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "acm:*",
          "cloudfront:*",
          "iam:*",
          "lambda:*",
          "route53:*",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
          "s3:GetBucketLocation",
          "s3:GetBucketPolicy",
          "s3:PutBucketPolicy",
          "s3:CreateBucket",
          "s3:PutBucketAcl",
          "s3:GetBucketAcl",
          "s3:PutBucketVersioning",
          "s3:GetBucketVersioning",
          "s3:PutBucketPublicAccessBlock",
          "s3:GetBucketPublicAccessBlock",
          "s3:PutEncryptionConfiguration",
          "s3:GetEncryptionConfiguration",
          "sqs:*"
        ]
        Resource = "*"
      }
    ]
  })

  # Shared policy for serverless (ACM, CloudFront, IAM, Lambda, CloudWatch Logs, Route53, S3, SQS)
  # S3 actions are scoped to specific deployment-related operations
  serverless_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "acm:*",
          "cloudfront:*",
          "iam:*",
          "lambda:*",
          "logs:*",
          "route53:*",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
          "s3:GetBucketLocation",
          "s3:GetBucketPolicy",
          "s3:PutBucketPolicy",
          "s3:CreateBucket",
          "s3:PutBucketAcl",
          "s3:GetBucketAcl",
          "s3:PutBucketVersioning",
          "s3:GetBucketVersioning",
          "s3:PutBucketPublicAccessBlock",
          "s3:GetBucketPublicAccessBlock",
          "s3:PutEncryptionConfiguration",
          "s3:GetEncryptionConfiguration",
          "sqs:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM Groups
# ---------------------------------------------------------------------------

resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ---------------------------------------------------------------------------
# IAM Group Inline Policies
# ---------------------------------------------------------------------------

resource "aws_iam_group_policy" "admin" {
  name   = "admin-full-access"
  group  = aws_iam_group.admin.name
  policy = local.admin_policy
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-full-access"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = local.admin_policy
}

resource "aws_iam_group_policy" "github" {
  name   = "github-targeted-access"
  group  = aws_iam_group.github.name
  policy = local.github_policy
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless-dedicated-access"
  group  = aws_iam_group.serverless.name
  policy = local.serverless_policy
}

# ---------------------------------------------------------------------------
# IAM Users
# ---------------------------------------------------------------------------

resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/admin/"
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_user" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ---------------------------------------------------------------------------
# IAM Group Memberships
# ---------------------------------------------------------------------------

resource "aws_iam_group_membership" "admin" {
  name  = "admin-membership"
  group = aws_iam_group.admin.name
  users = [
    aws_iam_user.admin.name,
    aws_iam_user.admin_macbook_pro.name
  ]
}

resource "aws_iam_group_membership" "admin_terraform_cloud" {
  name  = "admin-terraform-cloud-membership"
  group = aws_iam_group.admin_terraform_cloud.name
  users = [
    aws_iam_user.admin_terraform_cloud.name
  ]
}

resource "aws_iam_group_membership" "github" {
  name  = "github-membership"
  group = aws_iam_group.github.name
  users = [
    aws_iam_user.github.name
  ]
}

resource "aws_iam_group_membership" "serverless" {
  name  = "serverless-membership"
  group = aws_iam_group.serverless.name
  users = [
    aws_iam_user.serverless.name
  ]
