}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

# ---------------------------------------------------------------------------
# IAM Role "serverless" for Lambda / Edge Lambda trust
# ---------------------------------------------------------------------------

resource "aws_iam_role" "serverless" {
  name = "serverless"
  path = "/serverless/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "lambda.amazonaws.com",
            "edgelambda.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Customer Managed Policy "serverless" (attached to the serverless role)
# ---------------------------------------------------------------------------

resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Customer managed policy granting serverless service access"
  policy      = local.serverless_policy
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

# Data sources for account metadata
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Input variables
# ---------------------------------------------------------------------------

variable "namespace" {
  description = "Namespace for the CloudPosse label module"
  type        = string
  default     = "eg"
}

variable "environment" {
  description = "Environment for the CloudPosse label module"
  type        = string
  default     = "default"
}

variable "name" {
  description = "Name for the CloudPosse label module"
  type        = string
  default     = "iam"
}

variable "tags" {
  description = "Additional tags for the label module"
  type        = map(string)
  default     = {}
}

variable "attributes" {
  description = "Additional attributes for the CloudPosse label module"
  type        = list(string)
  default     = []
}

variable "admin_users" {
  description = "List of IAM user names to place in the admin group"
  type        = list(string)
  default     = []
}

variable "non_admin_users" {
  description = "List of IAM user names to place in the non-admin group"
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------------
# CloudPosse label module for consistent naming
# ---------------------------------------------------------------------------

module "this" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  tags        = var.tags
}

# ---------------------------------------------------------------------------
# IAM Groups
# ---------------------------------------------------------------------------

resource "aws_iam_group" "admin" {
  name = "${module.this.id}-admin"
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = "${module.this.id}-non-admin"
  path = "/"
}

# ---------------------------------------------------------------------------
# Self-management policy (attached to both groups)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "SelfManagementStandard"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:GetUser",
      "iam:GetLoginProfile",
      "iam:ListMFADevices",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "SelfManagementDeactivateMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AccountReadOnlyActions"
    effect = "Allow"
    actions = [
      "iam:ListVirtualMFADevices",
      "iam:GetAccountPasswordPolicy",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.this.id}-self-management"
  path        = "/"
  description = "Self-management policy for passwords, access keys, and virtual MFA devices"
  policy      = data.aws_iam_policy_document.self_management.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy_attachment" "self_management_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "self_management_non_admin" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# ---------------------------------------------------------------------------
# Admin role (trust policy targets account root principal with MFA)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = "${module.this.id}-admin-role"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  description        = "Admin role requiring MFA for assumption, with AdministratorAccess attached"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "admin_role_admin_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

# ---------------------------------------------------------------------------
# Admin role assumption policy (attached only to the admin group)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_role_assumption" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      aws_iam_role.admin.arn,
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_role_assumption" {
  name        = "${module.this.id}-admin-role-assumption"
  path        = "/"
  description = "Policy allowing assumption of the dedicated admin role with MFA"
  policy      = data.aws_iam_policy_document.admin_role_assumption.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy_attachment" "admin_role_assumption" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_role_assumption.arn
}

# ---------------------------------------------------------------------------
# IAM Users and Group Memberships
# ---------------------------------------------------------------------------

resource "aws_iam_user" "admin_users" {
  for_each = toset(var.admin_users)
  name     = each.key
  path     = "/"
  tags     = module.this.tags
}

resource "aws_iam_user" "non_admin_users" {
  for_each = toset(var.non_admin_users)
  name     = each.key
  path     = "/"
  tags     = module.this.tags
}

resource "aws_iam_group_membership" "admin" {
  name  = "${module.this.id}-admin-membership"
  group = aws_iam_group.admin.name
  users = [for u in var.admin_users : aws_iam_user.admin_users[u].name]
}

resource "aws_iam_group_membership" "non_admin" {
  name  = "${module.this.id}-non-admin-membership"
  group = aws_iam_group.non_admin.name
  users = [for u in var.non_admin_users : aws_iam_user.non_admin_users[u].name]
}

# =============================================================================
# Variables
# =============================================================================

variable "enabled" {
  description = "Main enable toggle for the security group management module"
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Toggle between creating a new security group (true) or using an existing one (false)"
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "ID of an existing security group when create_sg is false"
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID to create the security group in. If null and create_sg is true, a fallback VPC is provisioned"
  type        = string
  default     = null
}

variable "sg_description" {
  description = "Description for the security group"
  type        = string
  default     = "Managed by Terraform security group module"
}

# Label module variables

variable "namespace" {
  description = "Namespace for the label module"
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment for the label module"
  type        = string
  default     = ""
}

variable "stage" {
  description = "Stage for the label module"
  type        = string
  default     = ""
}

variable "name" {
  description = "Name for the label module"
  type        = string
  default     = ""
}

variable "delimiter" {
  description = "Delimiter for the label module"
  type        = string
  default     = "-"
}

variable "attributes" {
  description = "Additional attributes for the label module"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

# Prefix list variables

variable "create_prefix_list" {
  description = "Toggle to create a managed prefix list"
  type        = bool
  default     = true
}

variable "prefix_list_address_family" {
  description = "Address family for the managed prefix list"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries in the managed prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

# Categorized ingress rules

variable "ingress_cidr_rules" {
  description = "Ingress rules based on CIDR blocks"
  type = list(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = []
}

variable "ingress_self_rules" {
  description = "Ingress rules that reference the security group itself"
  type = list(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    protocol    = string
  }))
  default = []
}

variable "ingress_source_sg_rules" {
  description = "Ingress rules based on source security group IDs"
  type = list(object({
    description  = optional(string)
    from_port    = number
    to_port      = number
    protocol     = string
    source_sg_id = string
  }))
  default = []
}

variable "ingress_prefix_list_rules" {
  description = "Ingress rules based on prefix lists. Defaults to the newly created prefix list when prefix_list_id is unspecified"
  type = list(object({
    description    = optional(string)
    from_port      = number
    to_port        = number
    protocol       = string
    prefix_list_id = optional(string)
  }))
  default = []
}

# Categorized egress rules

variable "egress_cidr_rules" {
  description = "Egress rules based on CIDR blocks"
  type = list(object({
    description   = optional(string)
    from_port     = number
    to_port       = number
    protocol      = string
    cidr_blocks   = list(string)
    ipv6_cidr_blocks = optional(list(string))
  }))
  default = []
}

variable "egress_self_rules" {
  description = "Egress rules that reference the security group itself"
  type = list(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    protocol    = string
  }))
  default = []
}

variable "egress_source_sg_rules" {
  description = "Egress rules based on destination security group IDs"
  type = list(object({
    description      = optional(string)
    from_port        = number
    to_port          = number
    protocol         = string
    destination_sg_id = string
  }))
  default = []
}

variable "egress_prefix_list_rules" {
  description = "Egress rules based on prefix lists. Defaults to the newly created prefix list when prefix_list_id is unspecified"
  type = list(object({
    description    = optional(string)
    from_port      = number
    to_port        = number
    protocol       = string
    prefix_list_id = optional(string)
  }))
  default = []
}

# =============================================================================
# Data sources
# =============================================================================

data "aws_availability_zones" "available" {
  state = "available"
}

# =============================================================================
# Label module
# =============================================================================

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  environment = var.environment
  name        = var.name
  delimiter   = var.delimiter
  attributes  = var.attributes
  enabled     = var.enabled
}

# =============================================================================
# Fallback VPC (only when create_sg is true and vpc_id is null)
# =============================================================================

resource "aws_vpc" "this" {
  count = var.enabled && var.create_sg && var.vpc_id == null ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(module.labels.tags, {
    Name = "${module.labels.id}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# Security group (only when create_sg is true)
# =============================================================================

resource "aws_security_group" "this" {
  count = var.enabled && var.create_sg ? 1 : 0

  name        = "${module.labels.id}-sg"
  description = var.sg_description
  vpc_id      = var.vpc_id != null ? var.vpc_id : aws_vpc.this[0].id

  tags = merge(module.labels.tags, {
    Name = "${module.labels.id}-sg"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# Managed prefix list (only when create_prefix_list is true)
# =============================================================================

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enabled && var.create_prefix_list ? 1 : 0

  name           = "${module.labels.id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = try(entry.value.description, null)
    }
  }

  tags = merge(module.labels.tags, {
    Name = "${module.labels.id}-prefix-list"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# Locals for resolved resource IDs
# =============================================================================

locals {
  sg_id          = var.enabled ? (var.create_sg ? aws_security_group.this[0].id : var.existing_sg_id) : null
  prefix_list_id = var.enabled && var.create_prefix_list ? try(aws_ec2_managed_prefix_list.this[0].id, null) : null
}

# =============================================================================
# Ingress rules - CIDR based
# =============================================================================

resource "aws_security_group_rule" "ingress_cidr" {
  for_each = var.enabled ? {
    for idx, rule in var.ingress_cidr_rules : "ingress-cidr-${idx}" => rule
  } : {}

  security_group_id = local.sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
  cidr_blocks       = each.value.cidr_blocks
}

# =============================================================================
# Ingress rules - Self referencing
# =============================================================================

resource "aws_security_group_rule" "ingress_self" {
  for_each = var.enabled ? {
    for idx, rule in var.ingress_self_rules : "ingress-self-${idx}" => rule
  } : {}

  security_group_id = local.sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
  self              = true
}

# =============================================================================
# Ingress rules - Source security group
# =============================================================================

resource "aws_security_group_rule" "ingress_source_sg" {
  for_each = var.enabled ? {
    for idx, rule in var.ingress_source_sg_rules : "ingress-source-sg-${idx}" => rule
  } : {}

  security_group_id        = local.sg_id
  type                     = "ingress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = try(each.value.description, null)
  source_security_group_id = each.value.source_sg_id
}

# =============================================================================
# Ingress rules - Prefix list based (defaults to created prefix list)
# =============================================================================

resource "aws_security_group_rule" "ingress_prefix_list" {
  for_each = var.enabled ? {
    for idx, rule in var.ingress_prefix_list_rules : "ingress-pl-${idx}" => rule
  } : {}

  security_group_id = local.sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
  prefix_list_ids   = [coalesce(each.value.prefix_list_id, local.prefix_list_id)]
}

# =============================================================================
# Egress rules - CIDR based
# =============================================================================

resource "aws_security_group_rule" "egress_cidr" {
  for_each = var.enabled ? {
    for idx, rule in var.egress_cidr_rules : "egress-cidr-${idx}" => rule
  } : {}

  security_group_id = local.sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
  cidr_blocks       = each.value.cidr_blocks
  ipv6_cidr_blocks  = try(each.value.ipv6_cidr_blocks, null)
}

# =============================================================================
# Egress rules - Self referencing
# =============================================================================

resource "aws_security_group_rule" "egress_self" {
  for_each = var.enabled ? {
    for idx, rule in var.egress_self_rules : "egress-self-${idx}" => rule
  } : {}

  security_group_id = local.sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
  self              = true
}

# =============================================================================
# Egress rules - Destination security group
# =============================================================================

resource "aws_security_group_rule" "egress_source_sg" {
  for_each = var.enabled ? {
    for idx, rule in var.egress_source_sg_rules : "egress-source-sg-${idx}" => rule
  } : {}

  security_group_id        = local.sg_id
  type                     = "egress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = try(each.value.description, null)
  source_security_group_id = each.value.destination_sg_id
}

# =============================================================================
# Egress rules - Prefix list based (defaults to created prefix list)
# =============================================================================

resource "aws_security_group_rule" "egress_prefix_list" {
  for_each = var.enabled ? {
    for idx, rule in var.egress_prefix_list_rules : "egress-pl-${idx}" => rule
  } : {}

  security_group_id = local.sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
  prefix_list_ids   = [coalesce(each.value.prefix_list_id, local.prefix_list_id)]
}

# ------------------------------------------------------------------------------
# Data sources – static provider metadata only
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/1.30/amazon-linux-2/recommended/image_id"
}

# ------------------------------------------------------------------------------
# KMS key for EKS secret encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "eks" {
  description         = "EKS cluster secret encryption key"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEKSClusterRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster.arn
        }
        Action = [
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowEKSViaService"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Decrypt",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "eks.${data.aws_region.current.region}.amazonaws.com"
          }
        }
      },
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Networking – VPC, subnets, IGW, NAT
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "demo-eks-vpc"
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demo-eks-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "demo-eks-public"
  }
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet("10.0.0.0/16", 4, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "demo-eks-private-${data.aws_availability_zones.available.names[count.index]}"
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "demo-eks-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "demo-eks-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "demo-eks-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# IAM – EKS cluster role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

# ------------------------------------------------------------------------------
# IAM – EKS worker node role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "eks_node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_read" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Allow the node role to signal the CloudFormation stack
resource "aws_iam_role_policy" "node_cfn_signal" {
  role = aws_iam_role.eks_node.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "cloudformation:SignalResource"
        Resource = "arn:${data.aws_partition.current.partition}:cloudformation:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:stack/eks-cluster-stack/*"
      },
    ]
  })
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.eks_node.name
}

# ------------------------------------------------------------------------------
# Security groups
# ------------------------------------------------------------------------------
resource "aws_security_group" "control_plane" {
  name        = "demo-eks-control-plane-sg"
  description = "Security group for EKS control plane ENIs"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-control-plane-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "cp_from_node_443" {
  security_group_id = aws_security_group.control_plane.id
  referenced_security_group_id = aws_security_group.node.id
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "cp_from_node_1025" {
  security_group_id = aws_security_group.control_plane.id
  referenced_security_group_id = aws_security_group.node.id
  from_port         = 1025
  to_port           = 65535
  ip_protocol       = "tcp"
}

resource "aws_security_group" "node" {
  name        = "demo-eks-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-node-sg"
  }
}

# Unrestricted internal communication between nodes
resource "aws_vpc_security_group_ingress_rule" "node_self" {
  security_group_id            = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.node.id
  from_port                    = 0
  to_port                      = 0
  ip_protocol                  = "-1"
}

# Ingress from control plane – port 443
resource "aws_vpc_security_group_ingress_rule" "node_from_cp_443" {
  security_group_id = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.control_plane.id
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

# Ingress from control plane – ports 1025-65535
resource "aws_vpc_security_group_ingress_rule" "node_from_cp_1025" {
  security_group_id = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.control_plane.id
  from_port         = 1025
  to_port           = 65535
  ip_protocol       = "tcp"
}

# Outbound traffic only within VPC CIDR
resource "aws_vpc_security_group_egress_rule" "node_to_vpc" {
  security_group_id = aws_security_group.node.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 0
  to_port           = 0
  ip_protocol       = "-1"
}

# Egress to control plane – port 443
resource "aws_vpc_security_group_egress_rule" "node_to_cp_443" {
  security_group_id = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.control_plane.id
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

# Egress to control plane – ports 1025-65535
resource "aws_vpc_security_group_egress_rule" "node_to_cp_1025" {
  security_group_id = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.control_plane.id
  from_port         = 1025
  to_port           = 65535
  ip_protocol       = "tcp"
}

# ------------------------------------------------------------------------------
# TLS private key and AWS key pair
# ------------------------------------------------------------------------------
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_sensitive_file" "eks_private_key" {
  content  = tls_private_key.eks.private_key_pem
  filename = pathexpand("eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
}

# ------------------------------------------------------------------------------
# EKS cluster
# ------------------------------------------------------------------------------
resource "aws_eks_cluster" "main" {
  name     = "demo-eks"
  role_arn = aws_iam_role.eks_cluster.arn
  version  = "1.30"

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
    security_group_ids      = [aws_security_group.control_plane.id]
  }

  access_config {
    authentication_mode                      = "API_AND_CONFIG_MAP"
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# EC2 Launch Template for worker nodes
# ------------------------------------------------------------------------------
locals {
  node_user_data = base64encode(<<-EOF
#!/bin/bash
set -ex

/etc/eks/bootstrap.sh demo-eks

TOKEN=$(curl -s -X PUT "http://169.254.169.254/latest/api/token" \
  -H "X-aws-ec2-metadata-token-ttl-seconds: 21600")
INSTANCE_ID=$(curl -s -H "X-aws-ec2-metadata-token: $TOKEN" \
  http://169.254.169.254/latest/meta-data/instance-id)
REGION=$(curl -s -H "X-aws-ec2-metadata-token: $TOKEN" \
  http://169.254.169.254/latest/meta-data/placement/region)

aws cloudformation signal-resource \
  --stack-name eks-cluster-stack \
  --logical-resource-id NodeGroup \
  --unique-id "$INSTANCE_ID" \
  --status SUCCESS \
  --region "$REGION"
EOF
  )
}

resource "aws_launch_template" "node" {
  name_prefix   = "eks-demo-node-"
  instance_type = "t3.medium"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  key_name      = aws_key_pair.eks.key_name

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 30
      volume_type = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_node.name
  }

  vpc_security_group_ids = [aws_security_group.node.id]

  user_data = local.node_user_data

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "eks-demo-node"
    }
  }
}

# ------------------------------------------------------------------------------
# 30-second delay to allow launch template to settle
# ------------------------------------------------------------------------------
resource "time_sleep" "launch_template_settle" {
  create_duration = "30s"

  depends_on = [aws_launch_template.node]
}

# ------------------------------------------------------------------------------
# CloudFormation stack – Auto Scaling Group
# ------------------------------------------------------------------------------
resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name         = "eks-cluster-stack"
  capabilities = ["CAPABILITY_IAM"]

  template_body = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Resources = {
      NodeGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"
        Properties = {
          LaunchTemplate = {
            LaunchTemplateId = aws_launch_template.node.id
            Version          = aws_launch_template.node.latest_version
          }
          VPCZoneIdentifier = [for s in aws_subnet.private : s.id]
          MinSize           = "1"
          MaxSize           = "4"
          DesiredCapacity   = "3"
        }
        CreationPolicy = {
          ResourceSignal = {
            Count   = 3
            Timeout = "PT15M"
          }
        }
        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
          }
        }
      }
    }
    Outputs = {
      AutoScalingGroupID = {
        Value = { Ref = "NodeGroup" }
      }
    }
  })

  depends_on = [time_sleep.launch_template_settle]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "node_instance_role_arn" {
  description = "ARN of the EKS worker node IAM role"
  value       = aws_iam_role.eks_node.arn
}

output "node_security_group_id" {
  description = "ID of the EKS worker node security group"
  value       = aws_security_group.node.id
}

output "auto_scaling_group_id" {
  description = "Auto Scaling Group ID provisioned by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["AutoScalingGroupID"]
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# Provider alias for the replica (DR) region
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "stacks" {
  description = "Map of EKS stack names to their deployment regions"
  type        = map(string)
  default = {
    "dev"     = "us-east-1"
    "staging" = "us-west-2"
    "prod"    = "eu-west-1"
  }
}

variable "replica_region" {
  description = "AWS region for the replica (DR) S3 bucket"
  type        = string
  default     = "us-west-2"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  tags = {
    Environment           = "state-management"
    ManagedBy             = "terraform"
    Service               = "terraform-backend"
    Component             = "state-storage"
    SecurityCompliance    = "encrypted-replicated"
  }
}

# ============================================================================
# PRIMARY REGION (us-east-1) — KMS Key & S3 Bucket
# ============================================================================

resource "aws_kms_key" "primary" {
  description             = "Custom KMS key for primary S3 backend SSE — 7-day deletion window, automatic rotation"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.tags
}

resource "aws_kms_alias" "primary" {
  name          = "alias/terraform-state-backend-primary"
  target_key_id = aws_kms_key.primary.id
}

resource "aws_s3_bucket" "primary" {
  bucket = "terraform-state-backend-${local.account_id}"
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_iam_policy_document" "primary_bucket_policy" {
  statement {
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_bucket_policy.json
}

# ============================================================================
# REPLICA REGION — KMS Key & S3 Bucket
# ============================================================================

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "Custom KMS key for replica S3 bucket SSE"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.tags
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/terraform-state-backend-replica"
  target_key_id = aws_kms_key.replica.id
}

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = "terraform-state-backend-replica-${local.account_id}"
  tags     = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_iam_policy_document" "replica_bucket_policy" {
  statement {
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_bucket_policy.json
}

# ============================================================================
# CROSS-REGION REPLICATION — IAM Role & Replication Configuration
# ============================================================================

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
  tags               = local.tags
}

data "aws_iam_policy_document" "replication_policy" {
  statement {
    sid    = "ReadSourceBucket"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "ReadSourceObjects"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "ReplicateToDestination"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid    = "DecryptWithSourceKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
    ]
    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "EncryptWithDestinationKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "s3-cross-region-replication-policy"
  role   = aws_iam_role.replication.name
  policy = data.aws_iam_policy_document.replication_policy.json
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ============================================================================
# DYNAMODB TABLES — Per-Stack State Locking (PAY_PER_REQUEST)
# ============================================================================

resource "aws_dynamodb_table" "state_lock" {
  for_each = var.stacks

  name         = "terraform-state-lock-${each.key}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ============================================================================
# STACK-SPECIFIC IAM POLICIES
# ============================================================================

resource "aws_iam_policy" "stack_state" {
  for_each = var.stacks

  name        = "terraform-state-policy-${each.key}"
  description = "Grant ${each.key} stack access to its DynamoDB table, S3 prefix, and KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBLockAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable",
        ]
        Resource = aws_dynamodb_table.state_lock[each.key].arn
      },
      {
        Sid    = "S3StateAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/eks-stacks/${each.key}/*",
        ]
      },
      {
        Sid    = "KMSEncryptDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.primary.arn
      },
    ]
  })
}

# ============================================================================
# LOCAL BACKEND CONFIG FILES — One per stack in eks-stacks/
# ============================================================================

resource "local_file" "backend_config" {
  for_each = var.stacks

  filename = "eks-stacks/${each.key}/backend.tf"
  content  = <<-EOF
terraform {
  backend "s3" {
    bucket         = "${aws_s3_bucket.primary.id}"
    key            = "eks-stacks/${each.key}/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
    encrypt        = true
    kms_key_id     = "${aws_kms_key.primary.arn}"
  }
}
EOF
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

resource "random_pet" "name" {
  length = 2
}

locals {
  name = random_pet.name.id
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group for API Gateway access logs
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "api_gw" {
  name              = "/aws/apigateway/${local.name}"
  retention_in_days = 1

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key for SQS queue encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sqs" {
  description             = "KMS key for SQS queue ${local.name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SQS Service"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${local.name}-sqs"
  target_key_id = aws_kms_key.sqs.id
}

# ---------------------------------------------------------------------------
# SQS Queue
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "this" {
  name                      = local.name
  kms_master_key_id         = aws_kms_key.sqs.id
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM execution role for API Gateway
# ---------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway" {
  name = "${local.name}-api-gateway"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway" {
  name = "${local.name}-api-gateway-policy"
  role = aws_iam_role.api_gateway.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SQSSendMessage"
        Effect = "Allow"
        Action = "sqs:SendMessage"
        Resource = aws_sqs_queue.this.arn
      },
      {
        Sid    = "KMSEncryptDecrypt"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ],
        Resource = aws_kms_key.sqs.arn
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ],
        Resource = aws_cloudwatch_log_group.api_gw.arn
      },
      {
        Sid    = "CloudWatchLogsStreamAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ],
        Resource = "${aws_cloudwatch_log_group.api_gw.arn}:log-stream:*"
      },
      {
        Sid    = "CloudWatchAllLogGroups"
        Effect = "Allow"
        Action = [
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ],
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# API Gateway v2 – WebSocket API
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_api" "ws" {
  name                       = local.name
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# ----- Integrations -------------------------------------------------------

# Connect route – mock integration returning 200
resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "MOCK"

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "$default"

  response_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

# Default route – AWS integration sending raw message body to SQS
resource "aws_apigatewayv2_integration" "default" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.this.name}"
  credentials_arn  = aws_iam_role.api_gateway.arn
  passthrough_behavior = "WHEN_NO_TEMPLATES"

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$util.urlEncode($input.body)"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "$default"
}

# Disconnect route – AWS integration sending "Client disconnected" to SQS
resource "aws_apigatewayv2_integration" "disconnect" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.this.name}"
  credentials_arn  = aws_iam_role.api_gateway.arn
  passthrough_behavior = "WHEN_NO_TEMPLATES"

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client%20disconnected"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_integration_response" "disconnect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.disconnect.id
  integration_response_key = "$default"
}

# ----- Routes --------------------------------------------------------------

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

# ----- Deployment & Stage --------------------------------------------------

resource "aws_apigatewayv2_deployment" "ws" {
  api_id = aws_apigatewayv2_api.ws.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_apigatewayv2_integration.connect.id,
      aws_apigatewayv2_integration.default.id,
      aws_apigatewayv2_integration.disconnect.id,
      aws_apigatewayv2_route.connect.id,
      aws_apigatewayv2_route.default.id,
      aws_apigatewayv2_route.disconnect.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.ws.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gw.arn
    format = jsonencode({
      requestId        = "$context.requestId"
      ip               = "$context.identity.sourceIp"
      requestTime      = "$context.requestTime"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      responseLatency  = "$context.responseLatency"
      integrationError = "$context.integrationErrorMessage"
    })
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "websocket_endpoint" {
  description = "Full WebSocket endpoint URL including stage"
  value       = "${aws_apigatewayv2_api.ws.api_endpoint}/${aws_apigatewayv2_stage.dev.name}"
}

output "queue_arn" {
  description = "ARN of the SQS queue"
  value       = aws_sqs_queue.this.arn
}

output "kms_key_id" {
  description = "KMS key ID"
  value       = aws_kms_key.sqs.id
}

variable "bucket_name_primary" {
  description = "Name of the primary S3 bucket (without suffix)"
  type        = string
  default     = "example1"
}

variable "bucket_name_secondary" {
  description = "Name of the secondary S3 bucket (without suffix)"
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the Multi-Region Access Point"
  type        = string
  default     = "example-mrap"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# Provider alias for the secondary region (us-west-2) which is required for
# Multi-Region Access Point control-plane operations.
provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

# ---------------------------------------------------------------------------
# KMS keys – one customer-managed key per bucket, both with automatic rotation
# ---------------------------------------------------------------------------

resource "aws_kms_key" "primary" {
  description             = "KMS key for primary S3 bucket (us-east-1)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "secondary" {
  provider                = aws.us_west_2
  description             = "KMS key for secondary S3 bucket (us-west-2)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Primary S3 bucket (us-east-1)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  bucket = "${var.bucket_name_primary}-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# Secondary S3 bucket (us-west-2)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2
  bucket   = "${var.bucket_name_secondary}-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider   = aws.us_west_2
  bucket     = aws_s3_bucket.secondary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider                = aws.us_west_2
  bucket                  = aws_s3_bucket.secondary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# Replication IAM role and policy
# ---------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  name = "s3-replication-role-mrap"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceRead"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*"
    ]
  }

  statement {
    sid    = "DestinationReplicate"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [
      aws_s3_bucket.secondary.arn,
      "${aws_s3_bucket.secondary.arn}/*"
    ]
  }

  statement {
    sid    = "SourceKeyDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      aws_kms_key.primary.arn
    ]
  }

  statement {
    sid    = "DestinationKeyEncrypt"
    effect = "Allow"
    actions = [
      "kms:Encrypt"
    ]
    resources = [
      aws_kms_key.secondary.arn
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name   = "s3-replication-policy-mrap"
  policy = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------------------------------------------------------------------
# Replication configuration on primary bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replication-to-secondary"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Multi-Region Access Point (managed from us-west-2)
# ---------------------------------------------------------------------------

resource "aws_s3control_multi_region_access_point" "main" {
  provider   = aws.us_west_2
  account_id = data.aws_caller_identity.current.account_id

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "main" {
  provider   = aws.us_west_2
  account_id = data.aws_caller_identity.current.account_id

  details {
    name = aws_s3control_multi_region_access_point.main.name
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "AllowOwnAccountGetPut"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = [
            "arn:${data.aws_partition.current.partition}:s3::${data.aws_caller_identity.current.account_id}:accesspoint/${aws_s3control_multi_region_access_point.main.name}/object/*"
          ]
          Principal = {
            AWS = data.aws_caller_identity.current.account_id
          }
        }
      ]
    })
  }
}

locals {
  # Lambda assume role policy
  lambda_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Shared customer-managed policy: CloudWatch Logs write permissions
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Grants CloudWatch Logs write permissions for Lambda functions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Create DynamoDB Backup Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = local.lambda_assume_role_policy
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creation of DynamoDB backups"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:CreateBackup"
        ]
        Resource = "arn:aws:dynamodb:*:*:table/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_policy_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_lambda_logging_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# ---------------------------------------------------------------------------
# Remove (List & Delete) DynamoDB Backup Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = local.lambda_assume_role_policy
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deleting DynamoDB backups"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:ListBackups",
          "dynamodb:DeleteBackup"
        ]
        Resource = "arn:aws:dynamodb:*:*:table/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_policy_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_lambda_logging_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "create_ddb_backup_role_arn" {
  description = "ARN of the create_ddb_backup_role"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the create_ddb_backup_role"
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the remove_ddb_backup_role"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the remove_ddb_backup_role"
  value       = aws_iam_role.remove_ddb_backup_role.name
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "projectvpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "projectvpc-public"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "projectvpc-private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "projectvpc-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "projectvpc-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "projectvpc-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "projectvpc-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "projectvpc-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer-managed key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup"
  target_key_id = aws_kms_key.endpoint_backup.id
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup.json
}

data "aws_iam_policy_document" "endpoint_backup" {
  statement {
    sid    = "DenyInsecureTransports"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      "arn:aws:s3:::${local.bucket_name}",
      "arn:aws:s3:::${local.bucket_name}/*",
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceLockOver90Days"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]
    resources = [
      "arn:aws:s3:::${local.bucket_name}/*",
    ]
    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }
    condition {
      test     = "DateGreaterThan"
      variable = "s3:object-lock-retain-until-date"
      values   = ["$${aws:CurrentTime + 90d}"]
    }
  }
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grants list, read, write, delete, version, retention, and restore access to the endpoint-backup S3 bucket and decrypt/data-key access on the S3 KMS key"
  policy      = data.aws_iam_policy_document.endpoint_backup_bucket_access.json
}

data "aws_iam_policy_document" "endpoint_backup_bucket_access" {
  statement {
    sid    = "S3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:PutObjectRetention",
      "s3:RestoreObject",
    ]
    resources = [
      "arn:aws:s3:::${local.bucket_name}",
      "arn:aws:s3:::${local.bucket_name}/*",
    ]
  }

  statement {
    sid    = "KMSDecryptDataKeyAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [
      aws_kms_key.endpoint_backup.arn,
    ]
  }
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

# ---------------------------------------------------------------------------
# Providers – multi-region aliases
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "ap-southeast-1"
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Source bucket names
  src1_buckets = toset(["log1a.veerum-${local.account_id}", "log1b.veerum-${local.account_id}"])
  src2_buckets = toset(["log2a.veerum-${local.account_id}", "log2b.veerum-${local.account_id}"])

  # Replica bucket names – region 1 (eu-west-1)
  repl1_buckets = toset([
    "log1a.veerum-replica1-${local.account_id}",
    "log1b.veerum-replica1-${local.account_id}",
    "log2a.veerum-replica1-${local.account_id}",
    "log2b.veerum-replica1-${local.account_id}",
  ])

  # Replica bucket names – region 2 (ap-southeast-1)
  repl2_buckets = toset([
    "log1a.veerum-replica2-${local.account_id}",
    "log1b.veerum-replica2-${local.account_id}",
    "log2a.veerum-replica2-${local.account_id}",
    "log2b.veerum-replica2-${local.account_id}",
  ])

  # All replica bucket names (for IAM policy)
  all_replica_buckets = concat(tolist(local.repl1_buckets), tolist(local.repl2_buckets))
}

# ---------------------------------------------------------------------------
# KMS keys
# ---------------------------------------------------------------------------

# Source 1 region (us-east-1) – default provider
resource "aws_kms_key" "sourcekey1" {
  description             = "Source key 1 – us-east-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "sourcekey1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.sourcekey1.id
}

# Source 2 region (us-west-2)
resource "aws_kms_key" "sourcekey2" {
  provider                = aws.source2
  description             = "Source key 2 – us-west-2"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "sourcekey2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.sourcekey2.id
}

# Replica 1 region (eu-west-1)
resource "aws_kms_key" "replicakey1" {
  provider              = aws.replica1
  description           = "Replica key 1 – eu-west-1"
  deletion_window_in_days = 30
  enable_key_rotation   = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "replicakey1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replicakey1.id
}

# Replica 2 region (ap-southeast-1)
resource "aws_kms_key" "replicakey2" {
  provider              = aws.replica2
  description           = "Replica key 2 – ap-southeast-1"
  deletion_window_in_days = 30
  enable_key_rotation   = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "replicakey2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replicakey2.id
}

# ---------------------------------------------------------------------------
# IAM role and policy for replication
# ---------------------------------------------------------------------------
resource "aws_iam_role" "s3_replication" {
  name = "s3-cross-region-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = {
    Env = "dev"
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Permissions for cross-region S3 replication across four regions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadSourceBuckets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket",
          "s3:ListBucketVersions",
        ]
        Resource = concat(
          [for b in tolist(local.src1_buckets) : "arn:aws:s3:::${b}"],
          [for b in tolist(local.src1_buckets) : "arn:aws:s3:::${b}/*"],
          [for b in tolist(local.src2_buckets) : "arn:aws:s3:::${b}"],
          [for b in tolist(local.src2_buckets) : "arn:aws:s3:::${b}/*"],
        )
      },
      {
        Sid    = "WriteReplicaBuckets"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectRetention",
          "s3:GetObjectLegalHold",
        ]
        Resource = concat(
          [for b in local.all_replica_buckets : "arn:aws:s3:::${b}"],
          [for b in local.all_replica_buckets : "arn:aws:s3:::${b}/*"],
        )
      },
      {
        Sid    = "DecryptSourceKeys"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
        ]
        Resource = [
          aws_kms_key.sourcekey1.arn,
          aws_kms_key.sourcekey2.arn,
        ]
      },
      {
        Sid    = "EncryptReplicaKeys"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
        ]
        Resource = [
          aws_kms_key.replicakey1.arn,
          aws_kms_key.replicakey2.arn,
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

# ---------------------------------------------------------------------------
# Source S3 buckets – Source 1 (us-east-1, default provider)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "src1_log1a" {
  bucket = "log1a.veerum-${local.account_id}"

  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket" "src1_log1b" {
  bucket = "log1b.veerum-${local.account_id}"

  tags = {
    Env = "dev"
  }
}

# Source 1 versioning
resource "aws_s3_bucket_versioning" "src1_log1a" {
  bucket = aws_s3_bucket.src1_log1a.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "src1_log1b" {
  bucket = aws_s3_bucket.src1_log1b.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Source 1 public access blocks
resource "aws_s3_bucket_public_access_block" "src1_log1a" {
  bucket                = aws_s3_bucket.src1_log1a.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "src1_log1b" {
  bucket                = aws_s3_bucket.src1_log1b.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Source 1 SSE-KMS encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "src1_log1a" {
  bucket = aws_s3_bucket.src1_log1a.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sourcekey1.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "src1_log1b" {
  bucket = aws_s3_bucket.src1_log1b.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sourcekey1.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# Source 1 lifecycle (abort incomplete multipart uploads)
resource "aws_s3_bucket_lifecycle_configuration" "src1_log1a" {
  bucket = aws_s3_bucket.src1_log1a.id

  rule {
    id     = "abort-incomplete-multipart-upload"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "src1_log1b" {
  bucket = aws_s3_bucket.src1_log1b.id

  rule {
    id     = "abort-incomplete-multipart-upload"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# ---------------------------------------------------------------------------
# Source S3 buckets – Source 2 (us-west-2, provider aws.source2)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "src2_log2a" {
  provider = aws.source2
  bucket   = "log2a.veerum-${local.account_id}"

  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket" "src2_log2b" {
  provider = aws.source2
  bucket   = "log2b.veerum-${local.account_id}"

  tags = {
    Env = "dev"
  }
}

# Source 2 versioning
resource "aws_s3_bucket_versioning" "src2_log2a" {
  provider = aws.source2
  bucket   = aws_s3_bucket.src2_log2a.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "src2_log2b" {
  provider = aws.source2
  bucket   = aws_s3_bucket.src2_log2b.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Source 2 public access blocks
resource "aws_s3_bucket_public_access_block" "src2_log2a" {
  provider              = aws.source2
  bucket                = aws_s3_bucket.src2_log2a.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
