# ---------------------------------------------------------------------------
# Replication configuration – Source 1 buckets (us-east-1)
# Each source bucket has two rules: one to replica1, one to replica2
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "src1_log1a" {
  bucket = aws_s3_bucket.src1_log1a.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "ReplicateToReplica1"
    status = "Enabled"

    filter {
      prefix = ""
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = "arn:aws:s3:::log1a.veerum-replica1-${local.account_id}"
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey1.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id     = "ReplicateToReplica2"
    status = "Enabled"

    filter {
      prefix = ""
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = "arn:aws:s3:::log1a.veerum-replica2-${local.account_id}"
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey2.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.src1_log1a,
    aws_iam_role_policy_attachment.s3_replication,
  ]
}

